window.lessonsHSK1 = [{"emoji":"👋","grammar":[],"han":"AI小语，你好！","natural":["Mạch ý: chào hỏi ở văn phòng, chào hỏi trên lớp, rồi cảm ơn và tạm biệt trên lớp, cuối bài là bài vè luyện phát âm, tất cả đều diễn ra trong ngày đầu tiên của năm học.","Phân biệt 你, 你们 và 您: 你 nói với một người quen, 你们 nói với nhiều người, 您 nói với thầy cô hoặc người lớn tuổi.","Khi nghe, chú ý hậu tố 们 sau danh từ chỉ người và cặp lời nói 谢谢, 不客气 luôn đi cùng nhau."],"num":1,"photoPrefix":"h1-1","pinyin":"AI Xiǎoyǔ, nǐ hǎo!","structures":[{"han":"AI小语，你好！","pinyin":"AI Xiǎoyǔ, nǐ hǎo!","meaning":"Chào AI Tiểu Ngữ!","note":"你好 là lời chào cơ bản nhất, đặt trước tên người được chào, dùng được trong hầu hết các tình huống gặp mặt."},{"han":"老师，您好！","pinyin":"Lǎoshī, nín hǎo!","meaning":"Chào thầy (cô) ạ!","note":"您 là đại từ xưng hô kính trọng, sách ghi rõ dùng với người lớn tuổi hoặc người đáng kính, khác với 你 dùng với bạn bè."},{"han":"同学们，再见！","pinyin":"Tóngxuémen, zàijiàn!","meaning":"Tạm biệt các bạn học!","note":"们 đặt sau danh từ chỉ người để chỉ số nhiều, 同学们 là cả nhóm bạn học, còn 再见 là lời tạm biệt."},{"han":"妈种麻，我放马。马吃麻，妈骂马。","pinyin":"","meaning":"Mẹ trồng gai dầu, tôi thả ngựa. Ngựa ăn gai dầu, mẹ mắng ngựa.","note":"Bài vè chơi chữ với cùng một âm tiết ma ở bốn thanh điệu khác nhau: mā (mẹ), má (gai dầu), mǎ (ngựa), mà (mắng), nên đọc nhanh rất dễ lẫn thanh điệu, luyện phát âm chuẩn từng thanh."},{"han":"谢谢！不客气！","pinyin":"Xièxie! Bú kèqi!","meaning":"Cảm ơn! Không có gì!","note":""}],"theme":"Chào hỏi, cảm ơn và tạm biệt","translation":"Chào AI Tiểu Ngữ!","vocab":[{"emoji":"👋","example":"你好，小语！","examplePinyin":"Nǐ hǎo, Xiǎoyǔ!","exampleVi":"Chào Tiểu Ngữ!","meaning":"xin chào","pinyin":"nǐ hǎo","pos":"Cụm từ","word":"你好"},{"emoji":"👩‍🏫","example":"王老师，你好！","examplePinyin":"Wáng lǎoshī, nǐ hǎo!","exampleVi":"Chào cô Vương!","meaning":"cô Vương (cách gọi cô giáo họ Vương)","pinyin":"Wáng lǎoshī","pos":"Danh từ riêng","word":"王老师"},{"emoji":"👥","example":"大家好！","examplePinyin":"Dàjiā hǎo!","exampleVi":"Chào mọi người!","meaning":"mọi người, tất cả mọi người","pinyin":"dàjiā","pos":"Đại từ","word":"大家"},{"emoji":"👍","example":"你好！","examplePinyin":"Nǐ hǎo!","exampleVi":"Chào bạn!","meaning":"tốt, khỏe","pinyin":"hǎo","pos":"Tính từ","word":"好"},{"emoji":"🎒","example":"我是学生。","examplePinyin":"Wǒ shì xuéshēng.","exampleVi":"Tôi là học sinh.","meaning":"học sinh, sinh viên","pinyin":"xuéshēng","pos":"Danh từ","word":"学生"},{"emoji":"👥","example":"同学们，再见！","examplePinyin":"Tóngxuémen, zàijiàn!","exampleVi":"Tạm biệt các bạn học!","meaning":"hậu tố chỉ số nhiều sau đại từ hoặc danh từ chỉ người","pinyin":"men","pos":"Hậu tố","word":"们"},{"emoji":"👩‍🏫","example":"老师，您好！","examplePinyin":"Lǎoshī, nín hǎo!","exampleVi":"Chào thầy (cô) ạ!","meaning":"thầy giáo, cô giáo","pinyin":"lǎoshī","pos":"Danh từ","word":"老师"},{"emoji":"🙏","example":"老师，您好！","examplePinyin":"Lǎoshī, nín hǎo!","exampleVi":"Chào thầy (cô) ạ!","meaning":"ngài, bạn (cách xưng hô kính trọng)","pinyin":"nín","pos":"Đại từ","word":"您"},{"emoji":"👥","example":"你们好！","examplePinyin":"Nǐmen hǎo!","exampleVi":"Chào các bạn!","meaning":"các bạn","pinyin":"nǐmen","pos":"Đại từ","word":"你们"},{"emoji":"🙏","example":"谢谢！","examplePinyin":"Xièxie!","exampleVi":"Cảm ơn!","meaning":"cảm ơn","pinyin":"xièxie","pos":"Động từ","word":"谢谢"},{"emoji":"😊","example":"不客气！","examplePinyin":"Bú kèqi!","exampleVi":"Không có gì!","meaning":"không có gì, đừng khách sáo","pinyin":"bú kèqi","pos":"Cụm từ","word":"不客气"},{"emoji":"🧑‍🤝‍🧑","example":"同学们，再见！","examplePinyin":"Tóngxuémen, zàijiàn!","exampleVi":"Tạm biệt các bạn học!","meaning":"bạn học","pinyin":"tóngxué","pos":"Danh từ","word":"同学"},{"emoji":"👋","example":"老师，再见！","examplePinyin":"Lǎoshī, zàijiàn!","exampleVi":"Tạm biệt thầy (cô) ạ!","meaning":"tạm biệt","pinyin":"zàijiàn","pos":"Động từ","word":"再见"}],"phonetics":{"audio":"h1-phon-1.mp3","sections":[{"table":{"headers":["声母","韵母","声调","音节","例字"],"headersVi":["Thanh mẫu","Vận mẫu","Thanh điệu","Âm tiết","Chữ Hán"],"rows":[["b","a","ˉ","bā","八"],["b","a","ˊ","bá","拔"],["b","a","ˇ","bǎ","把"],["b","a","ˋ","bà","爸"],["","a","ˉ","ā","阿"],["","a","ˊ","á","啊"]]},"text":"汉语一个汉字通常对应一个音节，汉语字音节一般由声母、韵母和声调组成，有时由韵母和声调组成。例如：","textVi":"Trong tiếng Trung Quốc, mỗi chữ Hán thường tương ứng với một âm tiết. Một âm tiết tiếng Trung Quốc thường bao gồm thanh mẫu, vận mẫu và thanh điệu, đôi khi chỉ bao gồm vận mẫu và thanh điệu. Ví dụ:","title":"汉语音节","titleVi":"Âm tiết tiếng Trung Quốc","track":"1-1","words":[{"han":"茶","py":"chá","vi":"trà"},{"han":"狗","py":"gǒu","vi":"chó"},{"han":"猫","py":"māo","vi":"mèo"},{"han":"菜","py":"cài","vi":"món ăn"},{"han":"杯子","py":"bēizi","vi":"cái cốc"},{"han":"学生","py":"xuésheng","vi":"học sinh, sinh viên"},{"han":"老师","py":"lǎoshī","vi":"thầy giáo, cô giáo"},{"han":"鸡蛋","py":"jīdàn","vi":"trứng gà"}]},{"table":{"headers":["声母","韵母"],"headersVi":["Thanh mẫu","Vận mẫu"],"rows":[["b p m f","a o e i [i] u er"],["d t n l","ai ei ao ou"],["g k h","an en"],["","ang eng ong"]]},"text":"汉语声母和韵母拼合组成音节，但是声母和韵母不是都能相拼的。\n在下方表格列举的部分声母中，除了声母“n、l”，其他声母都不能和韵母“ü”及“ü”开头的韵母相拼。另外，声母“b、p、f”不和韵母“e”相拼；声母“f、g、k、h”不和韵母“i”相拼。\n韵母“er”不和任何声母相拼，而是单独作为一个音节。","textVi":"Trong tiếng Trung Quốc, thanh mẫu và vận mẫu kết hợp với nhau tạo thành âm tiết, nhưng không phải tất cả các thanh mẫu và vận mẫu đều có thể ghép với nhau.\nTrong số các thanh mẫu được liệt kê ở bảng dưới đây, chỉ có thanh mẫu “n, l” ghép được với vận mẫu “ü” và các vận mẫu bắt đầu bằng “ü”. Ngoài ra, các thanh mẫu “b, p, f” không ghép với vận mẫu “e”; các thanh mẫu “f, g, k, h” không ghép với vận mẫu “i”.\nVận mẫu “er” không ghép với bất kỳ thanh mẫu nào mà đứng độc lập tạo thành một âm tiết.","title":"声母和韵母（1）","titleVi":"Thanh mẫu và vận mẫu (1)"},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["ā","á","ǎ","à","ē","é","ě","è","ér","ěr","èr","dā","dá","dǎ","dà","kē","ké","kě","kè"]},"text":"汉语有4个基本声调，包括第一声（55）、第二声（35）、第三声（214）和第四声（51），也称一声、二声、三声、四声。声调要标在韵母的主要元音上。声调不同，意义也不同。","textVi":"Tiếng Trung Quốc có 4 thanh điệu cơ bản, bao gồm thanh thứ nhất (55), thanh thứ hai (35), thanh thứ ba (214) và thanh thứ tư (51), hay còn gọi là thanh 1, thanh 2, thanh 3, thanh 4. Dấu thanh điệu phải được đặt trên nguyên âm chính của vận mẫu. Thanh điệu khác nhau, ý nghĩa cũng khác nhau.","title":"声调","titleVi":"Thanh điệu","words":[{"han":"口","py":"kǒu","vi":"(lượng từ cho số người trong gia đình)"},{"han":"饭","py":"fàn","vi":"bữa ăn, cơm"},{"han":"喝","py":"hē","vi":"uống"},{"han":"二","py":"èr","vi":"hai (số 2)"},{"han":"你好","py":"nǐ hǎo","vi":"xin chào"},{"han":"朋友","py":"péngyou","vi":"bạn bè"},{"han":"面包","py":"miànbāo","vi":"bánh mì"},{"han":"妹妹","py":"mèimei","vi":"em gái"},{"han":"房间","py":"fángjiān","vi":"phòng"},{"han":"白天","py":"báitiān","vi":"ban ngày"},{"han":"饭店","py":"fàndiàn","vi":"nhà hàng"},{"han":"电脑","py":"diànnǎo","vi":"máy tính"}]}]}},{"emoji":"🙋","grammar":[{"error":"Đừng xếp tân ngữ lên trước vị ngữ kiểu 我陈天中叫, tiếng Hán không nói như vậy.","examples":"你叫什么名字？ (Nǐ jiào shénme míngzi?) — Bạn tên là gì? 我叫白家月。 (Wǒ jiào Bái Jiāyuè.) — Tôi tên là Bạch Gia Nguyệt. 我是学生。 (Wǒ shì xuéshēng.) — Tôi là học sinh.","explain":"Câu tiếng Hán xếp theo thứ tự chủ ngữ đứng trước, vị ngữ ở giữa, tân ngữ đứng sau. Ví dụ: 我 là chủ ngữ, 叫 là vị ngữ, 陈天中 là tân ngữ.","formula":"Chủ ngữ + vị ngữ + tân ngữ","tip":"Hỏi tên thì tân ngữ là 什么名字, trả lời thì thay bằng tên thật.","title":"Trật tự từ cơ bản: 主语+谓语+宾语"}],"han":"我叫李文","natural":["Mạch ý: cô Vương hỏi tên Trần Thiên Trung, Trần Thiên Trung nhận nhầm Bạch Gia Nguyệt thành An Ni rồi xin lỗi, sau đó Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu, cuối bài là bài vè luyện phát âm.","Chú ý trật tự câu cơ bản trong tiếng Trung: chủ ngữ, vị ngữ, tân ngữ, ví dụ 我叫陈天中.","Tên người Trung Quốc gồm họ rồi tên, ví dụ 陈天中 họ 陈, tên 天中; 白家月 họ 白, tên 家月."],"num":2,"photoPrefix":"h1-2","pinyin":"Wǒ jiào Lǐ Wén","structures":[{"han":"请问，你叫什么名字？","pinyin":"Qǐngwèn, nǐ jiào shénme míngzi?","meaning":"Xin hỏi, bạn tên là gì?","note":"请问 mở đầu câu hỏi một cách lịch sự, còn 你叫什么名字？ là mẫu câu hỏi tên cơ bản, trả lời bằng 我叫……."},{"han":"我不是安妮，我是白家月。","pinyin":"Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","meaning":"Tôi không phải An Ni, tôi là Bạch Gia Nguyệt.","note":"不是 là phủ định của 是, câu này cho thấy cách sửa lại khi nhận nhầm người: 我不是安妮，我是白家月."},{"han":"对不起！没关系！","pinyin":"","meaning":"Xin lỗi! Không sao đâu!","note":"对不起 xin lỗi và 没关系 đáp lại là cặp cố định, sách còn ghi trong khẩu ngữ cũng nói 没事."},{"han":"七加一，再减一，加完减完等于几？加完减完还是七。","pinyin":"","meaning":"Bảy cộng một, rồi trừ một, cộng xong trừ xong bằng mấy? Cộng xong trừ xong vẫn là bảy.","note":"Bài vè chơi chữ với hai động từ 加 (cộng) và 减 (trừ) cùng con số bảy: cộng một rồi trừ một thì kết quả vẫn là bảy, câu hỏi 等于几？ và câu đáp 还是七 tạo thành vần điệu lặp lại, đọc nhanh dễ líu lưỡi."},{"han":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","meaning":"Rất vui được gặp bạn.","note":""}],"theme":"Tự giới thiệu tên","translation":"Tôi tên là Lý Văn","vocab":[{"emoji":"🙏","example":"请问，你叫什么名字？","examplePinyin":"Qǐngwèn, nǐ jiào shénme míngzi?","exampleVi":"Xin hỏi, bạn tên là gì?","meaning":"xin hỏi, làm ơn cho hỏi","pinyin":"qǐngwèn","pos":"Động từ","word":"请问"},{"emoji":"👉","example":"你叫什么名字？","examplePinyin":"Nǐ jiào shénme míngzi?","exampleVi":"Bạn tên là gì?","meaning":"bạn (số ít)","pinyin":"nǐ","pos":"Đại từ","word":"你"},{"emoji":"📛","example":"我叫李文。","examplePinyin":"Wǒ jiào Lǐ Wén.","exampleVi":"Tôi tên là Lý Văn.","meaning":"tên là, gọi là","pinyin":"jiào","pos":"Động từ","word":"叫"},{"emoji":"❓","example":"你叫什么名字？","examplePinyin":"Nǐ jiào shénme míngzi?","exampleVi":"Bạn tên là gì?","meaning":"gì, cái gì","pinyin":"shénme","pos":"Đại từ","word":"什么"},{"emoji":"📛","example":"你叫什么名字？","examplePinyin":"Nǐ jiào shénme míngzi?","exampleVi":"Bạn tên là gì?","meaning":"tên","pinyin":"míngzi","pos":"Danh từ","word":"名字"},{"emoji":"🙋","example":"我叫陈天中。","examplePinyin":"Wǒ jiào Chén Tiānzhōng.","exampleVi":"Tôi tên là Trần Thiên Trung.","meaning":"tôi","pinyin":"wǒ","pos":"Đại từ","word":"我"},{"emoji":"✖️","example":"我不是安妮，我是白家月。","examplePinyin":"Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","exampleVi":"Tôi không phải An Ni, tôi là Bạch Gia Nguyệt.","meaning":"không (phủ định)","pinyin":"bù","pos":"Phó từ","word":"不"},{"emoji":"🟰","example":"我是白家月。","examplePinyin":"Wǒ shì Bái Jiāyuè.","exampleVi":"Tôi là Bạch Gia Nguyệt.","meaning":"là","pinyin":"shì","pos":"Động từ","word":"是"},{"emoji":"🙏","example":"对不起！","examplePinyin":"Duìbuqǐ!","exampleVi":"Xin lỗi!","meaning":"xin lỗi","pinyin":"duìbuqǐ","pos":"Động từ","word":"对不起"},{"emoji":"😊","example":"没关系！","examplePinyin":"Méi guānxi!","exampleVi":"Không sao đâu!","meaning":"không sao đâu, không có gì đâu","pinyin":"méi guānxi","pos":"Cụm từ","word":"没关系"},{"emoji":"😌","example":"没事，别担心。","examplePinyin":"Méishì, bié dānxīn.","exampleVi":"Không sao đâu, đừng lo.","meaning":"không sao, không có chuyện gì","pinyin":"méishì","pos":"Động từ","word":"没事"},{"emoji":"😄","example":"很高兴认识你。","examplePinyin":"Hěn gāoxìng rènshi nǐ.","exampleVi":"Rất vui được gặp bạn.","meaning":"rất, lắm","pinyin":"hěn","pos":"Phó từ","word":"很"},{"emoji":"😊","example":"很高兴认识你。","examplePinyin":"Hěn gāoxìng rènshi nǐ.","exampleVi":"Rất vui được gặp bạn.","meaning":"vui, vui vẻ","pinyin":"gāoxìng","pos":"Tính từ","word":"高兴"},{"emoji":"🤝","example":"认识你我也很高兴。","examplePinyin":"Rènshi nǐ wǒ yě hěn gāoxìng.","exampleVi":"Được gặp bạn tôi cũng rất vui.","meaning":"quen biết, làm quen","pinyin":"rènshi","pos":"Động từ","word":"认识"},{"emoji":"➕","example":"认识你我也很高兴。","examplePinyin":"Rènshi nǐ wǒ yě hěn gāoxìng.","exampleVi":"Được gặp bạn tôi cũng rất vui.","meaning":"cũng","pinyin":"yě","pos":"Phó từ","word":"也"}],"phonetics":{"audio":"h1-phon-2.mp3","sections":[{"exercise":{"instruction":"先跟读音节，再大声朗读。注意“ü”的写法。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to. Chú ý cách viết của “ü”.","items":["jī","jí","jǐ","jì","qū","qú","qǔ","qù","xū","xú","xǔ","xù","jiā","jiàn","quàn","qīng","xiāng","xīn"]},"table":{"headers":["声母","韵母"],"headersVi":["Thanh mẫu","Vận mẫu"],"rows":[["j q x","i [i] ü"],["","ia ie iao iou (iu)"],["","ian in"],["","iang ing iong"],["","üe üan ün"]]},"text":"声母“j、q、x”只和下方表格中的韵母“i [i]、ü”及“i [i]、ü”开头的韵母相拼，不和韵母“a、u”及“a、u”开头的韵母直接相拼。","textVi":"Các thanh mẫu “j, q, x” chỉ ghép với các vận mẫu “i [i], ü” và các vận mẫu bắt đầu bằng “i [i], ü” trong bảng dưới đây, không ghép trực tiếp với các vận mẫu “a, u” và các vận mẫu bắt đầu bằng “a, u”.","title":"声母和韵母（2）","titleVi":"Thanh mẫu và vận mẫu (2)","track":"2-1","words":[{"han":"鸡","py":"jī","vi":"gà"},{"han":"七","py":"qī","vi":"bảy (số 7)"},{"han":"写","py":"xiě","vi":"viết"},{"han":"请","py":"qǐng","vi":"mời, xin (lịch sự)"},{"han":"再见","py":"zàijiàn","vi":"tạm biệt"},{"han":"谢谢","py":"xièxie","vi":"cảm ơn"},{"han":"星期","py":"xīngqī","vi":"tuần"},{"han":"高兴","py":"gāoxìng","vi":"vui, vui vẻ"}]},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["yī","yí","yǐ","yì","wū","wú","wǔ","wù","yū","yú","yǔ","yù"]},"text":"韵母“i、u、ü”单独成音节时，写成“yi、wu、yu”。","textVi":"Khi các vận mẫu “i, u, ü” đứng độc lập tạo thành âm tiết, chúng được viết thành “yi, wu, yu”.","title":"（1）韵母“i、u、ü”单独成音节时的写法","titleVi":"Cách viết các vận mẫu “i, u, ü” khi đứng độc lập tạo thành âm tiết","words":[{"han":"雨","py":"yǔ","vi":"mưa"},{"han":"五","py":"wǔ","vi":"năm (số 5)"},{"han":"一","py":"yī","vi":"một (số 1)"},{"han":"椅子","py":"yǐzi","vi":"ghế"}]},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["jū","jú","jǔ","jù","qū","qú","qǔ","qù","xū","xú","xǔ","xù"]},"text":"声母“j、q、x”和韵母“ü”相拼时，“ü”上边的两点儿省略，写作“u”。","textVi":"Khi các thanh mẫu “j, q, x” ghép với vận mẫu “ü”, hai dấu chấm trên “ü” được lược bỏ, viết thành “u”.","title":"（2）声母“j、q、x”和韵母“ü”相拼的规则","titleVi":"Quy tắc ghép âm của các thanh mẫu “j, q, x” với vận mẫu “ü”"},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["yōu","yóu","yǒu","yòu","yóuyǒng","lǚyóu","péngyou"]},"text":"韵母“iou”单独成音节时，写作“you”。","textVi":"Khi vận mẫu “iou” đứng độc lập tạo thành âm tiết, nó được viết thành “you”.","title":"（3）韵母“iou”单独成音节时的写法","titleVi":"Cách viết các vận mẫu “iou” khi đứng độc lập tạo thành âm tiết"},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["miù","diū","niú","liǔ","jiù","qiū","qiú","xiù"]},"text":"韵母“iou”和声母“m、d、n、l、j、q、x”相拼时，写作“iu”。例如：“miu、diu、niu、liu、jiu、qiu、xiu”。“iu”的声调要标在“u”上。","textVi":"Khi vận mẫu “iou” ghép với các thanh mẫu “m, d, n, l, j, q, x”, thì vận mẫu này được viết thành “iu”. Ví dụ: “miu, diu, niu, liu, jiu, qiu, xiu”. Dấu thanh điệu của “iu” phải được đặt trên “u”.","title":"（4）韵母“iou”在音节里的写法","titleVi":"Cách viết vận mẫu “iou” trong âm tiết","words":[{"han":"九","py":"jiǔ","vi":"chín (số 9)"},{"han":"朋友","py":"péngyou","vi":"bạn bè"},{"han":"牛奶","py":"niúnǎi","vi":"sữa bò"},{"han":"休息","py":"xiūxi","vi":"nghỉ ngơi"}]}]}},{"emoji":"🌏","grammar":[{"error":"Đừng viết 我是忙 hay 我是高兴, 是 chỉ đi với danh từ, không đi với tính từ.","examples":"我是法国人。 (Wǒ shì Fǎguó rén.) — Tôi là người Pháp. 她是中文老师。 (Tā shì Zhōngwén lǎoshī.) — Cô ấy là cô giáo tiếng Trung. 我老师不是法国人。 (Wǒ lǎoshī bú shì Fǎguó rén.) — Cô giáo của tôi không phải người Pháp.","explain":"Câu 是 dùng để nói một người hay một vật là gì hoặc thuộc loại nào. Dạng phủ định là 不是, đặt 不 trước 是.","formula":"Chủ ngữ + 是 + danh từ (chỉ người, quốc tịch, nghề nghiệp)","tip":"是 không dùng với tính từ, muốn nói bận hay vui thì dùng 很, không dùng 是.","title":"Câu với 是: 我是中国人"},{"error":"Đừng quên 的 khi định ngữ không phải đại từ nhân xưng, ví dụ phải nói 白家月的中文老师, không nói 白家月中文老师.","examples":"白家月的中文老师。 (Bái Jiāyuè de Zhōngwén lǎoshī.) — Cô giáo tiếng Trung của Bạch Gia Nguyệt. 你的名字。 (Nǐ de míngzi.) — Tên của bạn. 我老师。 (Wǒ lǎoshī.) — Cô giáo của tôi.","explain":"的 đặt giữa định ngữ và danh từ chính để chỉ quan hệ sở hữu. Khi trước 的 là đại từ nhân xưng và sau 的 là từ chỉ người thân hay từ chỉ người thì có thể lược bỏ 的.","formula":"Định ngữ + 的 + danh từ (trung tâm ngữ)","tip":"我老师, 我学生, 你同学 đều là dạng đã lược 的, vẫn đúng và rất hay dùng.","title":"Trợ từ kết cấu 的 chỉ sở hữu"},{"error":"Đừng thêm từ để hỏi như 什么 hay 谁 vào câu đã có 吗, một câu chỉ hỏi một kiểu.","examples":"你也很忙吗？ (Nǐ yě hěn máng ma?) — Bạn cũng rất bận phải không? 你是她的中文老师吗？ (Nǐ shì tā de Zhōngwén lǎoshī ma?) — Bạn có phải là cô giáo tiếng Trung của cô ấy không? 你工作还忙吗？ (Nǐ gōngzuò hái máng ma?) — Công việc của bạn còn bận không?","explain":"吗 là trợ từ ngữ khí đặt cuối câu để tạo câu hỏi có không. Câu trả lời thường là khẳng định lại hoặc phủ định.","formula":"Câu trần thuật + 吗？","tip":"吗 chỉ đặt cuối câu, không đặt giữa câu.","title":"Câu hỏi có không với 吗"}],"han":"我是中国人","natural":["Mạch ý: Lý Văn và Bạch Gia Nguyệt nói về quốc tịch, An Ni hỏi Trần Thiên Trung về cô gái trong ảnh, Vương Nhất Tuyết gọi video hỏi thăm Vương Nhất Phi, cuối bài là bài vè luyện phát âm.","Chú ý 的 trong 我的中文老师 và 你的名字, và trường hợp 的 có thể lược khi trước là đại từ nhân xưng và sau là từ chỉ người thân hoặc danh từ chỉ người, ví dụ 我老师, 我学生.","Khi nghe, phân biệt câu trần thuật có 是 với câu hỏi có 吗, và nhớ 谁 cũng đọc được là shuí theo ghi chú trong sách."],"num":3,"photoPrefix":"h1-3","pinyin":"Wǒ shì Zhōngguó rén","structures":[{"han":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","meaning":"Tôi là người Trung Quốc.","note":"是 là động từ chính của câu phán đoán, 我是中国人 là mẫu câu 是 cơ bản nhất, phủ định là 不是."},{"han":"我的中文老师也是中国人。","pinyin":"Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","meaning":"Giáo viên tiếng Trung của tôi cũng là người Trung Quốc.","note":"的 nối định ngữ với danh từ, 我的中文老师 là giáo viên tiếng Trung của tôi, trong đó 也 cho biết thầy cũng là người Trung Quốc như Lý Văn."},{"han":"这是谁？","pinyin":"Zhè shì shéi?","meaning":"Đây là ai?","note":"这 là đại từ chỉ định gần, 谁 hỏi về người, câu này mở đầu bằng 这是谁？ để hỏi người trong ảnh."},{"han":"四是四，十是十。十四是十四，四十是四十。","pinyin":"","meaning":"Bốn là bốn, mười là mười. Mười bốn là mười bốn, bốn mươi là bốn mươi.","note":"Bài vè chơi chữ với bốn số dễ lẫn: 四 (bốn), 十 (mười), 十四 (mười bốn) và 四十 (bốn mươi), chỉ khác nhau ở thứ tự của 四 và 十 nên đọc nhanh rất dễ nhầm lẫn."},{"han":"你工作还忙吗？","pinyin":"Nǐ gōngzuò hái máng ma?","meaning":"Công việc của bạn còn bận không?","note":""}],"theme":"Quốc tịch và câu 是","translation":"Tôi là người Trung Quốc","vocab":[{"emoji":"🧑","example":"我是中国人。","examplePinyin":"Wǒ shì Zhōngguó rén.","exampleVi":"Tôi là người Trung Quốc.","meaning":"người","pinyin":"rén","pos":"Danh từ","word":"人"},{"emoji":"🔗","example":"我的中文老师也是中国人。","examplePinyin":"Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","exampleVi":"Giáo viên tiếng Trung của tôi cũng là người Trung Quốc.","meaning":"(trợ từ kết cấu, dùng sau định ngữ)","pinyin":"de","pos":"Trợ từ","word":"的"},{"emoji":"🇨🇳","example":"我是中国人。","examplePinyin":"Wǒ shì Zhōngguó rén.","exampleVi":"Tôi là người Trung Quốc.","meaning":"Trung Quốc","pinyin":"Zhōngguó","pos":"Danh từ riêng","word":"中国"},{"emoji":"🇫🇷","example":"我是法国人。","examplePinyin":"Wǒ shì Fǎguó rén.","exampleVi":"Tôi là người Pháp.","meaning":"nước Pháp","pinyin":"Fǎguó","pos":"Danh từ riêng","word":"法国"},{"emoji":"🇨🇳","example":"我的中文老师也是中国人。","examplePinyin":"Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","exampleVi":"Giáo viên tiếng Trung của tôi cũng là người Trung Quốc.","meaning":"tiếng Trung","pinyin":"Zhōngwén","pos":"Danh từ riêng","word":"中文"},{"emoji":"👉","example":"这是谁？","examplePinyin":"Zhè shì shéi?","exampleVi":"Đây là ai?","meaning":"đây, này","pinyin":"zhè","pos":"Đại từ","word":"这"},{"emoji":"❓","example":"这是谁？","examplePinyin":"Zhè shì shéi?","exampleVi":"Đây là ai?","meaning":"ai (cũng đọc shuí)","pinyin":"shéi","pos":"Đại từ","word":"谁"},{"emoji":"💑","example":"这是我女朋友。","examplePinyin":"Zhè shì wǒ nǚpéngyou.","exampleVi":"Đây là bạn gái của tôi.","meaning":"bạn gái","pinyin":"nǚpéngyou","pos":"Danh từ","word":"女朋友"},{"emoji":"❓","example":"你女朋友是哪国人？","examplePinyin":"Nǐ nǚpéngyou shì nǎ guó rén?","exampleVi":"Bạn gái của bạn là người nước nào?","meaning":"nào","pinyin":"nǎ","pos":"Đại từ","word":"哪"},{"emoji":"🌍","example":"你女朋友是哪国人？","examplePinyin":"Nǐ nǚpéngyou shì nǎ guó rén?","exampleVi":"Bạn gái của bạn là người nước nào?","meaning":"nước, quốc gia","pinyin":"guó","pos":"Danh từ","word":"国"},{"emoji":"👩","example":"她也是泰国人。","examplePinyin":"Tā yě shì Tàiguó rén.","exampleVi":"Cô ấy cũng là người Thái Lan.","meaning":"cô ấy","pinyin":"tā","pos":"Đại từ","word":"她"},{"emoji":"🇹🇭","example":"她也是泰国人。","examplePinyin":"Tā yě shì Tàiguó rén.","exampleVi":"Cô ấy cũng là người Thái Lan.","meaning":"Thái Lan","pinyin":"Tàiguó","pos":"Danh từ riêng","word":"泰国"},{"emoji":"📞","example":"喂，一飞！","examplePinyin":"Wéi, Yīfēi!","exampleVi":"A lô, Nhất Phi!","meaning":"a lô, này (lời gọi khi nghe điện thoại)","pinyin":"wèi","pos":"Thán từ","word":"喂"},{"emoji":"👩","example":"姐姐！","examplePinyin":"Jiějie!","exampleVi":"Chị ơi!","meaning":"chị gái","pinyin":"jiějie","pos":"Danh từ","word":"姐姐"},{"emoji":"💼","example":"你工作还忙吗？","examplePinyin":"Nǐ gōngzuò hái máng ma?","exampleVi":"Công việc của bạn còn bận không?","meaning":"công việc","pinyin":"gōngzuò","pos":"Danh từ","word":"工作"},{"emoji":"🔄","example":"你工作还忙吗？","examplePinyin":"Nǐ gōngzuò hái máng ma?","exampleVi":"Công việc của bạn còn bận không?","meaning":"còn, vẫn","pinyin":"hái","pos":"Phó từ","word":"还"},{"emoji":"😓","example":"对，还很忙。","examplePinyin":"Duì, hái hěn máng.","exampleVi":"Đúng, còn rất bận.","meaning":"bận","pinyin":"máng","pos":"Tính từ","word":"忙"},{"emoji":"❓","example":"你工作还忙吗？","examplePinyin":"Nǐ gōngzuò hái máng ma?","exampleVi":"Công việc của bạn còn bận không?","meaning":"(trợ từ cuối câu hỏi có không)","pinyin":"ma","pos":"Trợ từ","word":"吗"},{"emoji":"✅","example":"对，还很忙。","examplePinyin":"Duì, hái hěn máng.","exampleVi":"Đúng, còn rất bận.","meaning":"đúng","pinyin":"duì","pos":"Tính từ","word":"对"},{"emoji":"📈","example":"我不太忙。","examplePinyin":"Wǒ bú tài máng.","exampleVi":"Tôi không bận lắm.","meaning":"quá, lắm","pinyin":"tài","pos":"Phó từ","word":"太"},{"emoji":"👥","example":"我们很想你。","examplePinyin":"Wǒmen hěn xiǎng nǐ.","exampleVi":"Chúng tôi rất nhớ bạn.","meaning":"chúng tôi, chúng ta","pinyin":"wǒmen","pos":"Đại từ","word":"我们"},{"emoji":"💭","example":"我们很想你。","examplePinyin":"Wǒmen hěn xiǎng nǐ.","exampleVi":"Chúng tôi rất nhớ bạn.","meaning":"nhớ, nhớ nhung","pinyin":"xiǎng","pos":"Động từ","word":"想"}],"phonetics":{"audio":"h1-phon-3.mp3","sections":[{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["zhā","zhá","zhǎ","zhà","shē","shé","shě","shè","chuāng","chuáng","chuǎng","chuàng","zuō","zuó","zuǒ","zuò"]},"table":{"headers":["声母","韵母"],"headersVi":["Thanh mẫu","Vận mẫu"],"rows":[["zh ch sh r","a e i [ʅ/ɿ] u"],["z c s","ai ao ou"],["","an en"],["","ang eng ong"],["","ua uo uai uei (ui)"],["","uan uen (un)"],["","uang ueng"]]},"text":"声母“zh、ch、sh、r、z、c、s”主要和下方表格中列举的部分韵母相拼，不和韵母“i [i]、ü”及“i [i]、ü”开头的韵母相拼。","textVi":"Các thanh mẫu “zh, ch, sh, r, z, c, s” chủ yếu ghép với một số vận mẫu được liệt kê trong bảng dưới đây, không ghép với các vận mẫu “i [i], ü” và các vận mẫu bắt đầu bằng “i [i], ü”.","title":"声母和韵母（3）","titleVi":"Thanh mẫu và vận mẫu (3)","track":"3-1","words":[{"han":"人","py":"rén","vi":"người"},{"han":"坐","py":"zuò","vi":"đi (xe), ngồi"},{"han":"菜","py":"cài","vi":"món ăn"},{"han":"书","py":"shū","vi":"sách"},{"han":"手机","py":"shǒujī","vi":"điện thoại di động"},{"han":"医生","py":"yīshēng","vi":"bác sĩ"},{"han":"桌子","py":"zhuōzi","vi":"bàn"},{"han":"出租车","py":"chūzūchē","vi":"xe taxi"}]},{"exercise":{"instruction":"先跟读音节，再大声朗读。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to.","items":["wā","wá","wǎ","wà","wēi","wéi","wěi","wèi"]},"text":"韵母“ua、uo、uai、uei、uan、uen、uang、ueng”单独成音节时，“u”写作“w”，写成“wa、wo、wai、wei、wan、wen、wang、weng”。","textVi":"Khi các vận mẫu “ua, uo, uai, uei, uan, uen, uang, ueng” đứng độc lập tạo thành âm tiết, “u” được viết thành “w”, âm tiết được viết thành “wa, wo, wai, wei, wan, wen, wang, weng”.","title":"（1）“u+韵母”类单独成音节时的写法","titleVi":"Cách viết nhóm vận mẫu bắt đầu bằng “u” khi đứng độc lập tạo thành âm tiết"},{"text":"韵母“uei、uen”和声母相拼时，写作“ui、un”。例如：“shuí、chǔn、suǐ、cǔn”。","textVi":"Khi các vận mẫu “uei, uen” ghép với thanh mẫu, chúng được viết thành “ui, un”. Ví dụ: “shuí, chǔn, suǐ, cǔn”.","title":"（2）韵母“uei、uen”在音节里的写法","titleVi":"Cách viết các vận mẫu “uei, uen” trong âm tiết","words":[{"han":"春","py":"chūn","vi":"mùa xuân"},{"han":"村","py":"cūn","vi":"làng, thôn"},{"han":"睡","py":"shuì","vi":"ngủ"},{"han":"嘴","py":"zuǐ","vi":"miệng"}]}]}},{"emoji":"👨‍👩‍👧‍👦","grammar":[{"error":"Phủ định của 有 là 没 hoặc 没有, đừng viết 不有.","examples":"她有二十个学生。 (Tā yǒu èrshí gè xuéshēng.) — Cô ấy có hai mươi học sinh. 她有一个姐姐。 (Tā yǒu yí gè jiějie.) — Cô ấy có một chị gái. 我没有姐姐。 (Wǒ méiyǒu jiějie.) — Tôi không có chị gái.","explain":"有 trong bài này chỉ sở hữu, nghĩa là có. Dạng phủ định là 没 hoặc 没有, đặt trước 有, không dùng 不.","formula":"Chủ ngữ + 有 + tân ngữ (số lượng + lượng từ + danh từ)","tip":"Hỏi số lượng thì dùng 有多少 hoặc 有几, ví dụ 她有多少个学生?","title":"Câu với 有 chỉ sở hữu (1)"},{"error":"Đừng nói 二个学生, trước lượng từ 个 phải dùng 两, không dùng 二.","examples":"十二。 (Shí'èr.) — Mười hai. 二十二。 (Èrshí'èr.) — Hai mươi hai. 两个学生。 (Liǎng gè xuéshēng.) — Hai học sinh.","explain":"Số trong tiếng Hán có hai cách viết là số Ả Rập và chữ Hán, ví dụ 1 và 一. Số 2 viết và đọc là 二 trong số thứ tự như 第二, nhưng trước lượng từ thì dùng 两, ví dụ 两个学生.","formula":"Số chục: 十, 二十, 三十; số trăm: 一百, 二百; số nghìn: 一千; số 2 trước lượng từ đọc là 两","tip":"Nhớ hai cách đọc của 2: 二 trong 十二, 二十二; 两 trong 两个人, 两口人.","title":"Cách đọc và viết số 0 đến 9999"},{"error":"Đừng dùng 呢 để hỏi câu mới chưa nhắc tới, ví dụ gặp nhau lần đầu thì hỏi 你叫什么名字, không hỏi 你呢.","examples":"我有两个哥哥，你呢？ (Wǒ yǒu liǎng gè gēge, nǐ ne?) — Tôi có hai anh trai, còn bạn thì sao? 我叫白家月，你呢？ (Wǒ jiào Bái Jiāyuè, nǐ ne?) — Tôi tên là Bạch Gia Nguyệt, còn bạn thì sao? 我是中国人，你呢？ (Wǒ shì Zhōngguó rén, nǐ ne?) — Tôi là người Trung Quốc, còn bạn thì sao?","explain":"呢 đặt cuối câu để hỏi lại về tình huống vừa nhắc tới, nghĩa gần với còn bạn thì sao. Mẫu thường gặp là nói xong chuyện của mình rồi hỏi đối phương bằng B呢.","formula":"A……, B + 呢？","tip":"呢 trong bài này chỉ dùng để hỏi lại, không dùng để hỏi chuyện hoàn toàn mới.","title":"Trợ từ ngữ khí 呢 hỏi lại: A……, B呢？"},{"error":"Đừng bỏ lượng từ sau số từ, ví dụ phải nói 两个学生, không nói 两学生.","examples":"四口人。 (Sì kǒu rén.) — Bốn người trong gia đình. 两个学生。 (Liǎng gè xuéshēng.) — Hai học sinh. 两个哥哥。 (Liǎng gè gēge.) — Hai anh trai.","explain":"Khi nói số lượng, sau số từ thường phải có lượng từ. Bài này học hai lượng từ chỉ người là 口 dùng cho số người trong nhà và 个 là lượng từ chung, ví dụ 四口人, 两个学生.","formula":"Số từ + lượng từ + (danh từ), ví dụ: 四口人, 两个哥哥","tip":"口 chỉ dùng cho người trong gia đình, còn 个 dùng được cho người nói chung.","title":"Lượng từ danh từ và cấu trúc số + lượng từ + danh từ"}],"han":"我有两个孩子","natural":["Mạch ý: Lưu Minh hỏi Vương Nhất Phi có bao nhiêu học sinh, Vương Nhất Tuyết kể mình có hai anh trai và Dương Đồng Lạc kể nhà mình có bốn người, rồi Dương Đồng Lạc hỏi Vương Nhất Tuyết có mấy con và các con bao nhiêu tuổi.","Chú ý số 2 có hai cách đọc: 二 dùng trong số thứ tự như 第二, 两 dùng trước lượng từ như 两个哥哥, 两口人.","Khi nghe, phân biệt 多少 hỏi số lượng chung, 几 hỏi số lượng nhỏ, 几岁 hỏi tuổi trẻ em và 多大 hỏi tuổi người lớn hơn."],"num":4,"photoPrefix":"h1-4","pinyin":"Wǒ yǒu liǎng gè háizi","structures":[{"han":"她有多少个学生？","pinyin":"Tā yǒu duōshao gè xuéshēng?","meaning":"Cô ấy có bao nhiêu học sinh?","note":"有 nói về sở hữu, 她有多少个学生？ hỏi số lượng, trả lời bằng số từ, lượng từ và danh từ: 二十个学生."},{"han":"我有两个哥哥，你呢？","pinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","meaning":"Tôi có hai anh trai, còn bạn?","note":"呢 đặt cuối câu để hỏi lại điều vừa nhắc tới, 我有两个哥哥，你呢？ hỏi ngược lại đối phương có mấy anh trai."},{"han":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","meaning":"Nhà bạn có mấy người?","note":"口 là lượng từ dùng cho số người trong gia đình, 几口人 hỏi nhà có mấy miệng ăn, trả lời 我家有四口人."},{"han":"您儿子几岁？","pinyin":"Nín érzi jǐ suì?","meaning":"Con trai của cô mấy tuổi?","note":"几岁 hỏi tuổi trẻ dưới mười tuổi, 多大 hỏi tuổi người trên mười tuổi, sách ghi rõ hai cách hỏi này không dùng lẫn nhau."},{"han":"我有两个孩子，一个儿子，一个女儿。","pinyin":"Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","meaning":"Tôi có hai con, một con trai, một con gái.","note":""}],"theme":"Gia đình và tuổi tác","translation":"Tôi có hai con","vocab":[{"emoji":"🤲","example":"我有两个孩子。","examplePinyin":"Wǒ yǒu liǎng gè háizi.","exampleVi":"Tôi có hai con.","meaning":"có","pinyin":"yǒu","pos":"Động từ","word":"有"},{"emoji":"🔢","example":"她有多少个学生？","examplePinyin":"Tā yǒu duōshao gè xuéshēng?","exampleVi":"Cô ấy có bao nhiêu học sinh?","meaning":"bao nhiêu","pinyin":"duōshao","pos":"Đại từ","word":"多少"},{"emoji":"📏","example":"她有二十个学生。","examplePinyin":"Tā yǒu èrshí gè xuéshēng.","exampleVi":"Cô ấy có hai mươi học sinh.","meaning":"(lượng từ chung)","pinyin":"gè","pos":"Lượng từ","word":"个"},{"emoji":"👨","example":"我有两个哥哥，你呢？","examplePinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","exampleVi":"Tôi có hai anh trai, còn bạn?","meaning":"anh trai","pinyin":"gēge","pos":"Danh từ","word":"哥哥"},{"emoji":"❓","example":"我有两个哥哥，你呢？","examplePinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","exampleVi":"Tôi có hai anh trai, còn bạn?","meaning":"(trợ từ cuối câu hỏi lại)","pinyin":"ne","pos":"Trợ từ","word":"呢"},{"emoji":"✖️","example":"我没有哥哥。","examplePinyin":"Wǒ méiyǒu gēge.","exampleVi":"Tôi không có anh trai.","meaning":"không có","pinyin":"méiyǒu","pos":"Động từ","word":"没有"},{"emoji":"🏠","example":"你家有几口人？","examplePinyin":"Nǐ jiā yǒu jǐ kǒu rén?","exampleVi":"Nhà bạn có mấy người?","meaning":"gia đình, nhà","pinyin":"jiā","pos":"Danh từ","word":"家"},{"emoji":"🔢","example":"你家有几口人？","examplePinyin":"Nǐ jiā yǒu jǐ kǒu rén?","exampleVi":"Nhà bạn có mấy người?","meaning":"mấy, bao nhiêu (số nhỏ)","pinyin":"jǐ","pos":"Đại từ","word":"几"},{"emoji":"👥","example":"我家有四口人。","examplePinyin":"Wǒ jiā yǒu sì kǒu rén.","exampleVi":"Nhà tôi có bốn người.","meaning":"(lượng từ cho số người trong gia đình)","pinyin":"kǒu","pos":"Lượng từ","word":"口"},{"emoji":"👨","example":"我家有四口人，爸爸、妈妈、妹妹和我。","examplePinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","exampleVi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","meaning":"bố","pinyin":"bàba","pos":"Danh từ","word":"爸爸"},{"emoji":"👩","example":"我家有四口人，爸爸、妈妈、妹妹和我。","examplePinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","exampleVi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","meaning":"mẹ","pinyin":"māma","pos":"Danh từ","word":"妈妈"},{"emoji":"👧","example":"我家有四口人，爸爸、妈妈、妹妹和我。","examplePinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","exampleVi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","meaning":"em gái","pinyin":"mèimei","pos":"Danh từ","word":"妹妹"},{"emoji":"➕","example":"我家有四口人，爸爸、妈妈、妹妹和我。","examplePinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","exampleVi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","meaning":"và","pinyin":"hé","pos":"Liên từ","word":"和"},{"emoji":"👦","example":"这是您儿子吗？","examplePinyin":"Zhè shì nín érzi ma?","exampleVi":"Đây là con trai của cô phải không?","meaning":"con trai","pinyin":"érzi","pos":"Danh từ","word":"儿子"},{"emoji":"👶","example":"我有两个孩子。","examplePinyin":"Wǒ yǒu liǎng gè háizi.","exampleVi":"Tôi có hai con.","meaning":"con, trẻ con","pinyin":"háizi","pos":"Danh từ","word":"孩子"},{"emoji":"👧","example":"我有两个孩子，一个儿子，一个女儿。","examplePinyin":"Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","exampleVi":"Tôi có hai con, một con trai, một con gái.","meaning":"con gái","pinyin":"nǚ'ér","pos":"Danh từ","word":"女儿"},{"emoji":"🎂","example":"他今年五岁。","examplePinyin":"Tā jīnnián wǔ suì.","exampleVi":"Cháu năm nay năm tuổi.","meaning":"tuổi","pinyin":"suì","pos":"Lượng từ","word":"岁"},{"emoji":"👨","example":"他今年五岁。","examplePinyin":"Tā jīnnián wǔ suì.","exampleVi":"Cháu năm nay năm tuổi.","meaning":"anh ấy, cậu ấy","pinyin":"tā","pos":"Đại từ","word":"他"},{"emoji":"📅","example":"他今年五岁。","examplePinyin":"Tā jīnnián wǔ suì.","exampleVi":"Cháu năm nay năm tuổi.","meaning":"năm nay","pinyin":"jīnnián","pos":"Danh từ","word":"今年"},{"emoji":"❓","example":"您女儿多大？","examplePinyin":"Nín nǚ'ér duō dà?","exampleVi":"Con gái của cô bao nhiêu tuổi?","meaning":"bao nhiêu (mức độ)","pinyin":"duō","pos":"Đại từ","word":"多"},{"emoji":"📏","example":"您女儿多大？","examplePinyin":"Nín nǚ'ér duō dà?","exampleVi":"Con gái của cô bao nhiêu tuổi?","meaning":"lớn (tuổi)","pinyin":"dà","pos":"Tính từ","word":"大"}],"phonetics":{"audio":"h1-phon-4.mp3","sections":[{"exercise":{"instruction":"先跟读，再大声朗读。注意三声变调。","instructionVi":"Nghe và nhắc lại, sau đó đọc to. Chú ý biến điệu của thanh 3.","items":["shuǐguǒ","nǐ hǎo","kěyǐ","nǎlǐ","hěn hǎo","suǒyǐ","qǐng nǐ","shǒubiǎo"]},"table":{"headers":["词语/短语","拼音"],"headersVi":["Từ/Cụm từ","Phiên âm"],"rows":[["你好","nǐ + hǎo → ní + hǎo"],["哪里","nǎ + lǐ → ná + lǐ"],["可以","kě + yǐ → ké + yǐ"],["小语","Xiǎo + yǔ → Xiáo + yǔ"],["很好","hěn + hǎo → hén + hǎo"]]},"text":"两个三声（ˇ）音节连读时，第一个三声读成二声，即214+214→35+214。","textVi":"Khi hai âm tiết mang thanh 3 (ˇ) đọc liền nhau, thanh điệu của âm tiết thứ nhất đọc thành thanh 2, tức là 214 + 214 → 35 + 214.","title":"两个三声音节的连读变调","titleVi":"Sự biến đổi về thanh điệu khi hai âm tiết mang thanh 3 đi liền nhau","track":"4-1","words":[{"han":"你好","py":"nǐ hǎo","vi":"xin chào"},{"han":"哪里","py":"nǎlǐ","vi":"ở đâu"},{"han":"小语","py":"Xiǎoyǔ","vi":"Tiểu Ngữ (tên nhân vật)"},{"han":"水果","py":"shuǐguǒ","vi":"hoa quả"}]},{"table":{"headers":["词语","拼音","汉语意思","越南语意思"],"headersVi":["Từ","Phiên âm","Nghĩa tiếng Trung","Nghĩa tiếng Việt"],"rows":[["东西","dōngxī","方位，东西边","phương hướng, phía đông và phía tây"],["买卖","mǎi mài","买和卖","mua và bán"],["孙子","Sūnzǐ","人名，中国古代军事家","tên người, nhà quân sự Trung Quốc thời cổ đại"],["东西","dōngxi","事物","đồ vật"],["买卖","mǎimai","生意","buôn bán/kinh doanh"],["孙子","sūnzi","儿子的儿子","cháu nội"]]},"text":"除了四个基本声调外，汉语中有些音节不带声调，读音又轻又短，被称为轻声。轻声通常不做声调标记。例如：“jiǎozi、bàba”。\n汉语中一些词语读不读轻声，意义会不一样。例如：","textVi":"Ngoài bốn thanh điệu cơ bản, trong tiếng Trung Quốc có một số âm tiết không mang thanh điệu, đọc vừa nhẹ vừa ngắn, được gọi là thanh nhẹ. Thanh nhẹ thường không được đánh dấu thanh điệu. Ví dụ: “jiǎozi, bàba”.\nTrong tiếng Trung Quốc, một số từ khi đọc thanh nhẹ hay không đọc thanh nhẹ sẽ có ý nghĩa khác nhau. Ví dụ:","title":"轻声","titleVi":"Thanh nhẹ","words":[{"han":"妈妈","py":"māma","vi":"mẹ"},{"han":"爸爸","py":"bàba","vi":"bố"},{"han":"椅子","py":"yǐzi","vi":"ghế"},{"han":"饺子","py":"jiǎozi","vi":"sủi cảo"},{"han":"谢谢","py":"xièxie","vi":"cảm ơn"},{"han":"衣服","py":"yīfu","vi":"quần áo"},{"han":"漂亮","py":"piàoliang","vi":"xinh đẹp"},{"han":"早上","py":"zǎoshang","vi":"buổi sáng sớm"}]}]}},{"emoji":"📅","grammar":[{"error":"Đừng nói theo thứ tự ngày tháng năm kiểu 8号9月, tiếng Hán luôn nói tháng trước ngày sau.","examples":"今天9月8号。 (Jīntiān jiǔ yuè bā hào.) — Hôm nay là ngày 8 tháng 9. 今天是2025年5月22号。 (Jīntiān shì èr líng èr wǔ nián wǔ yuè èrshí'èr hào.) — Hôm nay là ngày 22 tháng 5 năm 2025. 明天是2024年8月18号，星期天。 (Míngtiān shì èr líng èr sì nián bā yuè shíbā hào, Xīngqītiān.) — Ngày mai là Chủ nhật, ngày 18 tháng 8 năm 2024.","explain":"Tiếng Hán nói ngày tháng theo thứ tự từ lớn đến nhỏ là năm, tháng, ngày rồi mới đến thứ. Ngày trong tháng nói là 号 trong khẩu ngữ, viết trang trọng thì dùng 日.","formula":"年 + 月 + 日/号 + 星期, ví dụ: 2025年5月22号, 星期四","tip":"Chủ nhật nói là 星期日 hoặc 星期天, hai cách đều đúng.","title":"Cách nói ngày tháng và thứ: 年-月-日-星期"},{"error":"Đừng thêm động từ vào vị ngữ danh từ, ví dụ nói 我妹妹12岁 là đủ, không cần thêm 是 hay 有.","examples":"今天5月1号。 (Jīntiān wǔ yuè yī hào.) — Hôm nay là ngày 1 tháng 5. 我妹妹12岁。 (Wǒ mèimei shí'èr suì.) — Em gái tôi 12 tuổi. 今天9月8号。 (Jīntiān jiǔ yuè bā hào.) — Hôm nay là ngày 8 tháng 9.","explain":"Câu vị ngữ danh từ có vị ngữ chỉ gồm danh từ hoặc cụm danh từ, thường nói về thời gian, ngày tháng hay tuổi, ví dụ 今天5月1号, 我妹妹12岁.","formula":"Chủ ngữ + (danh từ chỉ thời gian, ngày tháng, tuổi) làm vị ngữ, không cần 是 hay động từ","tip":"Nhận biết loại câu này ở chỗ vị ngữ là danh từ mà không có động từ, khác với câu 是 có chữ 是.","title":"Câu vị ngữ danh từ: 今天5月1号"},{"error":"Đừng viết 没会, phủ định của 会 là 不会.","examples":"你会做饭吗？ (Nǐ huì zuò fàn ma?) — Bạn biết nấu cơm không? 我会做面条儿。 (Wǒ huì zuò miàntiáor.) — Tôi biết làm mì sợi. 我不会做菜。 (Wǒ bú huì zuò cài.) — Tôi không biết nấu món ăn.","explain":"会 đặt trước động từ để nói biết làm một việc sau khi học, hoặc có khả năng làm việc đó. Hỏi thì thêm 吗 cuối câu, phủ định thì dùng 不会.","formula":"Chủ ngữ + 会 + động từ, phủ định: 不会 + động từ","tip":"会 nói về kỹ năng đã học được, bài này chỉ học 会.","title":"Động từ năng nguyện 会 chỉ biết làm gì"}],"han":"今天我休息","natural":["Mạch ý: Lưu Minh nói hôm nay là ngày 8 tháng 9, Chủ nhật nên được nghỉ, Dương Đồng Lạc kể mình biết nấu mì, sủi cảo và một số món, Chủ nhật cũng nấu cơm, rồi Vương Nhất Tuyết khen máy tính mới của Dương Đồng Lạc rất đẹp.","Chú ý thứ tự nói ngày tháng trong tiếng Trung: năm, tháng, ngày, thứ, ví dụ 2025年5月22号, 2024年8月18号，星期天.","Khi nghe, phân biệt 会 nói về năng lực học được với câu hỏi có không dùng 吗, và nhớ 星期日 cũng nói là 星期天."],"num":5,"photoPrefix":"h1-5","pinyin":"Jīntiān wǒ xiūxi","structures":[{"han":"今天几号？","pinyin":"Jīntiān jǐ hào?","meaning":"Hôm nay là ngày mấy?","note":"今天几号？ hỏi ngày trong tháng, trả lời bằng tháng và số ngày: 今天9月8号, trong đó 号 cũng có thể nói là 日."},{"han":"星期几？","pinyin":"Xīngqī jǐ?","meaning":"Hôm nay là thứ mấy?","note":"星期几？ hỏi thứ trong tuần, trả lời 星期日, còn 星期天 cũng có nghĩa là Chủ nhật, sách ghi cả hai cách nói."},{"han":"你会做饭吗？","pinyin":"Nǐ huì zuò fàn ma?","meaning":"Bạn có biết nấu cơm không?","note":"会 đặt trước động từ để nói về năng lực học được, 你会做饭吗？ hỏi có biết nấu cơm không, phủ định là 不会."},{"han":"真好看！","pinyin":"Zhēn hǎokàn!","meaning":"Đẹp thật đấy!","note":"真好看 là câu cảm thán khen ngợi, 真 nhấn mạnh mức độ, 我也很喜欢它 đáp lại bằng 也 để nói mình cũng thích."},{"han":"今天9月8号。","pinyin":"Jīntiān jiǔ yuè bā hào.","meaning":"Hôm nay là ngày 8 tháng 9.","note":""}],"theme":"Ngày tháng và năng lực","translation":"Hôm nay tôi nghỉ","vocab":[{"emoji":"📅","example":"今天几号？","examplePinyin":"Jīntiān jǐ hào?","exampleVi":"Hôm nay là ngày mấy?","meaning":"hôm nay","pinyin":"jīntiān","pos":"Danh từ","word":"今天"},{"emoji":"🔢","example":"今天9月8号。","examplePinyin":"Jīntiān jiǔ yuè bā hào.","exampleVi":"Hôm nay là ngày 8 tháng 9.","meaning":"ngày (trong tháng)","pinyin":"hào","pos":"Lượng từ","word":"号"},{"emoji":"🌙","example":"今天9月8号。","examplePinyin":"Jīntiān jiǔ yuè bā hào.","exampleVi":"Hôm nay là ngày 8 tháng 9.","meaning":"tháng","pinyin":"yuè","pos":"Danh từ","word":"月"},{"emoji":"📆","example":"1992年5月16日，星期六。","examplePinyin":"Yìjiǔjiǔ'èr nián wǔ yuè shíliù rì, Xīngqīliù.","exampleVi":"Ngày 16 tháng 5 năm 1992, thứ Bảy.","meaning":"ngày (trong tháng)","pinyin":"rì","pos":"Lượng từ","word":"日"},{"emoji":"🗓️","example":"星期几？","examplePinyin":"Xīngqī jǐ?","exampleVi":"Hôm nay là thứ mấy?","meaning":"tuần","pinyin":"xīngqī","pos":"Danh từ","word":"星期"},{"emoji":"☀️","example":"星期日。今天我休息。","examplePinyin":"Xīngqīrì. Jīntiān wǒ xiūxi.","exampleVi":"Chủ nhật. Hôm nay tôi nghỉ.","meaning":"Chủ nhật","pinyin":"Xīngqīrì","pos":"Danh từ","word":"星期日"},{"emoji":"☀️","example":"星期天我也做饭。","examplePinyin":"Xīngqītiān wǒ yě zuò fàn.","exampleVi":"Chủ nhật tôi cũng nấu cơm.","meaning":"Chủ nhật","pinyin":"Xīngqītiān","pos":"Danh từ","word":"星期天"},{"emoji":"😌","example":"今天我休息。","examplePinyin":"Jīntiān wǒ xiūxi.","exampleVi":"Hôm nay tôi nghỉ.","meaning":"nghỉ ngơi","pinyin":"xiūxi","pos":"Động từ","word":"休息"},{"emoji":"💪","example":"你会做饭吗？","examplePinyin":"Nǐ huì zuò fàn ma?","exampleVi":"Bạn có biết nấu cơm không?","meaning":"biết (làm gì sau khi học)","pinyin":"huì","pos":"Động từ khiếm khuyết","word":"会"},{"emoji":"🍳","example":"你会做饭吗？","examplePinyin":"Nǐ huì zuò fàn ma?","exampleVi":"Bạn có biết nấu cơm không?","meaning":"nấu cơm","pinyin":"zuò fàn","pos":"Động từ","word":"做饭"},{"emoji":"🔨","example":"我会做。","examplePinyin":"Wǒ huì zuò.","exampleVi":"Tôi biết làm.","meaning":"làm, chế biến","pinyin":"zuò","pos":"Động từ","word":"做"},{"emoji":"🍜","example":"我会做面条儿、饺子，也会做一些菜。","examplePinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài.","exampleVi":"Tôi biết làm mì, sủi cảo, cũng biết làm một số món.","meaning":"mì sợi","pinyin":"miàntiáor","pos":"Danh từ","word":"面条儿"},{"emoji":"🥟","example":"我会做面条儿、饺子，也会做一些菜。","examplePinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài.","exampleVi":"Tôi biết làm mì, sủi cảo, cũng biết làm một số món.","meaning":"sủi cảo","pinyin":"jiǎozi","pos":"Danh từ","word":"饺子"},{"emoji":"🥗","example":"我会做面条儿、饺子，也会做一些菜。","examplePinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài.","exampleVi":"Tôi biết làm mì, sủi cảo, cũng biết làm một số món.","meaning":"một số, một ít","pinyin":"yìxiē","pos":"Số từ","word":"一些"},{"emoji":"🍲","example":"我不会做菜。","examplePinyin":"Wǒ bú huì zuò cài.","exampleVi":"Tôi không biết nấu món ăn.","meaning":"món ăn","pinyin":"cài","pos":"Danh từ","word":"菜"},{"emoji":"🏢","example":"同乐，下班吗？","examplePinyin":"Tónglè, xiàbān ma?","exampleVi":"Đồng Lạc, tan làm chưa?","meaning":"tan làm","pinyin":"xiàbān","pos":"Động từ","word":"下班"},{"emoji":"🆕","example":"这是你的新电脑吗？","examplePinyin":"Zhè shì nǐ de xīn diànnǎo ma?","exampleVi":"Đây là máy tính mới của bạn phải không?","meaning":"mới","pinyin":"xīn","pos":"Tính từ","word":"新"},{"emoji":"💻","example":"这是你的新电脑吗？","examplePinyin":"Zhè shì nǐ de xīn diànnǎo ma?","exampleVi":"Đây là máy tính mới của bạn phải không?","meaning":"máy tính","pinyin":"diànnǎo","pos":"Danh từ","word":"电脑"},{"emoji":"✨","example":"真好看！","examplePinyin":"Zhēn hǎokàn!","exampleVi":"Đẹp thật đấy!","meaning":"thật, thật sự","pinyin":"zhēn","pos":"Phó từ","word":"真"},{"emoji":"😍","example":"真好看！","examplePinyin":"Zhēn hǎokàn!","exampleVi":"Đẹp thật đấy!","meaning":"đẹp, hay (nhìn)","pinyin":"hǎokàn","pos":"Tính từ","word":"好看"},{"emoji":"❤️","example":"我也很喜欢它。","examplePinyin":"Wǒ yě hěn xǐhuan tā.","exampleVi":"Tôi cũng rất thích nó.","meaning":"thích","pinyin":"xǐhuan","pos":"Động từ","word":"喜欢"},{"emoji":"🖱️","example":"我也很喜欢它。","examplePinyin":"Wǒ yě hěn xǐhuan tā.","exampleVi":"Tôi cũng rất thích nó.","meaning":"nó (chỉ đồ vật)","pinyin":"tā","pos":"Đại từ","word":"它"}],"phonetics":{"audio":"h1-phon-5.mp3","sections":[{"exercise":{"instruction":"先跟读音节，再大声朗读。注意“不”的变调。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to. Chú ý biến điệu của “不”.","items":["bù（不）+ shì（是）→ bú + shì（不是）","bù（不）+ huì（会）→ bú + huì（不会）","bù（不）+ dà（大）→ bú + dà（不大）","bù（不）+ duì（对）→ bú + duì（不对）"]},"text":"“不（bù）”单用或在一声、二声和三声音节前，不变调。在四声音节前读二声。\n不（bù）+ 四声 → 不（bú）+ 四声","textVi":"“不 (bù)” không thay đổi thanh điệu khi dùng độc lập hoặc đứng trước âm tiết mang thanh 1, thanh 2 và thanh 3. Khi đứng trước âm tiết mang thanh 4 thì “不 (bù)” được đọc thành thanh 2.\n不 (bù) + thanh 4 → 不 (bú) + thanh 4","title":"“不”的变调","titleVi":"Biến điệu của “不”","track":"5-1"},{"text":"“一（yī）”单用或表示序数时，不变调。有两种情况需变调。","textVi":"“一 (yī)” không thay đổi thanh điệu khi dùng độc lập hoặc biểu thị số thứ tự. Có hai trường hợp “一 (yī)” cần biến điệu.","title":"“一”的变调","titleVi":"Biến điệu của “一”"},{"exercise":{"instruction":"先跟读音节，再大声朗读。注意“一”的变调。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to. Chú ý biến điệu của “一”.","items":["yī（一）+ xiē（些）→ yì + xiē（一些）","yī（一）+ nián（年）→ yì + nián（一年）","yī（一）+ kǒu（口）→ yì + kǒu（一口）"]},"text":"一（yī）+ 一声/二声/三声 → 一（yì）+ 一声/二声/三声","textVi":"一 (yī) + thanh 1/thanh 2/thanh 3 → 一 (yì) + thanh 1/thanh 2/thanh 3","title":"（1）“一”在一声、二声和三声音节前，读四声。","titleVi":"Khi “一” đứng trước âm tiết mang thanh 1, thanh 2 và thanh 3 thì đọc thành thanh 4."},{"exercise":{"instruction":"先跟读音节，再大声朗读。注意“一”的变调。","instructionVi":"Nghe và nhắc lại âm tiết, sau đó đọc to. Chú ý biến điệu của “一”.","items":["yī（一）+ gè（个）→ yí + gè（一个）","yī（一）+ rì（日）→ yí + rì（一日）","yī（一）+ suì（岁）→ yí + suì（一岁）"]},"text":"一（yī）+ 四声 → 一（yí）+ 四声","textVi":"一 (yī) + thanh 4 → 一 (yí) + thanh 4","title":"（2）“一”在四声音节前，读二声。","titleVi":"Khi “一” đứng trước âm tiết mang thanh 4 thì đọc thành thanh 2."}]}},{"num":6,"emoji":"📱","han":"你的手机号是多少？","pinyin":"Nǐ de shǒujīhào shì duōshao?","translation":"Số điện thoại di động của bạn là bao nhiêu?","theme":"Số điện thoại và mua sắm","vocab":[{"emoji":"📱","word":"手机","pinyin":"shǒujī","pos":"Danh từ","meaning":"điện thoại di động","example":"我想买一个新手机。","examplePinyin":"Wǒ xiǎng mǎi yí ge xīn shǒujī.","exampleVi":"Tôi muốn mua một chiếc điện thoại mới."},{"emoji":"📞","word":"电话","pinyin":"diànhuà","pos":"Danh từ","meaning":"điện thoại; cuộc gọi","example":"请问，我可以用你的电话吗？","examplePinyin":"Qǐngwèn, wǒ kěyǐ yòng nǐ de diànhuà ma?","exampleVi":"Xin hỏi, tôi có thể dùng điện thoại của bạn không?"},{"emoji":"🔢","word":"号","pinyin":"hào","pos":"Danh từ","meaning":"số, mã số","example":"你的手机号是多少？","examplePinyin":"Nǐ de shǒujīhào shì duōshao?","exampleVi":"Số điện thoại di động của bạn là bao nhiêu?"},{"emoji":"📅","word":"明天","pinyin":"míngtiān","pos":"Danh từ","meaning":"ngày mai","example":"明天你去哪儿？","examplePinyin":"Míngtiān nǐ qù nǎr?","exampleVi":"Ngày mai bạn đi đâu?"},{"emoji":"🚶","word":"去","pinyin":"qù","pos":"Động từ","meaning":"đi, đến","example":"我想去超市。","examplePinyin":"Wǒ xiǎng qù chāoshì.","exampleVi":"Tôi muốn đi siêu thị."},{"emoji":"❓","word":"哪儿","pinyin":"nǎr","pos":"Đại từ","meaning":"đâu, ở đâu","example":"星期天我们去哪儿吃晚饭？","examplePinyin":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","exampleVi":"Chủ nhật chúng ta đi đâu ăn tối?"},{"emoji":"💭","word":"想","pinyin":"xiǎng","pos":"Động từ","meaning":"muốn","example":"我想去超市买东西。","examplePinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","exampleVi":"Tôi muốn đi siêu thị mua đồ."},{"emoji":"🛒","word":"超市","pinyin":"chāoshì","pos":"Danh từ","meaning":"siêu thị","example":"她坐出租车去超市。","examplePinyin":"Tā zuò chūzūchē qù chāoshì.","exampleVi":"Cô ấy đi taxi đến siêu thị."},{"emoji":"🛍️","word":"买","pinyin":"mǎi","pos":"Động từ","meaning":"mua","example":"你去超市买什么？","examplePinyin":"Nǐ qù chāoshì mǎi shénme?","exampleVi":"Bạn đi siêu thị mua gì?"},{"emoji":"📦","word":"东西","pinyin":"dōngxi","pos":"Danh từ","meaning":"đồ vật, thứ","example":"我想去超市买东西。","examplePinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","exampleVi":"Tôi muốn đi siêu thị mua đồ."},{"emoji":"🔢","word":"些","pinyin":"xiē","pos":"Lượng từ","meaning":"một số, một vài","example":"我想买些包子。","examplePinyin":"Wǒ xiǎng mǎi xiē bāozi.","exampleVi":"Tôi muốn mua một ít bánh bao."},{"emoji":"🥛","word":"牛奶","pinyin":"niúnǎi","pos":"Danh từ","meaning":"sữa bò","example":"我想买些牛奶。","examplePinyin":"Wǒ xiǎng mǎi xiē niúnǎi.","exampleVi":"Tôi muốn mua một ít sữa bò."},{"emoji":"🍚","word":"吃","pinyin":"chī","pos":"Động từ","meaning":"ăn","example":"妈妈，我想吃米饭，不想吃包子。","examplePinyin":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","exampleVi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."},{"emoji":"🍽️","word":"晚饭","pinyin":"wǎnfàn","pos":"Danh từ","meaning":"bữa tối","example":"我们去西安饭店吃晚饭。","examplePinyin":"Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn.","exampleVi":"Chúng tôi đến nhà hàng Tây An ăn tối."},{"emoji":"👉","word":"那边","pinyin":"nàbiān","pos":"Đại từ","meaning":"bên đó, chỗ đó","example":"那边的包子非常好吃。","examplePinyin":"Nàbiān de bāozi fēicháng hǎochī.","exampleVi":"Bánh bao bên đó rất ngon."},{"emoji":"🥟","word":"包子","pinyin":"bāozi","pos":"Danh từ","meaning":"bánh bao","example":"我想吃包子。","examplePinyin":"Wǒ xiǎng chī bāozi.","exampleVi":"Tôi muốn ăn bánh bao."},{"emoji":"⭐","word":"非常","pinyin":"fēicháng","pos":"Trạng từ","meaning":"rất, vô cùng","example":"那边的包子非常好吃，我想吃包子。","examplePinyin":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","exampleVi":"Bánh bao bên đó rất ngon, tôi muốn ăn bánh bao."},{"emoji":"😋","word":"好吃","pinyin":"hǎochī","pos":"Tính từ","meaning":"ngon","example":"那边的包子非常好吃。","examplePinyin":"Nàbiān de bāozi fēicháng hǎochī.","exampleVi":"Bánh bao bên đó rất ngon."},{"emoji":"🍚","word":"米饭","pinyin":"mǐfàn","pos":"Danh từ","meaning":"cơm","example":"妈妈，我想吃米饭，不想吃包子。","examplePinyin":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","exampleVi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."},{"emoji":"❓","word":"怎么","pinyin":"zěnme","pos":"Đại từ","meaning":"thế nào, bằng cách nào","example":"我们怎么去？","examplePinyin":"Wǒmen zěnme qù?","exampleVi":"Chúng ta đi bằng cách nào?"},{"emoji":"🚕","word":"坐","pinyin":"zuò","pos":"Động từ","meaning":"đi (xe), ngồi","example":"坐出租车去。","examplePinyin":"Zuò chūzūchē qù.","exampleVi":"Đi taxi đến đó."},{"emoji":"🚕","word":"出租车","pinyin":"chūzūchē","pos":"Danh từ","meaning":"xe taxi","example":"我们坐出租车去西安饭店。","examplePinyin":"Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.","exampleVi":"Chúng tôi đi taxi đến nhà hàng Tây An."}],"photoPrefix":"h1-6","structures":[{"han":"你的手机号是多少？","pinyin":"Nǐ de shǒujīhào shì duōshao?","meaning":"Số điện thoại di động của bạn là bao nhiêu?","note":"多少 hỏi số lượng; số điện thoại đọc từng chữ số một, số 1 đọc là yāo."},{"han":"我想去超市买东西。","pinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","meaning":"Tôi muốn đi siêu thị mua đồ.","note":"想 đứng trước động từ diễn tả mong muốn; 去超市买东西 là câu liên động, cụm sau (mua đồ) nói mục đích của cụm trước (đi siêu thị)."},{"han":"我们坐出租车去西安饭店。","pinyin":"Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.","meaning":"Chúng tôi đi taxi đến nhà hàng Tây An.","note":"坐出租车去 là câu liên động diễn tả cách thức: đi bằng taxi để đến nhà hàng."},{"han":"我们怎么去？","pinyin":"Hǎo de. Wǒmen zěnme qù?","meaning":"Chúng ta đi bằng cách nào?","note":"怎么 là đại từ nghi vấn hỏi cách thức, đứng trước động từ 去; câu trả lời nêu phương tiện, ví dụ 坐出租车去。"}],"natural":["Mạch ý: hỏi số điện thoại, hẹn đi siêu thị mua đồ, cả nhà bàn ăn tối cuối tuần.","想 đứng trước động từ để nói mong muốn; câu liên động có hai cụm động từ, cụm sau nói mục đích hoặc cách thức của cụm trước.","Khi nghe số điện thoại, chú ý số 1 đọc là yāo, và các chữ số đọc từng số một."],"grammar":[{"error":"Đừng đặt 想 sau động từ, ví dụ đừng nói 我去想超市.","examples":"我想去超市。(Wǒ xiǎng qù chāoshì.) — Tôi muốn đi siêu thị. 我哥哥不想休息。(Wǒ gēge bù xiǎng xiūxi.) — Anh tôi không muốn nghỉ ngơi.","explain":"想 đứng trước động từ, diễn tả mong muốn hoặc dự định làm một việc gì đó.","formula":"Chủ ngữ + 想 + động từ + tân ngữ","tip":"Phủ định đặt 不 trước 想, thành 不想, không đặt 不 trước động từ chính.","title":"Động từ năng nguyện 想 (muốn, định)"},{"error":"Đừng đảo thứ tự hai động tác, vì động tác trước xảy ra trước và thường chỉ mục đích hoặc cách thức của động tác sau.","examples":"我想去超市买东西。(Wǒ xiǎng qù chāoshì mǎi dōngxi.) — Tôi muốn đi siêu thị mua đồ. 我们去西安饭店吃晚饭。(Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn.) — Chúng tôi đi nhà hàng Tây An ăn tối. 我们坐出租车去西安饭店。(Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.) — Chúng tôi ngồi taxi đi nhà hàng Tây An.","explain":"Vị ngữ gồm hai cụm động từ trở lên nối tiếp nhau. Động tác sau có thể chỉ mục đích của động tác trước, hoặc động tác trước chỉ cách thức của động tác sau.","formula":"Chủ ngữ + động từ 1 + (tân ngữ) + động từ 2 + (tân ngữ)","tip":"Hai động tác có cùng một chủ ngữ, giữa hai động tác không dùng liên từ.","title":"Câu liên động 连动句 (1): hai động tác nối tiếp"},{"error":"Đừng đặt 怎么 ở cuối câu, và đừng dùng 怎么 để hỏi tên một đồ vật.","examples":"我们怎么去？(Wǒmen zěnme qù?) — Chúng tôi đi bằng cách nào? 她怎么去超市？(Tā zěnme qù chāoshì?) — Cô ấy đi siêu thị bằng cách nào?","explain":"怎么 đứng trước động từ để hỏi về cách thức hoặc phương pháp thực hiện một động tác.","formula":"Chủ ngữ + 怎么 + động từ + (tân ngữ)？","tip":"怎么 hỏi cách làm, khác với 什么 hỏi đồ vật và 哪儿 hỏi nơi chốn.","title":"Đại từ nghi vấn 怎么 (bằng cách nào)"}],"phonetics":{"audio":"h1-phon-6.mp3","sections":[{"exercise":{"instruction":"看图片，先跟读，再大声朗读。注意儿化发音。","instructionVi":"Xem hình, nghe và nhắc lại, sau đó đọc to. Chú ý phát âm âm uốn lưỡi “儿 (ér)”.","items":["miàntiáor","hǎowánr","yìdiǎnr","fànguǎnr","nàr","zhèr","wánr","gèr"]},"table":{"headers":["原词","词性","","儿化","词性"],"headersVi":["Từ gốc","Từ loại","","Âm uốn lưỡi “儿 (ér)”","Từ loại"],"rows":[["这 zhè","đt.","→","这儿 zhèr","đt."],["哪 nǎ","đt.","→","哪儿 nǎr","đt."],["画 huà","đgt.","→","画儿 huàr","đt."],["盖 gài","đgt.","→","盖儿 gàir","đt."],["个 gè","lượng.","→","个儿 gèr","đt."],["眼 yǎn","đt.","→","眼儿 yǎnr","đt."]]},"text":"汉语中一些词后边加上词尾“儿”，表示“细小、喜爱”的感情色彩，有时会改变词义、词性。有的词语直接加“儿”，相应地在原拼音后加“r”，例如：“这儿zhèr、那儿nàr、面条儿miàntiáor”。有的词语后边不直接加“儿”，但口语里习惯上会儿化，例如：“茶馆cháguǎnr、饭馆fànguǎnr、名牌míngpáir、照片zhàopiànr”。","textVi":"Trong tiếng Trung Quốc, một số từ khi thêm hậu tố “儿 (ér)” ở phía sau sẽ mang sắc thái thân mật, biểu thị ý nghĩa “nhỏ bé” hoặc “yêu thích”。\n\nTrong một số trường hợp, việc thêm “儿” có thể làm thay đổi ý nghĩa và từ loại của từ. Có một số từ khi được trực tiếp thêm “儿”, sẽ thêm “r” vào sau phiên âm gốc, ví dụ: “这儿 zhèr (chỗ này)”, “那儿 nàr (chỗ kia)”, “面条儿 miàntiáor (mì sợi)”.\n\nCó một số từ không trực tiếp thêm “儿” ở phía sau, nhưng theo thói quen trong văn nói sẽ được phát âm uốn lưỡi, ví dụ: “茶馆 cháguǎnr (tiệm trà)”, “饭馆 fànguǎnr (nhà hàng)”, “名牌 míngpáir (thương hiệu nổi tiếng)”, “照片 zhàopiànr (ảnh)”.","title":"儿化","titleVi":"Âm uốn lưỡi","track":"6-1","words":[{"han":"面条儿","py":"miàntiáor","vi":"mì sợi"},{"han":"好玩儿","py":"hǎowánr","vi":"vui, thú vị"},{"han":"一点儿","py":"yìdiǎnr","vi":"một chút, một ít"},{"han":"饭馆（儿）","py":"fànguǎnr","vi":"quán ăn, nhà hàng"},{"han":"那儿","py":"nàr","vi":"đó, chỗ đó"},{"han":"这儿","py":"zhèr","vi":"đây, chỗ này"},{"han":"玩（儿）","py":"wánr","vi":"chơi"},{"han":"歌（儿）","py":"gèr","vi":"bài hát"}]},{"text":"“a、o、e”开头的音节与前面的音节相接时，为了避免音节界限不清楚，要在两个音节间使用隔音符号（'）进行区分。例如：“shí'èr（十二）、Xī'ān（西安）、Tiān'ān Mén（天安门）”。","textVi":"Khi âm tiết bắt đầu bằng “a, o, e” nối liền với âm tiết phía trước, để tránh ranh giới giữa các âm tiết không rõ ràng, cần sử dụng dấu cách âm (') ở giữa hai âm tiết để phân biệt. Ví dụ: “shí'èr (mười hai)”, “Xī'ān (Tây An)”, “Tiān'ān Mén (Thiên An Môn)”.","title":"拼写规则——隔音符号","titleVi":"Quy tắc viết phiên âm – dấu cách âm","track":"6-1"}]}},{"num":7,"emoji":"🕕","han":"我晚上六点半下班","pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān","translation":"Tôi tan làm lúc sáu giờ rưỡi tối","theme":"Giờ giấc và công việc","vocab":[{"emoji":"🕐","word":"现在","pinyin":"xiànzài","pos":"Danh từ","meaning":"bây giờ","example":"现在几点？","examplePinyin":"Xiànzài jǐ diǎn?","exampleVi":"Bây giờ là mấy giờ?"},{"emoji":"🕑","word":"点","pinyin":"diǎn","pos":"Lượng từ","meaning":"giờ","example":"早上八点四十。","examplePinyin":"Zǎoshang bā diǎn sìshí.","exampleVi":"Tám giờ bốn mươi buổi sáng."},{"emoji":"🌅","word":"早上","pinyin":"zǎoshang","pos":"Danh từ","meaning":"buổi sáng sớm","example":"早上八点四十。","examplePinyin":"Zǎoshang bā diǎn sìshí.","exampleVi":"Tám giờ bốn mươi buổi sáng."},{"emoji":"☀️","word":"上午","pinyin":"shàngwǔ","pos":"Danh từ","meaning":"buổi sáng","example":"她上午十点半上课。","examplePinyin":"Tā shàngwǔ shí diǎn bàn shàngkè.","exampleVi":"Sáng nay mười giờ rưỡi cô ấy vào học."},{"emoji":"⏱️","word":"分","pinyin":"fēn","pos":"Lượng từ","meaning":"phút","example":"现在是八点四十分。","examplePinyin":"Xiànzài shì bā diǎn sìshí fēn.","exampleVi":"Bây giờ là tám giờ bốn mươi phút."},{"emoji":"📖","word":"课","pinyin":"kè","pos":"Danh từ","meaning":"tiết học, bài học","example":"我上午十点十分有课。","examplePinyin":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","exampleVi":"Sáng nay mười giờ mười phút tôi có tiết học."},{"emoji":"🌇","word":"下午","pinyin":"xiàwǔ","pos":"Danh từ","meaning":"buổi chiều","example":"下午我想去电影院看电影。","examplePinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng.","exampleVi":"Chiều nay tôi muốn đi rạp chiếu phim xem phim."},{"emoji":"👋","word":"见","pinyin":"jiàn","pos":"Động từ","meaning":"gặp","example":"我们下午三点见吧。","examplePinyin":"Wǒmen xiàwǔ sān diǎn jiàn ba.","exampleVi":"Chiều nay ba giờ chúng ta gặp nhau nhé."},{"emoji":"💬","word":"吧","pinyin":"ba","pos":"Trợ từ","meaning":"trợ từ cuối câu, diễn tả đề nghị, thương lượng","example":"你去超市买吧。","examplePinyin":"Nǐ qù chāoshì mǎi ba.","exampleVi":"Bạn đi siêu thị mua đi."},{"emoji":"🎬","word":"电影院","pinyin":"diànyǐngyuàn","pos":"Danh từ","meaning":"rạp chiếu phim","example":"下午我想去电影院看电影，你去吗？","examplePinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","exampleVi":"Chiều nay tôi muốn đi rạp chiếu phim xem phim, bạn đi không?"},{"emoji":"👀","word":"看","pinyin":"kàn","pos":"Động từ","meaning":"xem, nhìn, đọc","example":"我想去电影院看电影。","examplePinyin":"Wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng.","exampleVi":"Tôi muốn đi rạp chiếu phim xem phim."},{"emoji":"🎬","word":"电影","pinyin":"diànyǐng","pos":"Danh từ","meaning":"phim","example":"下午我想去电影院看电影。","examplePinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng.","exampleVi":"Chiều nay tôi muốn đi rạp chiếu phim xem phim."},{"emoji":"📋","word":"事","pinyin":"shì","pos":"Danh từ","meaning":"việc, chuyện","example":"我不想去，下午还有事。","examplePinyin":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","exampleVi":"Tôi không muốn đi, chiều nay còn có việc."},{"emoji":"🎒","word":"上课","pinyin":"shàngkè","pos":"Động từ","meaning":"vào học, đi học","example":"我明天下午两点还上课呢。","examplePinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.","exampleVi":"Chiều mai hai giờ tôi vẫn còn học đấy."},{"emoji":"💬","word":"呢","pinyin":"ne","pos":"Trợ từ","meaning":"trợ từ cuối câu trần thuật, diễn tả sự việc đã xác nhận","example":"李文晚上还有事呢。","examplePinyin":"Lǐ Wén wǎnshang hái yǒu shì ne.","exampleVi":"Buổi tối Lý Văn còn có việc đấy."},{"emoji":"🕧","word":"半","pinyin":"bàn","pos":"Số từ","meaning":"nửa","example":"四点半下课。","examplePinyin":"Sì diǎn bàn xiàkè.","exampleVi":"Bốn giờ rưỡi tan học."},{"emoji":"🔔","word":"下课","pinyin":"xiàkè","pos":"Động từ","meaning":"tan học","example":"我明天下午两点还上课呢，四点半下课。","examplePinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","exampleVi":"Chiều mai hai giờ tôi vẫn còn học, bốn giờ rưỡi mới tan học."},{"emoji":"📍","word":"在","pinyin":"zài","pos":"Động từ","meaning":"ở, tại","example":"我在家里呢。","examplePinyin":"Wǒ zài jiā li ne.","exampleVi":"Tôi đang ở nhà đây."},{"emoji":"🏠","word":"家","pinyin":"jiā","pos":"Danh từ","meaning":"nhà, gia đình","example":"安妮下午在家里学中文。","examplePinyin":"Ānnī xiàwǔ zài jiā li xué Zhōngwén.","exampleVi":"Buổi chiều An Ni học tiếng Trung ở nhà."},{"emoji":"🏠","word":"里","pinyin":"li/lǐ","pos":"Danh từ","meaning":"bên trong","example":"你去店里买些菜吧。","examplePinyin":"Nǐ qù diàn li mǎi xiē cài ba.","exampleVi":"Bạn đi cửa hàng mua ít rau nhé."},{"emoji":"🌙","word":"晚上","pinyin":"wǎnshang","pos":"Danh từ","meaning":"buổi tối","example":"我晚上六点半下班。","examplePinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān.","exampleVi":"Tôi tan làm lúc sáu giờ rưỡi tối."},{"emoji":"🏥","word":"医院","pinyin":"yīyuàn","pos":"Danh từ","meaning":"bệnh viện","example":"我八点去医院上班。","examplePinyin":"Wǒ bā diǎn qù yīyuàn shàngbān.","exampleVi":"Tôi tám giờ đi bệnh viện làm việc."},{"emoji":"💼","word":"上班","pinyin":"shàngbān","pos":"Động từ","meaning":"đi làm","example":"我明天八点上班。","examplePinyin":"Wǒ míngtiān bā diǎn shàngbān.","exampleVi":"Ngày mai tám giờ tôi đi làm."},{"emoji":"🏪","word":"店","pinyin":"diàn","pos":"Danh từ","meaning":"cửa hàng","example":"店里有很多东西。","examplePinyin":"Diàn li yǒu hěn duō dōngxi.","exampleVi":"Trong cửa hàng có rất nhiều đồ."},{"emoji":"🥬","word":"菜","pinyin":"cài","pos":"Danh từ","meaning":"rau, món ăn","example":"我想去店里买菜。","examplePinyin":"Wǒ xiǎng qù diàn li mǎi cài.","exampleVi":"Tôi muốn đi cửa hàng mua rau."},{"emoji":"⏱️","word":"分钟","pinyin":"fēnzhōng","pos":"Lượng từ","meaning":"phút","example":"好，我十分钟后去。","examplePinyin":"Hǎo, wǒ shí fēnzhōng hòu qù.","exampleVi":"Được, mười phút nữa tôi đi."},{"emoji":"⏩","word":"后","pinyin":"hòu","pos":"Danh từ","meaning":"sau, về sau","example":"我十分钟后去。","examplePinyin":"Wǒ shí fēnzhōng hòu qù.","exampleVi":"Mười phút nữa tôi đi."}],"photoPrefix":"h1-7","structures":[{"han":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","meaning":"Bây giờ là mấy giờ?","note":"现在 hỏi thời điểm hiện tại; 几点 hỏi giờ, trả lời bằng số giờ cộng 点 và số phút cộng 分."},{"han":"我们下午两点见吧。","pinyin":"Wǒmen xiàwǔ liǎng diǎn jiàn ba.","meaning":"Chiều nay hai giờ chúng ta gặp nhau nhé.","note":"吧 ở cuối câu diễn tả đề nghị, thương lượng; 下午 là danh từ chỉ khoảng thời gian, đứng trước giờ cụ thể."},{"han":"我明天下午两点还上课呢。","pinyin":"","meaning":"Chiều mai hai giờ tôi vẫn còn học đấy.","note":"呢 ở cuối câu trần thuật diễn tả sự việc đã xác nhận; 还 là phó từ, đứng trước động từ."},{"han":"我晚上六点半下班。","pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān.","meaning":"Tôi tan làm lúc sáu giờ rưỡi tối.","note":"晚上 là từ ngữ chỉ thời gian, đứng trước động từ làm trạng ngữ; 六点半 là sáu giờ rưỡi, 半 chỉ nửa giờ."}],"natural":["Mạch ý: gọi điện hỏi giờ và hẹn gặp, rủ đi xem phim nhưng bận học, gọi điện hỏi thăm và nhờ mua rau.","Nói giờ: giờ chẵn chỉ dùng 点, có phút thì thêm 分; mười phút thì không được lược 分, dưới mười phút phải đọc 零.","吧 diễn tả đề nghị, 呢 diễn tả sự việc đã xác nhận; cả hai đều đứng cuối câu và đọc thanh nhẹ."],"grammar":[{"error":"Đừng quên đọc 零 khi số phút dưới 10, và đừng lược 分 khi đúng mười phút, ví dụ phải nói 二十一点十分 chứ không nói 二十一点十.","examples":"中午十二点。(Zhōngwǔ shí'èr diǎn.) — 12 giờ trưa. 下午两点半。(Xiàwǔ liǎng diǎn bàn.) — 2 giờ rưỡi chiều. 二十二点零五。(Èrshí'èr diǎn líng wǔ.) — 22 giờ 05 phút.","explain":"Dùng 点 chỉ giờ chẵn, thêm 分 khi có phút. 分 có thể lược bỏ, trừ khi đúng mười phút thì không được lược, và dưới mười phút phải đọc thêm 零. Sau các danh từ chỉ buổi như 上午, 下午 có thể thêm giờ cụ thể ngay sau đó.","formula":"(Buổi: 上午/中午/下午/晚上) + số giờ + 点 + (số phút + 分)","tip":"Nửa giờ nói 半, đặt ngay sau 点, ví dụ 两点半.","title":"Cách nói giờ 时间的表达 (2): 点, 分, 半 và buổi trong ngày"},{"error":"Đừng đọc 吧 thành thanh 3, và đừng thêm 吧 vào câu hỏi đã có 吗.","examples":"我们下午三点见吧。(Wǒmen xiàwǔ sān diǎn jiàn ba.) — Chiều 3 giờ chúng ta gặp nhau nhé. 你去超市买吧。(Nǐ qù chāoshì mǎi ba.) — Bạn đi siêu thị mua đi nhé. 我们去西安饭店吃晚饭吧。(Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn ba.) — Chúng ta đi nhà hàng Tây An ăn tối nhé.","explain":"吧 đọc thanh nhẹ (ba), đứng cuối câu để diễn tả đề nghị, bàn bạc, khuyên nhủ hoặc yêu cầu một cách nhẹ nhàng.","formula":"Câu trần thuật + 吧。","tip":"吧 ở đây mang giọng đề nghị, câu trả lời thường là 好的.","title":"Trợ từ ngữ khí 吧 (1): đề nghị, bàn bạc"},{"error":"Đừng đặt cụm thời gian sau động từ, ví dụ đừng nói 我上课上午十点半.","examples":"我不想去。(Wǒ bù xiǎng qù.) — Tôi không muốn đi. 妹妹很高兴。(Mèimei hěn gāoxìng.) — Em gái rất vui. 她上午十点半上课。(Tā shàngwǔ shí diǎn bàn shàngkè.) — Cô ấy 10 giờ rưỡi sáng lên lớp.","explain":"Trong tiếng Trung, phó từ và từ ngữ chỉ thời gian làm trạng ngữ thường đứng trước động từ hoặc tính từ, không đứng sau như trong tiếng Việt.","formula":"Chủ ngữ + (từ chỉ thời gian) + (phó từ: 不/很/还) + động từ/tính từ","tip":"Nhớ thứ tự: thời gian trước, phó từ phủ định hoặc mức độ sau, rồi mới đến động từ.","title":"Vị trí trạng ngữ: phó từ và từ chỉ thời gian đứng trước động từ"},{"error":"Đừng thêm 呢 vào câu hỏi đã có 吗, và đừng dùng 呢 khi muốn phủ nhận sự việc.","examples":"我明天下午两点还上课呢。(Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.) — Chiều mai 2 giờ tôi vẫn còn lên lớp đấy. 妹妹会做两个菜呢。(Mèimei huì zuò liǎng gè cài ne.) — Em gái biết làm hai món đấy. 李文晚上还有事呢。(Lǐ Wén wǎnshang hái yǒu shì ne.) — Buổi tối Lý Văn vẫn còn việc đấy.","explain":"呢 đứng cuối câu để diễn tả sự việc đã được xác nhận, mang giọng nhấn mạnh là đúng như vậy.","formula":"Câu trần thuật + 呢。","tip":"呢 (2) khác với 呢 (1) dùng trong câu hỏi rút gọn, ở đây 呢 đứng cuối câu trần thuật.","title":"Trợ từ ngữ khí 呢 (2): khẳng định sự việc đã xác nhận"}],"phonetics":{"audio":"h1-phon-7.mp3","sections":[{"exercise":{"instruction":"听录音，分辨送气声母和不送气声母，并大声朗读。","instructionVi":"Nghe ghi âm, phân biệt thanh mẫu bật hơi và thanh mẫu không bật hơi, đồng thời đọc to.","items":["gǔ","kǔ","diǎn","tiǎn","dòng","tòng","jiǔ","qiǔ","zèng","cèng","zhǔn","chǔn","zhí","chí","zì","cì","bái","pái","bēn","pēn","jǔ","qǔ","guǎ","kuǎ"]},"text":"送气声母和不送气声母是汉语语音的一大特色，送气声母和不送气声母都是成对的，共六组：“b和p、d和t、g和k、j和q、zh和ch、z和c”。","textVi":"Thanh mẫu bật hơi và thanh mẫu không bật hơi là một điểm đặc trưng của ngữ âm tiếng Trung Quốc, thanh mẫu bật hơi và thanh mẫu không bật hơi đều đi theo cặp, tổng cộng có sáu nhóm: “b và p, d và t, g và k, j và q, zh và ch, z và c”。","title":"送气声母和不送气声母辨析","titleVi":"Phân biệt thanh mẫu bật hơi và thanh mẫu không bật hơi","track":"7-1"},{"exercise":{"instruction":"听录音，分辨前鼻音韵母和后鼻音韵母，并大声朗读。","instructionVi":"Nghe ghi âm, phân biệt vận mẫu âm mũi trước và vận mẫu âm mũi sau, đồng thời đọc to.","items":["pén","péng","rǎn","rǎng","nián","niáng","jiàn","jiàng","gǎn","gǎng","mén","méng","sèn","sēng","zàn","zàng","shěn","shěng","huán","huáng","fàn","fàng","chēn","chēng","lín","líng","xiàn","xiàng","bìn","bìng","qīn","qīng"]},"text":"汉语中前鼻音韵母是指以“-n”结尾的韵母，后鼻音韵母是指以“-ng”结尾的韵母。","textVi":"Trong tiếng Trung Quốc, vận mẫu âm mũi trước chỉ các vận mẫu kết thúc bằng “-n”, vận mẫu âm mũi sau chỉ các vận mẫu kết thúc bằng “-ng”。","title":"前鼻音韵母和后鼻音韵母辨析","titleVi":"Phân biệt vận mẫu âm mũi trước và vận mẫu âm mũi sau","track":"7-1"}]}},{"num":8,"emoji":"🏥","han":"我爸爸也在医院工作","pinyin":"Wǒ bàba yě zài yīyuàn gōngzuò","translation":"Bố tôi cũng làm việc ở bệnh viện","theme":"Vị trí và nghề nghiệp","vocab":[{"emoji":"🚪","word":"房间","pinyin":"fángjiān","pos":"Danh từ","meaning":"phòng","example":"房间外有一只小猫。","examplePinyin":"Fángjiān wài yǒu yì zhī xiǎo māo.","exampleVi":"Ngoài phòng có một con mèo nhỏ."},{"emoji":"🚪","word":"外","pinyin":"wài","pos":"Danh từ","meaning":"bên ngoài","example":"我们去书店外吧。","examplePinyin":"Wǒmen qù shūdiàn wài ba.","exampleVi":"Chúng ta ra ngoài hiệu sách nhé."},{"emoji":"🐱","word":"只","pinyin":"zhī","pos":"Lượng từ","meaning":"lượng từ dùng cho con vật","example":"房间外有一只小猫。","examplePinyin":"Fángjiān wài yǒu yì zhī xiǎo māo.","exampleVi":"Ngoài phòng có một con mèo nhỏ."},{"emoji":"🐱","word":"小","pinyin":"xiǎo","pos":"Tính từ","meaning":"nhỏ","example":"这只小猫真漂亮！","examplePinyin":"Zhè zhī xiǎo māo zhēn piàoliang!","exampleVi":"Con mèo nhỏ này xinh thật!"},{"emoji":"🐱","word":"猫","pinyin":"māo","pos":"Danh từ","meaning":"mèo","example":"小猫在桌子下。","examplePinyin":"Xiǎo māo zài zhuōzi xià.","exampleVi":"Con mèo nhỏ ở dưới gầm bàn."},{"emoji":"🙅","word":"没","pinyin":"méi","pos":"Trạng từ","meaning":"không, chưa","example":"我没看见，它在哪儿呢？","examplePinyin":"Wǒ méi kànjiàn, tā zài nǎr ne?","exampleVi":"Tôi không nhìn thấy nó, nó ở đâu nhỉ?"},{"emoji":"👀","word":"看见","pinyin":"kànjiàn","pos":"Động từ","meaning":"nhìn thấy","example":"我看见小猫在桌子下。","examplePinyin":"Wǒ kànjiàn xiǎo māo zài zhuōzi xià.","exampleVi":"Tôi nhìn thấy con mèo nhỏ ở dưới gầm bàn."},{"emoji":"🪑","word":"桌子","pinyin":"zhuōzi","pos":"Danh từ","meaning":"bàn","example":"它在桌子下呢。","examplePinyin":"Tā zài zhuōzi xià ne.","exampleVi":"Nó đang ở dưới gầm bàn đấy."},{"emoji":"⬇️","word":"下","pinyin":"xià","pos":"Danh từ","meaning":"phía dưới","example":"小猫在桌子下。","examplePinyin":"Xiǎo māo zài zhuōzi xià.","exampleVi":"Con mèo nhỏ ở dưới gầm bàn."},{"emoji":"😍","word":"漂亮","pinyin":"piàoliang","pos":"Tính từ","meaning":"xinh đẹp","example":"这只小猫真漂亮！","examplePinyin":"Zhè zhī xiǎo māo zhēn piàoliang!","exampleVi":"Con mèo nhỏ này xinh thật!"},{"emoji":"📍","word":"在","pinyin":"zài","pos":"Giới từ","meaning":"ở, tại","example":"他爸爸在医院工作。","examplePinyin":"Tā bàba zài yīyuàn gōngzuò.","exampleVi":"Bố anh ấy làm việc ở bệnh viện."},{"emoji":"🏫","word":"学校","pinyin":"xuéxiào","pos":"Danh từ","meaning":"trường học","example":"在学校书店前见吧。","examplePinyin":"Zài xuéxiào shūdiàn qián jiàn ba.","exampleVi":"Gặp nhau trước hiệu sách của trường nhé."},{"emoji":"📚","word":"书店","pinyin":"shūdiàn","pos":"Danh từ","meaning":"hiệu sách","example":"学校里有一个书店。","examplePinyin":"Xuéxiào li yǒu yí ge shūdiàn.","exampleVi":"Trong trường có một hiệu sách."},{"emoji":"⬆️","word":"前","pinyin":"qián","pos":"Danh từ","meaning":"phía trước","example":"我们在学校书店前见吧。","examplePinyin":"Wǒmen zài xuéxiào shūdiàn qián jiàn ba.","exampleVi":"Chúng ta gặp nhau trước hiệu sách của trường nhé."},{"emoji":"💪","word":"能","pinyin":"néng","pos":"Động từ","meaning":"có thể","example":"下午两点你能到吗？","examplePinyin":"Xiàwǔ liǎng diǎn nǐ néng dào ma?","exampleVi":"Chiều nay hai giờ bạn đến được không?"},{"emoji":"📍","word":"到","pinyin":"dào","pos":"Động từ","meaning":"đến, tới","example":"我能到。","examplePinyin":"Wǒ néng dào.","exampleVi":"Tôi đến được."},{"emoji":"🍱","word":"午饭","pinyin":"wǔfàn","pos":"Danh từ","meaning":"bữa trưa","example":"我在学校吃午饭。","examplePinyin":"Wǒ zài xuéxiào chī wǔfàn.","exampleVi":"Tôi ăn trưa ở trường."},{"emoji":"🍚","word":"饭","pinyin":"fàn","pos":"Danh từ","meaning":"bữa ăn, cơm","example":"小胡，还没吃饭呢？","examplePinyin":"Xiǎo Hú, hái méi chī fàn ne?","exampleVi":"Tiểu Hồ, vẫn chưa ăn cơm à?"},{"emoji":"🏥","word":"大","pinyin":"dà","pos":"Tính từ","meaning":"to, lớn","example":"大医院病人多，医生非常忙。","examplePinyin":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","exampleVi":"Bệnh viện lớn đông bệnh nhân, bác sĩ rất bận."},{"emoji":"🧑‍⚕️","word":"病人","pinyin":"bìngrén","pos":"Danh từ","meaning":"bệnh nhân","example":"大医院病人多。","examplePinyin":"Dà yīyuàn bìngrén duō.","exampleVi":"Bệnh viện lớn đông bệnh nhân."},{"emoji":"🔢","word":"多","pinyin":"duō","pos":"Tính từ","meaning":"nhiều","example":"大医院病人多，医生非常忙。","examplePinyin":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","exampleVi":"Bệnh viện lớn đông bệnh nhân, bác sĩ rất bận."},{"emoji":"👨‍⚕️","word":"医生","pinyin":"yīshēng","pos":"Danh từ","meaning":"bác sĩ","example":"你家有两个医生？","examplePinyin":"Nǐ jiā yǒu liǎng ge yīshēng?","exampleVi":"Nhà bạn có hai bác sĩ à?"},{"emoji":"💼","word":"工作","pinyin":"gōngzuò","pos":"Động từ","meaning":"làm việc","example":"我爸爸也在医院工作。","examplePinyin":"Wǒ bàba yě zài yīyuàn gōngzuò.","exampleVi":"Bố tôi cũng làm việc ở bệnh viện."}],"photoPrefix":"h1-8","structures":[{"han":"房间外有一只小猫。","pinyin":"Fángjiān wài yǒu yì zhī xiǎo māo.","meaning":"Ngoài phòng có một con mèo nhỏ.","note":"房间外 là cụm từ chỉ vị trí; 有 diễn tả sự tồn tại, sau 有 là số lượng cộng lượng từ cộng danh từ."},{"han":"它在桌子下呢。","pinyin":"Tā zài zhuōzi xià ne.","meaning":"Nó đang ở dưới gầm bàn đấy.","note":"桌子下 là từ chỉ phương vị; 呢 ở cuối câu diễn tả sự việc đã xác nhận."},{"han":"我在学校吃午饭。","pinyin":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","meaning":"Tôi ăn trưa ở trường.","note":"在 cộng từ chỉ nơi chốn, đứng trước động từ, nói hành động diễn ra ở đâu."},{"han":"下午两点你能到吗？","pinyin":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","meaning":"Chiều nay hai giờ bạn đến được không?","note":"能 là động từ năng nguyện đứng trước động từ, diễn tả khả năng; 吗 ở cuối câu hỏi có không."},{"han":"我们在哪儿见呢？","pinyin":"Wǒmen zài nǎr jiàn ne?","meaning":"Chúng ta gặp nhau ở đâu nhỉ?","note":""},{"han":"我爸爸也在医院工作。","pinyin":"Wǒ bàba yě zài yīyuàn gōngzuò.","meaning":"Bố tôi cũng làm việc ở bệnh viện.","note":""}],"natural":["Mạch ý: thấy mèo nhỏ ngoài phòng, hẹn gặp trước hiệu sách, trò chuyện ở bệnh viện về công việc bận rộn.","Từ chỉ phương vị đứng sau danh từ: 桌子上, 桌子下, 房间外, 书店前; 里 sau danh từ đọc thanh nhẹ.","Phân biệt 在 làm động từ (我在家里呢) và 在 làm giới từ (我在学校吃午饭)."],"grammar":[{"error":"Đừng đặt từ chỉ phương vị trước danh từ, ví dụ đừng nói 里房间 thay cho 房间里.","examples":"房间里有一只小猫。(Fángjiān li yǒu yì zhī xiǎo māo.) — Trong phòng có một con mèo con. 我们去书店外吧。(Wǒmen qù shūdiàn wài ba.) — Chúng ta đi ra ngoài hiệu sách nhé. 小雪的手机在桌子上呢。(Xiǎoxuě de shǒujī zài zhuōzi shang ne.) — Điện thoại của Tiểu Tuyết ở trên bàn đấy.","explain":"Các từ chỉ phương vị trong quyển này gồm 上, 下, 里, 外, 前, 后, 外边, dùng để chỉ hướng và vị trí của người hoặc vật.","formula":"Danh từ chỉ nơi chốn + từ chỉ phương vị (上/下/里/外/前/后/外边)","tip":"里 đọc thanh nhẹ (li) khi đứng sau danh từ, còn trong từ 外边 thì 边 đọc thanh nhẹ.","title":"Từ chỉ phương vị 方位词: 上, 下, 里, 外, 前, 后"},{"error":"Đừng đặt cụm 在 + nơi chốn sau động từ, ví dụ đừng nói 我吃午饭在学校.","examples":"我在学校吃午饭。(Wǒ zài xuéxiào chī wǔfàn.) — Tôi ăn trưa ở trường. 他爸爸在医院工作。(Tā bàba zài yīyuàn gōngzuò.) — Bố anh ấy làm việc ở bệnh viện. 你在哪儿买菜？(Nǐ zài nǎr mǎi cài?) — Bạn mua rau ở đâu?","explain":"在 kết hợp với từ chỉ vị trí hoặc nơi chốn, đặt trước động từ để chỉ hành động diễn ra ở vị trí hoặc nơi chốn nào.","formula":"Chủ ngữ + 在 + nơi chốn + động từ + (tân ngữ)","tip":"Cụm 在 + nơi chốn luôn đứng trước động từ, không đứng sau động từ.","title":"Giới từ 在 chỉ nơi chốn hành động"},{"error":"Đừng dùng 能 thay cho 会 khi nói về kỹ năng đã học được, ví dụ kỹ năng nấu ăn hay làm một món ăn.","examples":"下午两点你能到吗？(Xiàwǔ liǎng diǎn nǐ néng dào ma?) — Chiều 2 giờ bạn có đến được không? 爸爸能去。(Bàba néng qù.) — Bố có thể đi. 我不能去学校吃午饭。(Wǒ bù néng qù xuéxiào chī wǔfàn.) — Tôi không thể đến trường ăn trưa.","explain":"能 đứng trước động từ, diễn tả có khả năng, có điều kiện hoặc có thể làm một việc gì đó.","formula":"Chủ ngữ + (不) + 能 + động từ + (tân ngữ)","tip":"Phủ định là 不能, đặt 不 trước 能.","title":"Động từ năng nguyện 能 (có thể, được)"}],"phonetics":{"audio":"h1-phon-8.mp3","sections":[{"exercise":{"instruction":"听录音，选择听到的音节并大声朗读。","instructionVi":"Nghe ghi âm, chọn âm tiết nghe được và đọc to.","items":["(1) lián nián","(2) rěn shěn","(3) diē tiē","(4) chǎn chǎng","(5) liè luè","(6) hún fén","(7) bīn bīng","(8) gǒng kǒng"]},"title":"音节辨析（1）","titleVi":"Phân biệt âm tiết (1)","track":"8-1"},{"exercise":{"instruction":"听录音，选出不是叠音（或重叠式）的双音节。","instructionVi":"Nghe và chọn ra từ có hai âm tiết không phải dạng từ láy (hoặc từ lặp lại).","items":["(1) A tīngting B tīnglì C jiějie","(2) A gēge B gègè C gè kè","(3) A kànkan B kànjiàn C xiǎngxiang","(4) A méiyǒu B mèimei C xièxie"]},"title":"音节辨析（2）","titleVi":"Phân biệt âm tiết (2)","track":"8-1"}]}},{"num":9,"emoji":"📚","han":"我明天上午在学校学习","pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí","translation":"Sáng mai tôi học ở trường","theme":"Học tập và cuối tuần","vocab":[{"emoji":"⬆️","word":"前边","pinyin":"qiánbian","pos":"Danh từ","meaning":"phía trước","example":"学校前边有一家电影院。","examplePinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","exampleVi":"Trước trường có một rạp chiếu phim."},{"emoji":"↔️","word":"边","pinyin":"bian/biān","pos":"Danh từ","meaning":"hậu tố chỉ phương vị; phía, bên","example":"我们七点在电影院外边见，好吗？","examplePinyin":"Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","exampleVi":"Bảy giờ chúng ta gặp nhau ngoài rạp chiếu phim, được không?"},{"emoji":"🏠","word":"家","pinyin":"jiā","pos":"Lượng từ","meaning":"lượng từ dùng cho gia đình, doanh nghiệp","example":"王一雪家有一只小狗。","examplePinyin":"Wáng Yīxuě jiā yǒu yì zhī xiǎo gǒu.","exampleVi":"Nhà Vương Nhất Tuyết có một chú chó nhỏ."},{"emoji":"👉","word":"那个","pinyin":"nàge","pos":"Đại từ","meaning":"cái đó, người đó","example":"我们晚上去那个电影院看电影吧。","examplePinyin":"Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","exampleVi":"Tối nay chúng ta đến rạp chiếu phim đó xem phim nhé."},{"emoji":"🚪","word":"外边","pinyin":"wàibian","pos":"Danh từ","meaning":"bên ngoài","example":"我们七点在电影院外边见。","examplePinyin":"Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.","exampleVi":"Bảy giờ chúng ta gặp nhau ngoài rạp chiếu phim."},{"emoji":"🪑","word":"椅子","pinyin":"yǐzi","pos":"Danh từ","meaning":"ghế","example":"椅子上有一本中文书。","examplePinyin":"Yǐzi shang yǒu yì běn Zhōngwén shū.","exampleVi":"Trên ghế có một quyển sách tiếng Trung."},{"emoji":"⬆️","word":"上","pinyin":"shang/shàng","pos":"Danh từ","meaning":"phía trên","example":"书在椅子上。","examplePinyin":"Shū zài yǐzi shang.","exampleVi":"Quyển sách ở trên ghế."},{"emoji":"📖","word":"本","pinyin":"běn","pos":"Lượng từ","meaning":"lượng từ dùng cho sách","example":"这是我的第二本中文书。","examplePinyin":"Zhè shì wǒ de dì-èr běn Zhōngwén shū.","exampleVi":"Đây là quyển sách tiếng Trung thứ hai của tôi."},{"emoji":"📖","word":"书","pinyin":"shū","pos":"Danh từ","meaning":"sách","example":"椅子上有一本中文书，那是谁的书？","examplePinyin":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","exampleVi":"Trên ghế có một quyển sách tiếng Trung, đó là sách của ai?"},{"emoji":"👉","word":"那","pinyin":"nà","pos":"Đại từ","meaning":"đó, kia","example":"那是谁的书？","examplePinyin":"Nà shì shéi de shū?","exampleVi":"Đó là sách của ai?"},{"emoji":"🔢","word":"第","pinyin":"dì","pos":"Tiền tố","meaning":"tiền tố chỉ số thứ tự","example":"第一，第二，第三。","examplePinyin":"Dì-yī, dì-èr, dì-sān.","exampleVi":"Thứ nhất, thứ hai, thứ ba."},{"emoji":"📚","word":"学习","pinyin":"xuéxí","pos":"Động từ","meaning":"học tập","example":"我明天上午在学校学习。","examplePinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","exampleVi":"Sáng mai tôi học ở trường."},{"emoji":"🛠️","word":"做","pinyin":"zuò","pos":"Động từ","meaning":"làm","example":"明天星期六，你做什么？","examplePinyin":"Míngtiān Xīngqīliù, nǐ zuò shénme?","exampleVi":"Ngày mai là thứ bảy, bạn làm gì?"},{"emoji":"☀️","word":"白天","pinyin":"báitiān","pos":"Danh từ","meaning":"ban ngày","example":"我白天在家里读书。","examplePinyin":"Wǒ báitiān zài jiā li dúshū.","exampleVi":"Ban ngày tôi đọc sách ở nhà."},{"emoji":"📖","word":"读书","pinyin":"dúshū","pos":"Động từ","meaning":"đọc sách","example":"我在家里读书。","examplePinyin":"Wǒ zài jiā li dúshū.","exampleVi":"Tôi đọc sách ở nhà."},{"emoji":"🤝","word":"和","pinyin":"hé","pos":"Giới từ","meaning":"và, cùng với","example":"我晚上和朋友们去外边唱歌。","examplePinyin":"Wǒ wǎnshang hé péngyoumen qù wàibian chàng gē.","exampleVi":"Buổi tối tôi cùng các bạn ra ngoài hát."},{"emoji":"🧑‍🤝‍🧑","word":"朋友","pinyin":"péngyou","pos":"Danh từ","meaning":"bạn bè","example":"我有很多朋友。","examplePinyin":"Wǒ yǒu hěn duō péngyou.","exampleVi":"Tôi có rất nhiều bạn."},{"emoji":"🎤","word":"唱","pinyin":"chàng","pos":"Động từ","meaning":"hát","example":"我晚上和朋友们去外边唱歌。","examplePinyin":"Wǒ wǎnshang hé péngyoumen qù wàibian chàng gē.","exampleVi":"Buổi tối tôi cùng các bạn ra ngoài hát."},{"emoji":"🎵","word":"歌","pinyin":"gē","pos":"Danh từ","meaning":"bài hát","example":"我们晚上去外边唱歌。","examplePinyin":"Wǒmen wǎnshang qù wàibian chàng gē.","exampleVi":"Buổi tối chúng tôi ra ngoài hát."},{"emoji":"🎶","word":"好听","pinyin":"hǎotīng","pos":"Tính từ","meaning":"hay (nghe)","example":"你唱歌很好听。","examplePinyin":"Nǐ chàng gē hěn hǎotīng.","exampleVi":"Bạn hát rất hay."},{"emoji":"📺","word":"电视","pinyin":"diànshì","pos":"Danh từ","meaning":"ti vi","example":"我在家里做饭、看电视。","examplePinyin":"Wǒ zài jiā li zuò fàn, kàn diànshì.","exampleVi":"Tôi nấu cơm, xem ti vi ở nhà."},{"emoji":"🐶","word":"狗","pinyin":"gǒu","pos":"Danh từ","meaning":"chó","example":"我也有一只小狗。","examplePinyin":"Wǒ yě yǒu yì zhī xiǎo gǒu.","exampleVi":"Tôi cũng có một chú chó nhỏ."},{"emoji":"🎮","word":"玩","pinyin":"wán","pos":"Động từ","meaning":"chơi","example":"我在家里做饭、看电视，和孩子们、小狗玩。","examplePinyin":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","exampleVi":"Tôi nấu cơm, xem ti vi ở nhà, và chơi với các con cùng chú chó nhỏ."}],"photoPrefix":"h1-9","structures":[{"han":"学校前边有一家电影院。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","meaning":"Trước trường có một rạp chiếu phim.","note":"Câu tồn tại: nơi chốn cộng 有 cộng số lượng, lượng từ và danh từ; 一家电影院 là một rạp chiếu phim."},{"han":"电影院前边是一家超市。","pinyin":"","meaning":"Trước rạp chiếu phim là một siêu thị.","note":"Câu tồn tại dùng 是: nơi chốn cộng 是 cộng danh từ; phủ định dùng 不是."},{"han":"我们七点在电影院外边见。","pinyin":"","meaning":"Bảy giờ chúng ta gặp nhau ngoài rạp chiếu phim.","note":"七点 là từ ngữ chỉ thời gian, 在电影院外边 là từ ngữ chỉ nơi chốn; thời gian đứng trước nơi chốn."},{"han":"这是我的第二本中文书。","pinyin":"Zhè shì wǒ de dì-èr běn Zhōngwén shū.","meaning":"Đây là quyển sách tiếng Trung thứ hai của tôi.","note":"第 cộng số từ cộng lượng từ để chỉ số thứ tự; 第二本 là quyển thứ hai."},{"han":"我明天上午在学校学习。","pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","meaning":"Sáng mai tôi học ở trường.","note":""}],"natural":["Mạch ý: hẹn xem phim tối nay, quyển sách trên ghế là của ai, kế hoạch cuối tuần của hai người.","Câu tồn tại: 有 nói có cái gì ở đâu, 是 nói ở đâu là cái gì; khi phủ định, trước tân ngữ không dùng cụm số lượng và lượng từ.","Khi thời gian và nơi chốn cùng làm trạng ngữ, thời gian đứng trước, nơi chốn đứng sau, rồi mới đến động từ."],"grammar":[{"error":"Khi phủ định đừng thêm số lượng trước tân ngữ, ví dụ đừng nói 桌子上没有一只小猫.","examples":"学校前边有一家电影院。(Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.) — Trước trường có một rạp chiếu phim. 电影院前边是一家超市。(Diànyǐngyuàn qiánbian shì yì jiā chāoshì.) — Trước rạp chiếu phim là một siêu thị. 桌子上没有小猫。(Zhuōzi shang méiyǒu xiǎo māo.) — Trên bàn không có mèo con.","explain":"Câu tồn hiện nói ở một nơi hoặc vị trí nào đó có người hoặc vật nào, thường dùng 有 hoặc 是 làm dấu hiệu. Khi phủ định, trước tân ngữ không dùng cụm số lượng.","formula":"Nơi chốn + 有/是 + (số lượng + lượng từ) + người/vật","tip":"Dùng 有 khi nói có cái gì, dùng 是 khi nói cái đó là cái gì, phủ định của 有 là 没有, phủ định của 是 là 不是.","title":"Câu tồn hiện 存现句 (1): 有/是 chỉ sự tồn tại ở một nơi"},{"error":"Đừng đảo thứ tự, ví dụ đừng nói 我们在电影院外边七点见.","examples":"我们七点在电影院外边见。(Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.) — 7 giờ chúng tôi gặp nhau ở ngoài rạp chiếu phim. 安妮下午在家里学中文。(Ānnī xiàwǔ zài jiā li xué Zhōngwén.) — Buổi chiều An Ni học tiếng Trung ở nhà. 陈天中明天中午在学校吃午饭。(Chén Tiānzhōng míngtiān zhōngwǔ zài xuéxiào chī wǔfàn.) — Trưa mai Trần Thiên Trung ăn trưa ở trường.","explain":"Khi từ chỉ thời gian và từ chỉ nơi chốn cùng làm trạng ngữ, từ chỉ thời gian phải đứng trước từ chỉ nơi chốn.","formula":"Chủ ngữ + từ chỉ thời gian + 在 + nơi chốn + động từ","tip":"Nhớ thứ tự cố định: thời gian, rồi đến nơi chốn, rồi mới đến động từ.","title":"Thứ tự trạng ngữ: thời gian đứng trước nơi chốn"},{"error":"Đừng quên 第 khi nói số thứ tự, ví dụ muốn nói quyển thứ hai thì phải nói 第二本 chứ không nói 二本.","examples":"第一，第二，第三。(Dì yī, dì èr, dì sān.) — Thứ nhất, thứ hai, thứ ba. 第一个学生，第一本书。(Dì yí gè xuéshēng, dì yì běn shū.) — Học sinh thứ nhất, quyển sách thứ nhất. 这是我的第二本中文书。(Zhè shì wǒ de dì èr běn Zhōngwén shū.) — Đây là quyển sách tiếng Trung thứ hai của tôi.","explain":"第 đứng trước số từ chỉ thứ tự để tạo số thứ tự. Cấu trúc cơ bản: 第 + số từ, hoặc 第 + số từ + lượng từ + (danh từ).","formula":"第 + số từ (+ lượng từ + danh từ)","tip":"第 luôn đứng ngay trước số từ, không tách ra.","title":"Tiền tố 第 chỉ số thứ tự"}],"phonetics":{"audio":"h1-phon-9.mp3","sections":[{"exercise":{"instruction":"听录音，给音节标声调，并大声朗读。","instructionVi":"Nghe ghi âm, đánh dấu thanh điệu cho âm tiết và đọc to.","items":["hao","xie","nin","zhong","tongxue","dajia","zaijian","renshi"]},"title":"声调标写","titleVi":"Cách đánh dấu thanh điệu","track":"9-1"},{"exercise":{"instruction":"听录音，选出每组音节里声调不同的一个。","instructionVi":"Nghe ghi âm, chọn âm tiết có thanh điệu khác trong mỗi nhóm.","items":["(1) A qián B xiǎo C nián","(2) A cháng B shū C zhōng","(3) A gǒu B běn C xué","(4) A biàn B gē C dì"]},"title":"声调辨析","titleVi":"Phân biệt thanh điệu","track":"9-1"}]}},{"num":10,"emoji":"🍎","han":"这儿的苹果真便宜！","pinyin":"Zhèr de píngguǒ zhēn piányi!","translation":"Táo ở đây rẻ thật!","theme":"Mua sắm và giá cả","vocab":[{"emoji":"☕","word":"杯子","pinyin":"bēizi","pos":"Danh từ","meaning":"cái cốc","example":"请问，有杯子吗？","examplePinyin":"Qǐngwèn, yǒu bēizi ma?","exampleVi":"Xin hỏi, có cốc không ạ?"},{"emoji":"🧑‍💼","word":"售货员","pinyin":"shòuhuòyuán","pos":"Danh từ","meaning":"người bán hàng","example":"售货员说：这些五块钱一个。","examplePinyin":"Shòuhuòyuán shuō: Zhèxiē wǔ kuài qián yí ge.","exampleVi":"Người bán hàng nói: Những cái này năm đồng một cái."},{"emoji":"👉","word":"这边","pinyin":"zhèbiān","pos":"Đại từ","meaning":"bên này, chỗ này","example":"有，杯子在这边。","examplePinyin":"Yǒu, bēizi zài zhèbiān.","exampleVi":"Có, cốc ở bên này."},{"emoji":"💰","word":"钱","pinyin":"qián","pos":"Danh từ","meaning":"tiền","example":"多少钱一个？","examplePinyin":"Duōshao qián yí ge?","exampleVi":"Một cái bao nhiêu tiền?"},{"emoji":"👉","word":"这些","pinyin":"zhèxiē","pos":"Đại từ","meaning":"những cái này","example":"这些五块钱一个。","examplePinyin":"Zhèxiē wǔ kuài qián yí ge.","exampleVi":"Những cái này năm đồng một cái."},{"emoji":"💵","word":"块","pinyin":"kuài","pos":"Lượng từ","meaning":"đồng (tiền)","example":"苹果三块五一斤。","examplePinyin":"Píngguǒ sān kuài wǔ yì jīn.","exampleVi":"Táo ba đồng rưỡi một cân."},{"emoji":"👉","word":"那些","pinyin":"nàxiē","pos":"Đại từ","meaning":"những cái kia","example":"那些十块钱一个。","examplePinyin":"Nàxiē shí kuài qián yí ge.","exampleVi":"Những cái kia mười đồng một cái."},{"emoji":"📍","word":"这儿","pinyin":"zhèr","pos":"Đại từ","meaning":"đây, chỗ này","example":"这儿的水果真不少！","examplePinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!","exampleVi":"Hoa quả ở đây nhiều thật!"},{"emoji":"🍎","word":"水果","pinyin":"shuǐguǒ","pos":"Danh từ","meaning":"hoa quả","example":"我想买一些水果。","examplePinyin":"Wǒ xiǎng mǎi yìxiē shuǐguǒ.","exampleVi":"Tôi muốn mua một ít hoa quả."},{"emoji":"🔢","word":"少","pinyin":"shǎo","pos":"Tính từ","meaning":"ít","example":"这儿的水果真不少！","examplePinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!","exampleVi":"Hoa quả ở đây nhiều thật!"},{"emoji":"⚖️","word":"斤","pinyin":"jīn","pos":"Lượng từ","meaning":"cân (500g)","example":"苹果三块五一斤。","examplePinyin":"Píngguǒ sān kuài wǔ yì jīn.","exampleVi":"Táo ba đồng rưỡi một cân."},{"emoji":"🍎","word":"苹果","pinyin":"píngguǒ","pos":"Danh từ","meaning":"táo","example":"我想买两斤苹果。","examplePinyin":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","exampleVi":"Tôi muốn mua hai cân táo."},{"emoji":"💲","word":"便宜","pinyin":"piányi","pos":"Tính từ","meaning":"rẻ","example":"苹果很便宜。","examplePinyin":"Píngguǒ hěn piányi.","exampleVi":"Táo rất rẻ."},{"emoji":"🏪","word":"商店","pinyin":"shāngdiàn","pos":"Danh từ","meaning":"cửa hàng","example":"这家商店衣服真多！","examplePinyin":"Zhè jiā shāngdiàn yīfu zhēn duō!","exampleVi":"Cửa hàng này nhiều quần áo thật!"},{"emoji":"👕","word":"衣服","pinyin":"yīfu","pos":"Danh từ","meaning":"quần áo","example":"这些是女孩子穿的衣服。","examplePinyin":"Zhèxiē shì nǚ háizi chuān de yīfu.","exampleVi":"Đây là quần áo con gái mặc."},{"emoji":"👕","word":"件","pinyin":"jiàn","pos":"Lượng từ","meaning":"cái, chiếc","example":"这件一百元，怎么样？","examplePinyin":"Zhè jiàn yìbǎi yuán, zěnmeyàng?","exampleVi":"Cái này một trăm đồng, thế nào?"},{"emoji":"💴","word":"元","pinyin":"yuán","pos":"Lượng từ","meaning":"đồng (nhân dân tệ)","example":"这件衣服一百元。","examplePinyin":"Zhè jiàn yīfu yìbǎi yuán.","exampleVi":"Cái áo này một trăm đồng."},{"emoji":"🤔","word":"怎么样","pinyin":"zěnmeyàng","pos":"Đại từ","meaning":"thế nào","example":"这个杯子怎么样？","examplePinyin":"Zhège bēizi zěnmeyàng?","exampleVi":"Cái cốc này thế nào?"},{"emoji":"💸","word":"贵","pinyin":"guì","pos":"Tính từ","meaning":"đắt","example":"好看，也不贵。","examplePinyin":"Hǎokàn, yě bù guì.","exampleVi":"Đẹp, cũng không đắt."},{"emoji":"👕","word":"穿","pinyin":"chuān","pos":"Động từ","meaning":"mặc","example":"小雪能穿，买一件吧。","examplePinyin":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","exampleVi":"Tiểu Tuyết mặc được, mua một cái nhé."},{"emoji":"👧","word":"女","pinyin":"nǚ","pos":"Tính từ","meaning":"nữ","example":"这些是女孩子穿的衣服。","examplePinyin":"Zhèxiē shì nǚ háizi chuān de yīfu.","exampleVi":"Đây là quần áo con gái mặc."},{"emoji":"👦","word":"男","pinyin":"nán","pos":"Tính từ","meaning":"nam","example":"男孩子的衣服在那儿。","examplePinyin":"Nán háizi de yīfu zài nàr.","exampleVi":"Quần áo con trai ở đằng kia."},{"emoji":"📍","word":"那儿","pinyin":"nàr","pos":"Đại từ","meaning":"đó, chỗ đó","example":"男孩子的衣服在那儿。","examplePinyin":"Nán háizi de yīfu zài nàr.","exampleVi":"Quần áo con trai ở đằng kia."}],"photoPrefix":"h1-10","structures":[{"han":"多少钱一个？","pinyin":"Duōshao qián yí ge?","meaning":"Một cái bao nhiêu tiền?","note":"多少 hỏi số lượng, 钱 là tiền; 一个 là một cái, lượng từ 个 sau số từ 一."},{"han":"苹果三块五一斤。","pinyin":"Píngguǒ sān kuài wǔ yì jīn.","meaning":"Táo ba đồng rưỡi một cân.","note":"三块五 là ba đồng rưỡi; 一斤 là một cân; cấu trúc giá tiền cộng lượng từ chỉ đơn vị tính."},{"han":"这儿的苹果真便宜！","pinyin":"Zhèr de píngguǒ zhēn piányi!","meaning":"Táo ở đây rẻ thật!","note":"便宜 là tính từ trực tiếp làm vị ngữ, không cần 是; 真 là phó từ chỉ mức độ, đứng trước tính từ."},{"han":"这件一百元，怎么样？","pinyin":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","meaning":"Cái này một trăm đồng, thế nào?","note":"怎么样 là đại từ nghi vấn hỏi ý kiến hoặc đánh giá, đứng cuối câu; trả lời bằng tính từ như 好看, 不贵."}],"natural":["Mạch ý: mua cốc ở cửa hàng nhỏ, mua táo ở chợ, mua quần áo cho con ở trung tâm thương mại.","Nói tiền: 元, 角, 分 viết thành chữ là 块, 毛, 分; thứ tự từ lớn đến nhỏ là 元/块, 角/毛, 分; số 0 ở giữa đọc 零.","Tính từ làm vị ngữ không dùng 是: 这儿的苹果真便宜, 我的房间不大; 怎么样 hỏi ý kiến, thường trả lời bằng tính từ."],"grammar":[{"error":"Đừng đảo thứ tự các đơn vị, phải nói từ đơn vị lớn đến đơn vị nhỏ, và đừng quên đọc 零 khi ở giữa có đơn vị bằng không.","examples":"三块。(Sān kuài.) — Ba đồng. 三块二。(Sān kuài èr.) — Ba đồng hai hào. 二百零二块两毛。(Èrbǎi líng èr kuài liǎng máo.) — Hai trăm linh hai đồng hai hào.","explain":"Tiền Trung Quốc gọi là nhân dân tệ. Đơn vị từ lớn đến nhỏ là 元, 角, 分, trong khẩu ngữ lần lượt gọi là 块, 毛, 分. Thứ tự diễn đạt là 元/块, rồi đến 角/毛, rồi đến 分.","formula":"Số + 元/块 + (số + 角/毛) + (số + 分), thứ tự từ lớn đến nhỏ","tip":"Nói ba đồng hai hào thì nói 三块二, không cần nói thêm 毛 ở cuối.","title":"Cách nói số tiền 钱数的表达: 元/块, 角/毛, 分"},{"error":"Đừng thêm 是 trước tính từ, ví dụ đừng nói 我的房间是不大.","examples":"这儿的水果真不少！(Zhèr de shuǐguǒ zhēn bù shǎo!) — Hoa quả ở đây thật không ít! 我的房间不大。(Wǒ de fángjiān bú dà.) — Phòng của tôi không lớn. 那个苹果好吃。(Nàge píngguǒ hǎochī.) — Quả táo kia ngon.","explain":"Tính từ có thể trực tiếp làm vị ngữ, trước tính từ có thể thêm phó từ chỉ mức độ hoặc phó từ phủ định.","formula":"Chủ ngữ + (phó từ mức độ: 很/真/太, hoặc 不) + tính từ","tip":"Trước tính từ thường thêm 很, 真 hoặc 不, nhưng không thêm 是.","title":"Câu vị ngữ tính từ 形容词谓语句"},{"error":"Đừng đặt 怎么样 ở giữa câu trước động từ như 怎么, 怎么样 đứng cuối câu hỏi.","examples":"这个杯子怎么样？我很喜欢，也不贵。(Zhège bēizi zěnmeyàng? Wǒ hěn xǐhuan, yě bú guì.) — Cái cốc này thế nào? Tôi rất thích, cũng không đắt. 这本书怎么样？很好看。(Zhè běn shū zěnmeyàng? Hěn hǎokàn.) — Quyển sách này thế nào? Rất đẹp. 这个菜怎么样？这个菜不太好吃，我不喜欢。(Zhège cài zěnmeyàng? Zhège cài bú tài hǎochī, wǒ bù xǐhuan.) — Món này thế nào? Món này không ngon lắm, tôi không thích.","explain":"怎么样 dùng để hỏi ý kiến hoặc hỏi về tình hình, trạng thái của sự vật, cấu trúc cơ bản là ...怎么样？","formula":"Danh từ/chủ ngữ + 怎么样？","tip":"Trả lời câu hỏi 怎么样 bằng một nhận xét, ví dụ 很好看, 也不贵 hoặc 不太好吃.","title":"Đại từ nghi vấn 怎么样 (thế nào, ra sao)"}],"phonetics":{"audio":"h1-phon-10.mp3","sections":[{"exercise":{"instruction":"听录音，给音节标声调，并大声朗读。","instructionVi":"Nghe ghi âm, đánh dấu thanh điệu cho âm tiết và đọc to.","items":["dui","jia","guo","xiang","chaoshi","niunai","shangwu","dianying"]},"title":"声调标写","titleVi":"Cách đánh dấu thanh điệu","track":"10-1"},{"exercise":{"instruction":"听录音，选出每组音节里声调不同的一个。","instructionVi":"Nghe ghi âm, chọn âm tiết có thanh điệu khác trong mỗi nhóm.","items":["(1) A zuò B zì C zhuō","(2) A xiě B chá C jiě","(3) A chuān B qù C fēn","(4) A yǒu B shuí C rén","(5) A wàibian B zhège C yīyuàn"]},"title":"声调辨析","titleVi":"Phân biệt thanh điệu","track":"10-1"}]}},{"emoji":"🎓","grammar":[{"error":"Đừng thêm 吗 vào cuối câu hỏi chính phản, và hỏi chuyện đã xảy ra thì dùng 没, không dùng 不.","examples":"它是不是在超市后边？ (Tā shì bù shì zài chāoshì hòubian?) — Nó có phải ở phía sau siêu thị không? 你去没去学校？ (Nǐ qù méi qù xuéxiào?) — Bạn đã đi đến trường chưa? 这件衣服好看不好看？ (Zhè jiàn yīfu hǎokàn bù hǎokàn?) — Chiếc áo này có đẹp không?","explain":"Câu hỏi chính phản lặp lại động từ hoặc tính từ ở dạng khẳng định rồi phủ định, không cần dùng 吗. Động từ dùng 不 hoặc 没, tính từ chỉ dùng 不.","formula":"× + 不/没 + ×, trong đó × là động từ hoặc tính từ","tip":"Hỏi việc đã xảy ra thì dùng 没, hỏi việc thường xuyên hoặc tính chất thì dùng 不.","title":"Câu hỏi chính phản 正反问"},{"error":"Đừng đặt 在/正在 sau động từ, và đừng dùng 不 để phủ định hành động đang diễn ra, phải dùng 没.","examples":"你还在读大学吗？ (Nǐ hái zài dú dàxué ma?) — Bạn vẫn đang học đại học à? 学生们在/正在上课呢。 (Xuéshengmen zài/zhèngzài shàngkè ne.) — Các học sinh đang lên lớp. 我们读书呢。 (Wǒmen dúshū ne.) — Chúng tôi đang đọc sách.","explain":"Phó từ thời gian 在 và 正在 đứng trước động từ, diễn tả hành động đang diễn ra hoặc tình huống đang tiếp tục. Ngoài hai dạng trên, còn dạng động từ + 呢 cũng diễn tả việc đang làm.","formula":"在/正在 + Động từ, 在/正在 + Động từ + 呢, Động từ + 呢","tip":"Trả lời phủ định thì dùng 没 (有), ví dụ: 我没买菜，买水果呢.","title":"Diễn tả đang làm gì với 在/正在"},{"error":"Đừng nhầm 要 diễn tả ý muốn với 要 diễn tả cần lấy đồ, và đừng quên 要 đứng trước động từ, không đứng sau.","examples":"他今天要和小朋友玩。 (Tā jīntiān yào hé xiǎopéngyou wán.) — Hôm nay cậu ấy muốn chơi với các bạn nhỏ. 妈妈要去超市。 (Māma yào qù chāoshì.) — Mẹ muốn đi siêu thị. 白家月要在家里学中文。 (Bái Jiāyuè yào zài jiālǐ xué Zhōngwén.) — Bạch Gia Nguyệt muốn học tiếng Trung ở nhà.","explain":"Động từ năng nguyện 要 đứng trước động từ, diễn tả muốn làm hoặc định làm việc gì đó.","formula":"Chủ ngữ + 要 + Động từ","tip":"要 ở đây khác với 要 làm động từ thường mang nghĩa cần hoặc muốn lấy thứ gì đó, ví dụ ở Bài 13 và Bài 15.","title":"Muốn và định làm gì với 要"}],"han":"我读大学呢","natural":["Mạch ý: tìm nhà hàng trên đường, gặp nhau ở nhà hàng hỏi chuyện học hành, sáng thứ Bảy ở nhà hỏi chuyện em trai.","Phân biệt ba cách nói đang làm gì: 在/正在 + động từ, 在/正在 + động từ + 呢, động từ + 呢; phủ định dùng 没 (有).","Câu hỏi chính phản: động từ dùng 不/没, tính từ chỉ dùng 不; chú ý 不 đổi thành bú trước thanh 4 như 不是, 不去."],"num":11,"photoPrefix":"h1-11","pinyin":"Wǒ dú dàxué ne","structures":[{"han":"还不知道，正在找呢。","pinyin":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","meaning":"Vẫn chưa biết, tôi đang tìm đây.","note":"正在 + động từ diễn tả hành động đang diễn ra; 呢 ở cuối câu nhấn mạnh trạng thái đang tiếp diễn."},{"han":"你开车没开车？","pinyin":"Nǐ kāichē méi kāichē?","meaning":"Anh có lái xe không?","note":"Câu hỏi chính phản: động từ 开车 lặp lại với 没 ở giữa, hỏi về hành động đã xảy ra hay chưa."},{"han":"弟弟起床没起床呢？","pinyin":"Dìdi qǐchuáng méi qǐchuáng ne?","meaning":"Em trai đã dậy chưa?","note":"Câu hỏi chính phản với động từ ly hợp 起床, thêm 呢 ở cuối câu làm giọng hỏi nhẹ nhàng hơn."},{"han":"他今天要和小朋友玩。","pinyin":"Tā jīntiān yào hé xiǎopéngyǒu wán.","meaning":"Hôm nay nó muốn chơi với các bạn nhỏ.","note":"要 đứng trước động từ 玩, diễn tả ý muốn hay dự định làm gì; đây là điểm ngữ pháp trọng tâm của bài."},{"han":"我读大学呢，还是大学生。","pinyin":"Wǒ dú dàxué ne, hái shì dàxuéshēng.","meaning":"Tôi đang học đại học đây, vẫn còn là sinh viên.","note":""}],"theme":"Đang làm gì, học đại học","translation":"Tôi đang học đại học đây","vocab":[{"emoji":"🕐","example":"你什么时候能到饭店？","examplePinyin":"Nǐ shénme shíhou néng dào fàndiàn?","exampleVi":"Bao giờ anh đến được nhà hàng?","meaning":"lúc, thời điểm","pinyin":"shíhou","pos":"Danh từ","word":"时候"},{"emoji":"🍽️","example":"这个饭店的菜很好吃。","examplePinyin":"Zhège fàndiàn de cài hěn hǎochī.","exampleVi":"Món ăn của nhà hàng này rất ngon.","meaning":"nhà hàng","pinyin":"fàndiàn","pos":"Danh từ","word":"饭店"},{"emoji":"💡","example":"我不知道。","examplePinyin":"Wǒ bù zhīdào.","exampleVi":"Tôi không biết.","meaning":"biết","pinyin":"zhīdào","pos":"Động từ","word":"知道"},{"emoji":"⏳","example":"我正在看电视。","examplePinyin":"Wǒ zhèngzài kàn diànshì.","exampleVi":"Tôi đang xem ti vi.","meaning":"đang (nhấn mạnh hành động đang diễn ra)","pinyin":"zhèngzài","pos":"Phó từ","word":"正在"},{"emoji":"🔍","example":"我在找我的手机。","examplePinyin":"Wǒ zài zhǎo wǒ de shǒujī.","exampleVi":"Tôi đang tìm điện thoại của tôi.","meaning":"tìm","pinyin":"zhǎo","pos":"Động từ","word":"找"},{"emoji":"🚗","example":"你开车没开车？","examplePinyin":"Nǐ kāichē méi kāichē?","exampleVi":"Anh có lái xe không?","meaning":"lái xe","pinyin":"kāichē","pos":"Động từ","word":"开车"},{"emoji":"🚙","example":"我没开车，坐车呢。","examplePinyin":"Wǒ méi kāichē, zuò chē ne.","exampleVi":"Tôi không lái xe, tôi đang ngồi xe đây.","meaning":"xe","pinyin":"chē","pos":"Danh từ","word":"车"},{"emoji":"▶️","example":"你还在读大学吗？","examplePinyin":"Nǐ hái zài dú dàxué ma?","exampleVi":"Anh vẫn còn đang học đại học à?","meaning":"đang (chỉ hành động đang tiếp diễn)","pinyin":"zài","pos":"Phó từ","word":"在"},{"emoji":"📖","example":"你还在读大学吗？","examplePinyin":"Nǐ hái zài dú dàxué ma?","exampleVi":"Anh vẫn còn đang học đại học à?","meaning":"học (ở trường), đọc","pinyin":"dú","pos":"Động từ","word":"读"},{"emoji":"🏫","example":"我读大学呢。","examplePinyin":"Wǒ dú dàxué ne.","exampleVi":"Tôi đang học đại học đây.","meaning":"đại học","pinyin":"dàxué","pos":"Danh từ","word":"大学"},{"emoji":"🧑‍🎓","example":"我还是大学生。","examplePinyin":"Wǒ hái shì dàxuéshēng.","exampleVi":"Tôi vẫn còn là sinh viên.","meaning":"sinh viên đại học","pinyin":"dàxuéshēng","pos":"Danh từ","word":"大学生"},{"emoji":"📚","example":"我学医，我们的课很多。","examplePinyin":"Wǒ xué yī, wǒmen de kè hěn duō.","exampleVi":"Tôi học y, chúng tôi có rất nhiều tiết học.","meaning":"học","pinyin":"xué","pos":"Động từ","word":"学"},{"emoji":"🩺","example":"我学医，我们的课很多。","examplePinyin":"Wǒ xué yī, wǒmen de kè hěn duō.","exampleVi":"Tôi học y, chúng tôi có rất nhiều tiết học.","meaning":"y học","pinyin":"yī","pos":"Danh từ","word":"医"},{"emoji":"👦","example":"弟弟起床没起床呢？","examplePinyin":"Dìdi qǐchuáng méi qǐchuáng ne?","exampleVi":"Em trai đã dậy chưa?","meaning":"em trai","pinyin":"dìdi","pos":"Danh từ","word":"弟弟"},{"emoji":"⏰","example":"没起床呢，还在睡觉。","examplePinyin":"Méi qǐchuáng ne, hái zài shuìjiào.","exampleVi":"Chưa dậy đâu, vẫn còn đang ngủ.","meaning":"thức dậy, ra khỏi giường","pinyin":"qǐchuáng","pos":"Động từ","word":"起床"},{"emoji":"😴","example":"没起床呢，还在睡觉。","examplePinyin":"Méi qǐchuáng ne, hái zài shuìjiào.","exampleVi":"Chưa dậy đâu, vẫn còn đang ngủ.","meaning":"ngủ","pinyin":"shuìjiào","pos":"Động từ","word":"睡觉"},{"emoji":"💤","example":"弟弟还在睡呢。","examplePinyin":"Dìdi hái zài shuì ne.","exampleVi":"Em trai vẫn còn đang ngủ.","meaning":"ngủ","pinyin":"shuì","pos":"Động từ","word":"睡"},{"emoji":"📍","example":"我的书在那里。","examplePinyin":"Wǒ de shū zài nàlǐ.","exampleVi":"Sách của tôi ở chỗ đó.","meaning":"ở đó, chỗ đó","pinyin":"nàlǐ","pos":"Đại từ","word":"那里"},{"emoji":"❓","example":"他今天去不去哪里？","examplePinyin":"Tā jīntiān qù bu qù nǎlǐ?","exampleVi":"Hôm nay nó có đi đâu không?","meaning":"ở đâu","pinyin":"nǎlǐ","pos":"Đại từ","word":"哪里"},{"emoji":"📅","example":"我昨天问他。","examplePinyin":"Wǒ zuótiān wèn tā.","exampleVi":"Hôm qua tôi hỏi nó.","meaning":"hôm qua","pinyin":"zuótiān","pos":"Danh từ","word":"昨天"},{"emoji":"🗣️","example":"我昨天问他。","examplePinyin":"Wǒ zuótiān wèn tā.","exampleVi":"Hôm qua tôi hỏi nó.","meaning":"hỏi","pinyin":"wèn","pos":"Động từ","word":"问"},{"emoji":"👉","example":"他对我说。","examplePinyin":"Tā duì wǒ shuō.","exampleVi":"Nó nói với tôi.","meaning":"với, đối với","pinyin":"duì","pos":"Giới từ","word":"对"},{"emoji":"💬","example":"他对我说，他不去。","examplePinyin":"Tā duì wǒ shuō, tā bú qù.","exampleVi":"Nó nói với tôi là nó không đi.","meaning":"nói","pinyin":"shuō","pos":"Động từ","word":"说"},{"emoji":"💭","example":"他今天要和小朋友玩。","examplePinyin":"Tā jīntiān yào hé xiǎopéngyǒu wán.","exampleVi":"Hôm nay nó muốn chơi với các bạn nhỏ.","meaning":"muốn, định","pinyin":"yào","pos":"Động từ năng nguyện","word":"要"},{"emoji":"🧒","example":"他今天要和小朋友玩。","examplePinyin":"Tā jīntiān yào hé xiǎopéngyǒu wán.","exampleVi":"Hôm nay nó muốn chơi với các bạn nhỏ.","meaning":"trẻ em, bạn nhỏ","pinyin":"xiǎopéngyǒu","pos":"Danh từ","word":"小朋友"}],"phonetics":{"audio":"h1-phon-11.mp3","sections":[{"exercise":{"instruction":"听录音，给音节标声调，并大声朗读。","instructionVi":"Nghe ghi âm, đánh dấu thanh điệu cho âm tiết và đọc to.","items":["chang","leng","hui","shuijiao","pingguo","jidan","daxuesheng","dianyingyuan"]},"title":"声调标写","titleVi":"Cách đánh dấu thanh điệu","track":"11-1"},{"exercise":{"instruction":"听录音，选出每组音节里声调不同的一个。","instructionVi":"Nghe ghi âm, chọn âm tiết có thanh điệu khác trong mỗi nhóm.","items":["(1) A mǎi B néng C méi","(2) A xīn B zhēn C rè","(3) A zuò fàn B zhēngzài C xiàbān","(4) A shíjiān B hǎotīng C míngtiān","(5) A Xīngqītiān B zhōngxuéshēng C chūzūchē"]},"title":"声调辨析","titleVi":"Phân biệt thanh điệu","track":"11-1"}]}},{"emoji":"🌧️","grammar":[{"error":"Đừng tưởng mọi câu đều phải có đủ chủ ngữ và vị ngữ, câu cảm thán và câu nói thời tiết thường lược hẳn chủ ngữ.","examples":"下雨了。 (Xià yǔ le.) — Trời mưa rồi. 下雪了。 (Xià xuě le.) — Trời tuyết rơi rồi. 上课了。 (Shàngkè le.) — Vào lớp rồi.","explain":"Câu không có chủ ngữ vị ngữ chỉ gồm một từ hoặc một cụm từ, không phân biệt chủ ngữ và vị ngữ, thường dùng trong khẩu ngữ, ví dụ nói về thời tiết hoặc chào hỏi cảm thán.","formula":"Từ hoặc cụm từ, không chia chủ ngữ và vị ngữ","tip":"Dạng câu này rất thường gặp khi nói về thời tiết, ví dụ 下雨了, 下雪了.","title":"Câu không có chủ ngữ vị ngữ 非主谓句"},{"error":"Câu phủ định với 没 thì cuối câu không thêm 了, ví dụ nói 没起床 chứ không nói 没起床了.","examples":"下雨了。 (Xià yǔ le.) — Trời mưa rồi. 十二点了，吃午饭吧。 (Shí'èr diǎn le, chī wǔfàn ba.) — 12 giờ rồi, ăn trưa thôi. 弟弟起床了吗？ (Dìdi qǐchuáng le ma?) — Em trai đã dậy chưa?","explain":"Trợ từ ngữ khí 了 (1) đứng ở cuối câu hoặc ở chỗ ngắt trong câu, diễn tả có sự thay đổi hoặc xuất hiện tình huống mới. Trả lời phủ định thì dùng 没, cuối câu không dùng 了.","formula":"Câu + 了, dùng ở cuối câu hoặc chỗ ngắt trong câu","tip":"了 (1) khác với 了 (2) ở Bài 14, 了 (1) gắn với cả câu và diễn tả thay đổi, còn 了 (2) gắn sau động từ và diễn tả hoàn thành.","title":"Trợ từ ngữ khí 了 (1)"},{"error":"Đừng dùng 太……了 với nghĩa vừa phải, mẫu này chỉ dùng khi mức độ đã rất cao.","examples":"太冷了！ (Tài lěng le!) — Lạnh quá! 这个杯子太小了。 (Zhège bēizi tài xiǎo le.) — Cái cốc này nhỏ quá. 我们今天太高兴了！ (Wǒmen jīntiān tài gāoxìng le!) — Hôm nay chúng tôi vui quá!","explain":"Mẫu 太……了 dùng để cảm thán mức độ rất cao hoặc rất sâu, thường mang giọng khen hoặc chê tùy ngữ cảnh.","formula":"太 + Tính từ/Động từ + 了","tip":"Trong mẫu này, 了 thường đi kèm để nhấn mạnh cảm thán, đừng bỏ 了.","title":"Mẫu cảm thán 太……了"}],"han":"昨天下雪了","natural":["Mạch ý: gọi điện hỏi thời tiết, gặp nhau trong thang máy hỏi chuyện ốm, bác sĩ khám và dặn dò.","了 (1) ở cuối câu chỉ sự thay đổi hay tình hình mới; phủ định dùng 没, cuối câu không dùng 了.","Cấu trúc 太……了 dùng để cảm thán mức độ rất cao; câu không chủ ngữ như 下雨了, 下雪了 rất thường gặp trong khẩu ngữ."],"num":12,"photoPrefix":"h1-12","pinyin":"Zuótiān xià xuě le","structures":[{"han":"这里的天不太好，下雨了。","pinyin":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","meaning":"Thời tiết chỗ này không tốt lắm, trời đang mưa.","note":"了 ở cuối câu chỉ tình hình mới xuất hiện: trước đó không mưa, bây giờ mưa rồi."},{"han":"是的，太冷了。","pinyin":"Shì de, tài lěng le.","meaning":"Đúng thế, lạnh quá.","note":"Cấu trúc 太 + tính từ + 了 dùng để cảm thán mức độ rất cao, ở đây là rất lạnh."},{"han":"昨天下雪了。","pinyin":"Zuótiān xià xuě le.","meaning":"Hôm qua trời có tuyết rơi.","note":"Câu không có chủ ngữ, vị ngữ rõ ràng, thường dùng trong khẩu ngữ; 了 cuối câu chỉ tình hình mới."},{"han":"回家后再喝些热水。","pinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","meaning":"Về nhà rồi uống thêm ít nước nóng nhé.","note":"了 sau động từ 喝 chỉ hành động uống sẽ xảy ra sau khi về nhà; 再 diễn tả hành động tiếp theo."},{"han":"昨天下雪了，太冷了。","pinyin":"Zuótiān xià xuě le, tài lěng le.","meaning":"Hôm qua trời có tuyết rơi, lạnh quá.","note":""}],"theme":"Thời tiết, bị ốm và khám bệnh","translation":"Hôm qua trời có tuyết rơi","vocab":[{"emoji":"🌤️","example":"今天天气怎么样？","examplePinyin":"Jīntiān tiānqì zěnmeyàng?","exampleVi":"Hôm nay thời tiết thế nào?","meaning":"thời tiết","pinyin":"tiānqì","pos":"Danh từ","word":"天气"},{"emoji":"📍","example":"这里的天不太好。","examplePinyin":"Zhèlǐ de tiān bú tài hǎo.","exampleVi":"Thời tiết chỗ này không tốt lắm.","meaning":"ở đây, chỗ này","pinyin":"zhèlǐ","pos":"Đại từ","word":"这里"},{"emoji":"🌤️","example":"这里的天不太好，下雨了。","examplePinyin":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","exampleVi":"Thời tiết chỗ này không tốt lắm, trời đang mưa.","meaning":"thời tiết; ngày (đơn vị đếm ngày)","pinyin":"tiān","pos":"Danh từ","word":"天"},{"emoji":"🌧️","example":"下雨了。","examplePinyin":"Xià yǔ le.","exampleVi":"Trời mưa rồi.","meaning":"mưa, trời mưa","pinyin":"xià yǔ","pos":"Động từ","word":"下雨"},{"emoji":"✨","example":"下雨了。","examplePinyin":"Xià yǔ le.","exampleVi":"Trời mưa rồi.","meaning":"(cuối câu) chỉ sự thay đổi hay tình hình mới","pinyin":"le","pos":"Trợ từ","word":"了"},{"emoji":"💧","example":"雨大吗？","examplePinyin":"Yǔ dà ma?","exampleVi":"Mưa to không?","meaning":"mưa","pinyin":"yǔ","pos":"Danh từ","word":"雨"},{"emoji":"🤏","example":"有点儿大，我觉得很冷。","examplePinyin":"Yǒudiǎnr dà, wǒ juéde hěn lěng.","exampleVi":"Hơi to, tôi thấy rất lạnh.","meaning":"hơi, một chút","pinyin":"yǒudiǎnr","pos":"Phó từ","word":"有点儿"},{"emoji":"💭","example":"我觉得很冷。","examplePinyin":"Wǒ juéde hěn lěng.","exampleVi":"Tôi thấy rất lạnh.","meaning":"cảm thấy, cho rằng","pinyin":"juéde","pos":"Động từ","word":"觉得"},{"emoji":"🥶","example":"太冷了。","examplePinyin":"Tài lěng le.","exampleVi":"Lạnh quá.","meaning":"lạnh","pinyin":"lěng","pos":"Tính từ","word":"冷"},{"emoji":"⬇️","example":"昨天下雪了。","examplePinyin":"Zuótiān xià xuě le.","exampleVi":"Hôm qua trời có tuyết rơi.","meaning":"rơi (mưa, tuyết)","pinyin":"xià","pos":"Động từ","word":"下"},{"emoji":"❄️","example":"昨天下雪了。","examplePinyin":"Zuótiān xià xuě le.","exampleVi":"Hôm qua trời có tuyết rơi.","meaning":"tuyết","pinyin":"xuě","pos":"Danh từ","word":"雪"},{"emoji":"🚶","example":"你昨天没来公司。","examplePinyin":"Nǐ zuótiān méi lái gōngsī.","exampleVi":"Hôm qua anh không đến công ty.","meaning":"đến","pinyin":"lái","pos":"Động từ","word":"来"},{"emoji":"🏢","example":"你昨天没来公司，生病了？","examplePinyin":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","exampleVi":"Hôm qua anh không đến công ty, bị ốm à?","meaning":"công ty","pinyin":"gōngsī","pos":"Danh từ","word":"公司"},{"emoji":"🤒","example":"你昨天没来公司，生病了？","examplePinyin":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","exampleVi":"Hôm qua anh không đến công ty, bị ốm à?","meaning":"bị ốm","pinyin":"shēngbìng","pos":"Động từ","word":"生病"},{"emoji":"🏥","example":"我昨天去医院看病了。","examplePinyin":"Wǒ zuótiān qù yīyuàn kànbìng le.","exampleVi":"Hôm qua tôi đi bệnh viện khám bệnh.","meaning":"đi khám bệnh","pinyin":"kànbìng","pos":"Động từ","word":"看病"},{"emoji":"🤧","example":"医生，我病了。","examplePinyin":"Yīshēng, wǒ bìng le.","exampleVi":"Bác sĩ, tôi bị ốm.","meaning":"ốm, bị bệnh","pinyin":"bìng","pos":"Động từ","word":"病"},{"emoji":"🤏","example":"吃一点儿药。","examplePinyin":"Chī yìdiǎnr yào.","exampleVi":"Uống một ít thuốc.","meaning":"một chút, một ít","pinyin":"yìdiǎnr","pos":"Số từ","word":"一点儿"},{"emoji":"💊","example":"吃一点儿药。","examplePinyin":"Chī yìdiǎnr yào.","exampleVi":"Uống một ít thuốc.","meaning":"thuốc","pinyin":"yào","pos":"Danh từ","word":"药"},{"emoji":"🏠","example":"回家后再喝些热水。","examplePinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","exampleVi":"Về nhà rồi uống thêm ít nước nóng nhé.","meaning":"về, trở về","pinyin":"huí","pos":"Động từ","word":"回"},{"emoji":"⏭️","example":"回家后再喝些热水。","examplePinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","exampleVi":"Về nhà rồi uống thêm ít nước nóng nhé.","meaning":"rồi mới, sau đó","pinyin":"zài","pos":"Phó từ","word":"再"},{"emoji":"🥤","example":"回家后再喝些热水。","examplePinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","exampleVi":"Về nhà rồi uống thêm ít nước nóng nhé.","meaning":"uống","pinyin":"hē","pos":"Động từ","word":"喝"},{"emoji":"🔥","example":"回家后再喝些热水。","examplePinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","exampleVi":"Về nhà rồi uống thêm ít nước nóng nhé.","meaning":"nóng, ấm","pinyin":"rè","pos":"Tính từ","word":"热"},{"emoji":"💧","example":"回家后再喝些热水。","examplePinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","exampleVi":"Về nhà rồi uống thêm ít nước nóng nhé.","meaning":"nước","pinyin":"shuǐ","pos":"Danh từ","word":"水"}],"phonetics":{"audio":"h1-phon-12.mp3","sections":[{"exercise":{"instruction":"听录音，选出每组音节里声调不同的一个。","instructionVi":"Nghe ghi âm, chọn âm tiết có thanh điệu khác trong mỗi nhóm.","items":["(1) A shuǐ B shuì C hěn","(2) A wèntí B kànbìng C diànshì","(3) A gāoxìng B fēicháng C zhīdào","(4) A qù chāoshì B zài shāngdiàn C duìbuqǐ"]},"title":"声调辨析","titleVi":"Phân biệt thanh điệu","track":"12-1"},{"exercise":{"instruction":"听录音，根据听到的音节选择对应的词语，并大声朗读。","instructionVi":"Nghe ghi âm, chọn từ tương ứng với âm tiết nghe được, sau đó đọc to.","items":["nǐ hǎo","míngzi","Zhōngguó","lǎoshī","háizi","xièxie"]},"title":"听音节，匹配词语。","titleVi":"Nghe âm tiết, nối với từ ngữ.","track":"12-1","words":[{"han":"你好","py":"","vi":"xin chào"},{"han":"老师","py":"","vi":"thầy giáo, cô giáo"},{"han":"谢谢","py":"","vi":"cảm ơn"},{"han":"孩子","py":"","vi":"con, trẻ con"},{"han":"名字","py":"","vi":"tên"},{"han":"中国","py":"","vi":"Trung Quốc"}]}]}},{"emoji":"🍵","grammar":[{"error":"Đừng đặt 可以 sau động từ, và đừng nhầm 可以 diễn tả được phép với 会 diễn tả biết làm.","examples":"我可以再问您一个问题吗？ (Wǒ kěyǐ zài wèn nín yí gè wèntí ma?) — Tôi có thể hỏi thầy thêm một câu nữa không? 你们可以看这本书。 (Nǐmen kěyǐ kàn zhè běn shū.) — Các bạn có thể xem quyển sách này. 我可以坐吗？ (Wǒ kěyǐ zuò ma?) — Tôi có thể ngồi không?","explain":"Động từ năng nguyện 可以 đứng trước động từ, diễn tả có thể, có khả năng hoặc được phép làm việc gì đó.","formula":"Chủ ngữ + 可以 + Động từ","tip":"Trả lời đồng ý thì chỉ cần nói 可以, kèm theo lời mời thì thêm 请, ví dụ: 可以，请坐！","title":"Động từ năng nguyện 可以"},{"error":"Đừng dùng 一下 với hành động kéo dài, cấu trúc này chỉ hợp với việc làm thử trong chốc lát.","examples":"你可以打电话问一下。 (Nǐ kěyǐ dǎ diànhuà wèn yíxià.) — Bạn có thể gọi điện hỏi thử một chút. 请休息一下。 (Qǐng xiūxi yíxià.) — Xin hãy nghỉ một lát. 你看一下吧。 (Nǐ kàn yíxià ba.) — Bạn xem thử một chút đi.","explain":"Trong bài này, cấu trúc động từ + 一下 diễn tả làm một lần hoặc thử làm, hành động diễn ra trong thời gian ngắn.","formula":"Động từ + 一下","tip":"一下 đọc nhẹ và ngắn, dùng để nói một cách lịch sự và nhẹ nhàng, ví dụ nhờ ai đó xem thử hoặc nghỉ một lát.","title":"Cấu trúc động từ + 一下"},{"error":"Đừng đảo thứ tự hai tân ngữ, phải nói 给我一杯牛奶, không nói 给一杯牛奶我.","examples":"请给我一杯牛奶。 (Qǐng gěi wǒ yì bēi niúnǎi.) — Xin cho tôi một cốc sữa. 白家月给安妮一个苹果。 (Bái Jiāyuè gěi Ānnī yí gè píngguǒ.) — Bạch Gia Nguyệt cho An Ni một quả táo. 我问老师两个问题。 (Wǒ wèn lǎoshī liǎng gè wèntí.) — Tôi hỏi thầy hai câu hỏi.","explain":"Câu hai tân ngữ là câu có một động từ mang hai tân ngữ. Trong quyển này chỉ học câu hai tân ngữ tạo bởi 给 và 问, tân ngữ chỉ người đứng trước, tân ngữ chỉ vật đứng sau.","formula":"Chủ ngữ + 给/问 + Người + Vật","tip":"Nhớ thứ tự: cho ai trước rồi mới nói cho cái gì, ví dụ 给我一杯牛奶, hỏi ai trước rồi mới nói hỏi mấy câu.","title":"Câu hai tân ngữ 双宾语句 (1)"}],"han":"请给我一杯茶","natural":["Mạch ý: hỏi thêm cô giáo một câu, gọi món ở quán cà phê, gọi món ở nhà hàng.","可以 đứng trước động từ diễn tả có thể, được phép; 动词 + 一下 diễn tả làm thử một chút, thời gian ngắn.","Câu song tân: 给 và 问 mang hai tân ngữ, tân ngữ chỉ người đứng trước tân ngữ chỉ vật."],"num":13,"photoPrefix":"h1-13","pinyin":"Qǐng gěi wǒ yì bēi chá","structures":[{"han":"王老师，我可以再问您一个问题吗？","pinyin":"Wǒ kěyǐ zài wèn nín yí ge wèntí ma?","meaning":"Cô Vương, em có thể hỏi thêm cô một câu nữa không ạ?","note":"可以 đứng trước động từ 问, diễn tả xin phép; 再 diễn tả hỏi thêm một lần nữa; đây là câu song tân với động từ 问."},{"han":"请给我一杯牛奶。","pinyin":"Qǐng gěi wǒ yì bēi niúnǎi.","meaning":"Cho tôi một ly sữa.","note":"请 + 给 + 我 + 一杯牛奶 là câu song tân: 给 mang hai tân ngữ, người nhận (我) và vật được cho (一杯牛奶)."},{"han":"我要一斤饺子。","pinyin":"Wǒ yào yì jīn jiǎozi.","meaning":"Tôi muốn một cân sủi cảo.","note":"要 ở đây là động từ chỉ muốn gọi món; 一斤 là số lượng, 饺子 là món ăn."},{"han":"40个太多了，我要一半吧。","pinyin":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","meaning":"40 cái nhiều quá, tôi lấy một nửa thôi.","note":"太多了 là cấu trúc cảm thán đã học ở bài 12; 一半 chỉ một nửa số lượng, dùng khi gọi món."},{"han":"我可以再问您一个问题吗？","pinyin":"Wǒ kěyǐ zài wèn nín yí ge wèntí ma?","meaning":"Em có thể hỏi thêm cô một câu nữa không ạ?","note":""},{"han":"请给我一杯茶吧。","pinyin":"Qǐng gěi wǒ yì bēi chá ba.","meaning":"Cho tôi một ly trà nhé.","note":""}],"theme":"Gọi món ăn, uống","translation":"Cho tôi một ly trà","vocab":[{"emoji":"✅","example":"我可以再问您一个问题吗？","examplePinyin":"Wǒ kěyǐ zài wèn nín yí ge wèntí ma?","exampleVi":"Em có thể hỏi thêm cô một câu nữa không ạ?","meaning":"có thể, được phép","pinyin":"kěyǐ","pos":"Động từ năng nguyện","word":"可以"},{"emoji":"🔁","example":"我可以再问您一个问题吗？","examplePinyin":"Wǒ kěyǐ zài wèn nín yí ge wèntí ma?","exampleVi":"Em có thể hỏi thêm cô một câu nữa không ạ?","meaning":"lại, thêm lần nữa","pinyin":"zài","pos":"Phó từ","word":"再"},{"emoji":"❓","example":"你有什么问题？","examplePinyin":"Nǐ yǒu shénme wèntí?","exampleVi":"Em có câu hỏi gì?","meaning":"câu hỏi, vấn đề","pinyin":"wèntí","pos":"Danh từ","word":"问题"},{"emoji":"🛒","example":"那个小店卖不卖手机？","examplePinyin":"Nàge xiǎo diàn mài bu mài shǒujī?","exampleVi":"Cửa hàng nhỏ kia có bán điện thoại không ạ?","meaning":"bán","pinyin":"mài","pos":"Động từ","word":"卖"},{"emoji":"📞","example":"你可以打电话问一下。","examplePinyin":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","exampleVi":"Em có thể gọi điện hỏi thử xem.","meaning":"gọi điện thoại","pinyin":"dǎ diànhuà","pos":"Động từ","word":"打电话"},{"emoji":"🤏","example":"你可以打电话问一下。","examplePinyin":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","exampleVi":"Em có thể gọi điện hỏi thử xem.","meaning":"một chút, một lần (sau động từ)","pinyin":"yíxià","pos":"Số từ","word":"一下"},{"emoji":"🧑‍🍳","example":"服务员，请给我一杯茶。","examplePinyin":"Fúwùyuán, qǐng gěi wǒ yì bēi chá.","exampleVi":"Nhân viên ơi, cho tôi một ly trà.","meaning":"nhân viên phục vụ","pinyin":"fúwùyuán","pos":"Danh từ","word":"服务员"},{"emoji":"👩","example":"女士，请坐！您喝什么？","examplePinyin":"Nǚshì, qǐng zuò! Nín hē shénme?","exampleVi":"Thưa cô, mời cô ngồi! Cô uống gì ạ?","meaning":"quý bà, cô (cách gọi lịch sự)","pinyin":"nǚshì","pos":"Danh từ","word":"女士"},{"emoji":"🙏","example":"请给我一杯牛奶。","examplePinyin":"Qǐng gěi wǒ yì bēi niúnǎi.","exampleVi":"Cho tôi một ly sữa.","meaning":"mời, xin (lịch sự)","pinyin":"qǐng","pos":"Động từ","word":"请"},{"emoji":"🪑","example":"女士，请坐！","examplePinyin":"Nǚshì, qǐng zuò!","exampleVi":"Thưa cô, mời cô ngồi!","meaning":"ngồi","pinyin":"zuò","pos":"Động từ","word":"坐"},{"emoji":"🎁","example":"请给我一杯牛奶。","examplePinyin":"Qǐng gěi wǒ yì bēi niúnǎi.","exampleVi":"Cho tôi một ly sữa.","meaning":"cho, đưa","pinyin":"gěi","pos":"Động từ","word":"给"},{"emoji":"🥛","example":"请给我一杯牛奶。","examplePinyin":"Qǐng gěi wǒ yì bēi niúnǎi.","exampleVi":"Cho tôi một ly sữa.","meaning":"cốc, ly","pinyin":"bēi","pos":"Danh từ","word":"杯"},{"emoji":"🛎️","example":"我要一斤饺子。","examplePinyin":"Wǒ yào yì jīn jiǎozi.","exampleVi":"Tôi muốn một cân sủi cảo.","meaning":"muốn (gọi món), cần","pinyin":"yào","pos":"Động từ","word":"要"},{"emoji":"🍳","example":"我还没吃早饭。","examplePinyin":"Wǒ hái méi chī zǎofàn.","exampleVi":"Tôi vẫn chưa ăn sáng.","meaning":"bữa sáng","pinyin":"zǎofàn","pos":"Danh từ","word":"早饭"},{"emoji":"👉","example":"再要这个面包和鸡蛋吧。","examplePinyin":"Zài yào zhège miànbāo hé jīdàn ba.","exampleVi":"Cho thêm bánh mì và trứng này nhé.","meaning":"cái này","pinyin":"zhège","pos":"Đại từ","word":"这个"},{"emoji":"🍞","example":"再要这个面包和鸡蛋吧。","examplePinyin":"Zài yào zhège miànbāo hé jīdàn ba.","exampleVi":"Cho thêm bánh mì và trứng này nhé.","meaning":"bánh mì","pinyin":"miànbāo","pos":"Danh từ","word":"面包"},{"emoji":"🥚","example":"再要这个面包和鸡蛋吧。","examplePinyin":"Zài yào zhège miànbāo hé jīdàn ba.","exampleVi":"Cho thêm bánh mì và trứng này nhé.","meaning":"trứng gà","pinyin":"jīdàn","pos":"Danh từ","word":"鸡蛋"},{"emoji":"👨","example":"先生，请坐！您要什么？","examplePinyin":"Xiānsheng, qǐng zuò! Nín yào shénme?","exampleVi":"Thưa ông, mời ông ngồi! Ông muốn gì ạ?","meaning":"ông, ngài (cách gọi lịch sự)","pinyin":"xiānsheng","pos":"Danh từ","word":"先生"},{"emoji":"½","example":"40个太多了，我要一半吧。","examplePinyin":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","exampleVi":"40 cái nhiều quá, tôi lấy một nửa thôi.","meaning":"một nửa","pinyin":"yíbàn","pos":"Số từ","word":"一半"},{"emoji":"🍵","example":"请给我一杯茶吧。","examplePinyin":"Qǐng gěi wǒ yì bēi chá ba.","exampleVi":"Cho tôi một ly trà nhé.","meaning":"trà","pinyin":"chá","pos":"Danh từ","word":"茶"}],"phonetics":{"audio":"h1-phon-13.mp3","sections":[{"exercise":{"instruction":"听录音，选出每组音节里声调不同的一个。","instructionVi":"Nghe ghi âm, chọn âm tiết có thanh điệu khác trong mỗi nhóm.","items":["(1) A jiǎozi B shuǐguǒ C zǎoshang","(2) A xuéxí B fángjiān C míngtiān","(3) A mǎi bāozi B xiě Hànzì C yǒu bēizi","(4) A máng gōngzuò B lái shǔdiàn C zhǎo tóngxué"]},"title":"声调辨析","titleVi":"Phân biệt thanh điệu","track":"13-1"},{"exercise":{"instruction":"听录音，根据听到的音节选择对应的词语，并大声朗读。","instructionVi":"Nghe ghi âm, chọn từ tương ứng với âm tiết nghe được, sau đó đọc to.","items":["nǐ hǎo","gōngsī","xiānsheng","gōngzuò","jiǎozi","péngyou"]},"title":"听音节，匹配词语。","titleVi":"Nghe âm tiết, nối với từ ngữ.","track":"13-1","words":[{"han":"你好","py":"","vi":"xin chào"},{"han":"饺子","py":"","vi":"sủi cảo"},{"han":"公司","py":"","vi":"công ty"},{"han":"朋友","py":"","vi":"bạn bè"},{"han":"先生","py":"","vi":"ông, ngài (cách gọi lịch sự)"},{"han":"工作","py":"","vi":"công việc"}]}]}},{"emoji":"🎬","grammar":[{"error":"Câu phủ định với 没 thì không thêm 了 sau động từ, ví dụ nói 没去 chứ không nói 没去了.","examples":"我看了一个电影。 (Wǒ kànle yí gè diànyǐng.) — Tôi đã xem một bộ phim. 我买了一个新电脑。 (Wǒ mǎile yí gè xīn diànnǎo.) — Tôi đã mua một cái máy tính mới. 我昨天没去商店买东西。 (Wǒ zuótiān méi qù shāngdiàn mǎi dōngxi.) — Hôm qua tôi không đi cửa hàng mua đồ.","explain":"Trợ từ động thái 了 (2) đứng sau động từ, diễn tả hành động đã xảy ra hoặc đã hoàn thành. Khi phủ định thì dùng 没, không thêm 了.","formula":"Động từ + 了 + (Tân ngữ)","tip":"了 (2) khác với 了 (1) ở Bài 12, 了 (2) gắn ngay sau động từ, còn 了 (1) gắn ở cuối câu để diễn tả thay đổi.","title":"Trợ từ động thái 了 (2)"},{"error":"Đừng chèn tùy tiện bất cứ từ nào vào giữa từ li hợp, sách nói rõ thành phần có thể chèn vào rất hạn chế, thường chỉ là 了, số lượng hoặc tên môn học.","examples":"睡了觉。 (Shuì le jiào.) — Đã ngủ một giấc. 上中文课。 (Shàng Zhōngwén kè.) — Học tiết tiếng Trung. 说了很多话。 (Shuō le hěn duō huà.) — Đã nói rất nhiều lời.","explain":"Các từ như 上课, 下课, 上班, 下班, 说话, 读书, 睡觉, 看病, 生病 là một loại cấu trúc động từ đặc biệt, vừa hợp lại được vừa tách ra được. Hợp lại thì là một từ, tách ra chèn thêm thành phần khác vào giữa thì thành cụm từ, nên gọi là từ li hợp. Khi tách ra, thành phần có thể chèn vào rất hạn chế.","formula":"Dạng hợp: Động từ + Tân ngữ, dạng li: Động từ + 了/Thành phần khác + Tân ngữ","tip":"Muốn thêm 了 hoặc số lượng thì chèn vào giữa hai chữ, ví dụ 睡了觉, 睡了一觉, 上了中文课, không đặt 了 sau cả từ.","title":"Từ li hợp 离合词 (1)"},{"error":"Đừng đặt từ phủ định trước 都, phải nói 都没听见, không nói 没都听见.","examples":"我们都会写了。 (Wǒmen dōu huì xiě le.) — Chúng tôi đều biết viết rồi. 我和我的朋友们都去。 (Wǒ hé wǒ de péngyoumen dōu qù.) — Tôi và các bạn tôi đều đi. 同学们都没听见。 (Tóngxuémen dōu méi tīngjiàn.) — Các bạn học đều không nghe thấy.","explain":"Phó từ phạm vi 都 diễn tả tất cả hoặc tổng quát, đối tượng được tổng quát đặt trước 都. Khi phủ định, từ phủ định đặt sau 都.","formula":"Đối tượng được nói đến + 都 + Động từ/Tính từ","tip":"Muốn nhấn mạnh tất cả mọi người đều làm gì thì đặt 都 trước động từ, phủ định thì nói 都没 hoặc 都不.","title":"Phó từ phạm vi 都"}],"han":"我看了一个电影","natural":["Mạch ý: kể chuyện đi tàu hỏa, cô giáo hỏi tình hình học tập, bố mẹ bàn chuyện con đi học.","了 (2) sau động từ chỉ hành động đã xảy ra hay hoàn thành; phủ định dùng 没, không dùng 了.","Động từ ly hợp như 上课, 睡觉, 看病, 生病 có thể tách ra: 睡了觉, 上了课, 生了病; 都 diễn tả tất cả, từ phủ định đứng sau 都."],"num":14,"photoPrefix":"h1-14","pinyin":"Wǒ kànle yí ge diànyǐng","structures":[{"han":"我看了一个电影。","pinyin":"Wǒ kànle yí ge diànyǐng.","meaning":"Tôi đã xem một bộ phim.","note":"了 sau động từ 看 chỉ hành động xem phim đã xảy ra và hoàn thành; đây là điểm ngữ pháp trọng tâm của bài."},{"han":"我们都会写了。","pinyin":"Wǒmen dōu huì xiě le.","meaning":"Chúng em đều biết viết rồi ạ.","note":"都 đứng sau chủ ngữ 我们, diễn tả tất cả mọi người đều biết viết; phủ định của 都 đặt từ phủ định sau 都."},{"han":"上学后，他们都忙了。","pinyin":"Shàngxué hòu, tāmen dōu máng le.","meaning":"Sau khi đi học, chúng nó đều sẽ bận.","note":"上学 là động từ ly hợp: 上 và 学 có thể tách ra, ở đây 上学后 là dạng hợp; 都 diễn tả cả hai đứa trẻ đều bận."},{"han":"太晚了，睡觉吧。","pinyin":"Shì de. Tài wǎn le, shuìjiào ba.","meaning":"Muộn quá rồi, đi ngủ thôi.","note":"太晚了 là cấu trúc cảm thán đã học ở bài 12; 睡觉 là động từ ly hợp, ở đây dùng dạng hợp với 吧 diễn tả đề nghị."}],"theme":"Chuyện đã xảy ra, học tập","translation":"Tôi đã xem một bộ phim","vocab":[{"emoji":"⬆️","example":"你们上火车后看见王老师了吗？","examplePinyin":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","exampleVi":"Sau khi lên tàu các cậu có nhìn thấy cô Vương không?","meaning":"lên (xe, tàu); bắt đầu (theo giờ cố định)","pinyin":"shàng","pos":"Động từ","word":"上"},{"emoji":"🚆","example":"你们上火车后看见王老师了吗？","examplePinyin":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","exampleVi":"Sau khi lên tàu các cậu có nhìn thấy cô Vương không?","meaning":"tàu hỏa","pinyin":"huǒchē","pos":"Danh từ","word":"火车"},{"emoji":"🕛","example":"中午车开后，有些人在看书。","examplePinyin":"Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū.","exampleVi":"Sau khi tàu chạy buổi trưa, có người đọc sách.","meaning":"buổi trưa","pinyin":"zhōngwǔ","pos":"Danh từ","word":"中午"},{"emoji":"🚗","example":"中午车开后，有些人在看书。","examplePinyin":"Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū.","exampleVi":"Sau khi tàu chạy buổi trưa, có người đọc sách.","meaning":"(xe cộ) khởi hành, chạy","pinyin":"kāi","pos":"Động từ","word":"开"},{"emoji":"👥","example":"有些人在看书。","examplePinyin":"Yǒuxiē rén zài kàn shū.","exampleVi":"Có người đang đọc sách.","meaning":"một số, có một số","pinyin":"yǒuxiē","pos":"Đại từ","word":"有些"},{"emoji":"👥","example":"有的人在看书。","examplePinyin":"Yǒude rén zài kàn shū.","exampleVi":"Có người đang đọc sách.","meaning":"một số","pinyin":"yǒude","pos":"Đại từ","word":"有的"},{"emoji":"✨","example":"我看了一个电影。","examplePinyin":"Wǒ kànle yí ge diànyǐng.","exampleVi":"Tôi đã xem một bộ phim.","meaning":"(sau động từ) chỉ hành động đã hoàn thành","pinyin":"le","pos":"Trợ từ","word":"了"},{"emoji":"✍️","example":"我们都会写了。","examplePinyin":"Wǒmen dōu huì xiě le.","exampleVi":"Chúng em đều biết viết rồi ạ.","meaning":"viết","pinyin":"xiě","pos":"Động từ","word":"写"},{"emoji":"🔢","example":"我们都会写了。","examplePinyin":"Wǒmen dōu huì xiě le.","exampleVi":"Chúng em đều biết viết rồi ạ.","meaning":"đều, tất cả","pinyin":"dōu","pos":"Phó từ","word":"都"},{"emoji":"👂","example":"老师，我听不见。","examplePinyin":"Lǎoshī, wǒ tīng bú jiàn.","exampleVi":"Cô ơi, em không nghe thấy.","meaning":"nghe thấy","pinyin":"tīngjiàn","pos":"Động từ","word":"听见"},{"emoji":"🚫","example":"请大家不要说话！","examplePinyin":"Qǐng dàjiā búyào shuōhuà!","exampleVi":"Mọi người đừng nói chuyện nữa!","meaning":"đừng","pinyin":"búyào","pos":"Phó từ","word":"不要"},{"emoji":"💬","example":"请大家不要说话！","examplePinyin":"Qǐng dàjiā búyào shuōhuà!","exampleVi":"Mọi người đừng nói chuyện nữa!","meaning":"nói chuyện","pinyin":"shuōhuà","pos":"Động từ","word":"说话"},{"emoji":"👂","example":"请听老师的问题。","examplePinyin":"Qǐng tīng lǎoshī de wèntí.","exampleVi":"Hãy nghe câu hỏi của cô.","meaning":"nghe","pinyin":"tīng","pos":"Động từ","word":"听"},{"emoji":"❓","example":"你们都会写哪些汉字了？","examplePinyin":"Nǐmen dōu huì xiě nǎxiē Hànzì le?","exampleVi":"Các em đều biết viết những chữ Hán nào rồi?","meaning":"những... nào","pinyin":"nǎxiē","pos":"Đại từ","word":"哪些"},{"emoji":"🔤","example":"我会写这些字了，您看！","examplePinyin":"Wǒ huì xiě zhèxiē zì le, nín kàn!","exampleVi":"Em biết viết những chữ này rồi, cô xem này!","meaning":"chữ, từ","pinyin":"zì","pos":"Danh từ","word":"字"},{"emoji":"🇨🇳","example":"你们会说汉语了。","examplePinyin":"Nǐmen huì shuō Hànyǔ le.","exampleVi":"Các em đã biết nói tiếng Hán rồi.","meaning":"tiếng Hán","pinyin":"Hànyǔ","pos":"Danh từ","word":"汉语"},{"emoji":"🀄","example":"也会写汉字了吗？","examplePinyin":"Yě huì xiě Hànzì le ma?","exampleVi":"Cũng biết viết chữ Hán chưa?","meaning":"chữ Hán","pinyin":"Hànzì","pos":"Danh từ","word":"汉字"},{"emoji":"📅","example":"明年女儿上中学。","examplePinyin":"Míngnián nǚ'ér shàng zhōngxué.","exampleVi":"Sang năm con gái sẽ lên trung học.","meaning":"năm sau","pinyin":"míngnián","pos":"Danh từ","word":"明年"},{"emoji":"🏫","example":"明年女儿上中学。","examplePinyin":"Míngnián nǚ'ér shàng zhōngxué.","exampleVi":"Sang năm con gái sẽ lên trung học.","meaning":"trường trung học","pinyin":"zhōngxué","pos":"Danh từ","word":"中学"},{"emoji":"🏫","example":"儿子也上小学了。","examplePinyin":"Érzi yě shàng xiǎoxué le.","exampleVi":"Con trai cũng sẽ vào tiểu học.","meaning":"trường tiểu học","pinyin":"xiǎoxué","pos":"Danh từ","word":"小学"},{"emoji":"🧑‍🎓","example":"我们家有了一个中学生。","examplePinyin":"Wǒmen jiā yǒule yí ge zhōngxuéshēng.","exampleVi":"Nhà mình sẽ có một học sinh trung học.","meaning":"học sinh trung học","pinyin":"zhōngxuéshēng","pos":"Danh từ","word":"中学生"},{"emoji":"🧒","example":"还有了一个小学生。","examplePinyin":"Hái yǒule yí ge xiǎoxuéshēng.","exampleVi":"Còn có thêm một học sinh tiểu học nữa.","meaning":"học sinh tiểu học","pinyin":"xiǎoxuéshēng","pos":"Danh từ","word":"小学生"},{"emoji":"🎒","example":"上学后，他们都忙了。","examplePinyin":"Shàngxué hòu, tāmen dōu máng le.","exampleVi":"Sau khi đi học, chúng nó đều sẽ bận.","meaning":"đi học, nhập học","pinyin":"shàngxué","pos":"Động từ","word":"上学"},{"emoji":"👨‍👩‍👧‍👦","example":"上学后，他们都忙了。","examplePinyin":"Shàngxué hòu, tāmen dōu máng le.","exampleVi":"Sau khi đi học, chúng nó đều sẽ bận.","meaning":"họ (nam hoặc chung)","pinyin":"tāmen","pos":"Đại từ","word":"他们"},{"emoji":"👩‍👩‍👧","example":"她们都是我的同学。","examplePinyin":"Tāmen dōu shì wǒ de tóngxué.","exampleVi":"Họ đều là bạn học của tôi.","meaning":"họ (nữ)","pinyin":"tāmen","pos":"Đại từ","word":"她们"},{"emoji":"📚","example":"这些书都是新的，它们很好看。","examplePinyin":"Zhèxiē shū dōu shì xīn de, tāmen hěn hǎokàn.","exampleVi":"Những cuốn sách này đều mới, chúng rất đẹp.","meaning":"chúng (vật)","pinyin":"tāmen","pos":"Đại từ","word":"它们"},{"emoji":"🌙","example":"太晚了，睡觉吧。","examplePinyin":"Tài wǎn le, shuìjiào ba.","exampleVi":"Muộn quá rồi, đi ngủ thôi.","meaning":"muộn","pinyin":"wǎn","pos":"Tính từ","word":"晚"}],"phonetics":{"audio":"h1-phon-14.mp3","sections":[{"exercise":{"instruction":"听录音，根据听到的音节选择对应的词语，并大声朗读。","instructionVi":"Nghe ghi âm, chọn từ tương ứng với âm tiết nghe được, sau đó đọc to.","items":["nǐ hǎo","méi guānxi","nánpéngyou","bú kèqi","nǚ'ér","hǎowánr"]},"title":"听音节，匹配词语。","titleVi":"Nghe âm tiết và nối với từ ngữ phù hợp.","track":"14-1","words":[{"han":"你好","py":"","vi":"xin chào"},{"han":"女儿","py":"","vi":"con gái"},{"han":"好玩儿","py":"","vi":"vui, thú vị"},{"han":"没关系","py":"","vi":"không sao đâu, không có gì đâu"},{"han":"男朋友","py":"","vi":"bạn trai"},{"han":"不客气","py":"","vi":"không có gì, đừng khách sáo"}]},{"exercise":{"instruction":"听录音，辨别听到的是陈述句还是疑问句。陈述句用A标出，疑问句用B标出，并大声朗读。","instructionVi":"Nghe ghi âm, phân biệt câu nghe được là câu trần thuật hay câu nghi vấn. Đánh dấu A cho câu trần thuật, B cho câu nghi vấn và đọc to.","items":["Nǐ shì xuéshēng ma","Nǐ shì nǎ guó rén","Wǒ jiào Lǐ Wén","Jīntiān wǒ xiūxi","Shéi shì lǎoshī","Wǒ xiǎng qù chāoshì mǎi dōngxi"]},"text":"按照不同表述功能和语气划分，汉语句子一般分为陈述句、疑问句、感叹句和祈使句四类。陈述句叙述事实，句尾音调平或略下降；疑问句提出问题，除了特指问句，句尾音调多上扬；感叹句表达强烈的情感，句尾音调拉长或加重；祈使句发出请求或命令，句尾音调下降。","textVi":"Căn cứ vào chức năng biểu đạt và ngữ khí khác nhau, câu trong tiếng Trung Quốc thường được chia thành bốn loại: câu trần thuật, câu nghi vấn, câu cảm thán và câu cầu khiến. Câu trần thuật dùng để trình bày hoặc miêu tả sự việc, khi kết thúc câu ngữ điệu ổn định hoặc hơi hạ xuống. Câu nghi vấn dùng để nêu câu hỏi; ngoại trừ câu hỏi đặc chỉ, ngữ điệu khi kết thúc câu thường được nâng cao lên. Câu cảm thán dùng để biểu đạt tình cảm, ngữ điệu thường được kéo dài hoặc nhấn mạnh. Câu cầu khiến dùng để đưa ra yêu cầu, đề nghị hoặc mệnh lệnh, ngữ điệu thường đi xuống khi kết thúc câu.","title":"听辨句调","titleVi":"Nghe và phân biệt ngữ điệu của câu","track":"14-1"}]}},{"emoji":"✈️","grammar":[{"error":"Đừng quên 还 hoặc 也 ở vế sau, thiếu hai từ này thì câu chỉ còn hai vế rời nhau, không thành câu phức song song theo mẫu của bài.","examples":"我喜欢这个，也喜欢那个。 (Wǒ xǐhuan zhège, yě xǐhuan nàge.) — Tôi thích cái này, cũng thích cái kia. 王老师是北京人，李文也是北京人。 (Wáng lǎoshī shì Běijīng rén, Lǐ Wén yě shì Běijīng rén.) — Cô Vương là người Bắc Kinh, Lý Văn cũng là người Bắc Kinh. 我喜欢喝中国茶，还喜欢吃中国菜。 (Wǒ xǐhuan hē Zhōngguó chá, hái xǐhuan chī Zhōngguó cài.) — Tôi thích uống trà Trung Quốc, còn thích ăn món Trung Quốc.","explain":"Câu phức song song gồm hai hoặc nhiều vế nhỏ có liên hệ logic với nhau và cấu trúc đối xứng nhau. Trong quyển này chỉ học dạng vế sau dùng 还 hoặc 也.","formula":"Vế 1, 还/也 + Vế 2","tip":"还 và 也 đều diễn tả thêm một ý tương tự, 还 nhấn mạnh thêm nữa, 也 nhấn mạnh cũng vậy, hai vế phải có cấu trúc tương xứng.","title":"Câu phức song song ……，还/也……"}],"han":"大兴机场见！","natural":["Mạch ý: mời bạn ăn cơm Tàu, bàn kế hoạch nghỉ lễ, hẹn gặp ở sân bay Đại Hưng.","并列复句 “……，还/也……” gồm hai vế song song, vế sau dùng 还 hoặc 也 diễn tả thêm một ý nữa.","Chú ý cách nói mời khách ăn nhiều (多吃点儿) và văn hóa hiếu khách trên bàn ăn Trung Quốc."],"num":15,"photoPrefix":"h1-15","pinyin":"Dàxīng Jīchǎng jiàn!","structures":[{"han":"我喜欢这个，也喜欢那个。","pinyin":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","meaning":"Tôi thích món này, cũng thích món kia.","note":"并列复句 với 也: hai vế song song, vế sau dùng 也 diễn tả thêm một sở thích nữa."},{"han":"这些菜都好吃，还很好看。","pinyin":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","meaning":"Những món này đều ngon, lại còn rất đẹp mắt.","note":"还 trong 并列复句 diễn tả thêm một đặc điểm nữa của các món ăn: vừa ngon, lại còn đẹp mắt."},{"han":"今年我也想去北京。","pinyin":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","meaning":"Năm nay tôi cũng muốn đi Bắc Kinh.","note":"都 diễn tả cả hai người đều là người Bắc Kinh; 并列复句 với 也 ở vế sau nhấn mạnh cả hai cùng muốn đi Bắc Kinh."},{"han":"那我们和您姐姐在大兴机场见！","pinyin":"Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","meaning":"Vậy chúng em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!","note":"那 mở đầu câu kết luận, diễn tả quyết định sau khi bàn bạc: hẹn gặp chị gái cô Vương ở sân bay Đại Hưng."},{"han":"今年我想去北京。","pinyin":"Jīnnián wǒ xiǎng qù Běijīng.","meaning":"Năm nay tôi muốn đi Bắc Kinh.","note":""}],"theme":"Du lịch Bắc Kinh, hẹn gặp","translation":"Hẹn gặp ở sân bay Đại Hưng!","vocab":[{"emoji":"❤️","example":"你们爱吃哪个菜？","examplePinyin":"Nǐmen ài chī nǎge cài?","exampleVi":"Các bạn thích ăn món nào?","meaning":"yêu, thích","pinyin":"ài","pos":"Động từ","word":"爱"},{"emoji":"❓","example":"你们爱吃哪个菜？","examplePinyin":"Nǐmen ài chī nǎge cài?","exampleVi":"Các bạn thích ăn món nào?","meaning":"cái nào","pinyin":"nǎge","pos":"Đại từ","word":"哪个"},{"emoji":"📅","example":"去年我和男朋友去了西安。","examplePinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān.","exampleVi":"Năm ngoái tôi và bạn trai đã đi Tây An.","meaning":"năm ngoái","pinyin":"qùnián","pos":"Danh từ","word":"去年"},{"emoji":"👦","example":"去年我和男朋友去了西安。","examplePinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān.","exampleVi":"Năm ngoái tôi và bạn trai đã đi Tây An.","meaning":"bạn trai","pinyin":"nánpéngyou","pos":"Danh từ","word":"男朋友"},{"emoji":"🔢","example":"前几年我去了西安。","examplePinyin":"Qián jǐ nián wǒ qùle Xī'ān.","exampleVi":"Mấy năm trước tôi đã đi Tây An.","meaning":"mấy, vài","pinyin":"jǐ","pos":"Số từ","word":"几"},{"emoji":"📆","example":"今年我想去北京。","examplePinyin":"Jīnnián wǒ xiǎng qù Běijīng.","exampleVi":"Năm nay tôi muốn đi Bắc Kinh.","meaning":"năm","pinyin":"nián","pos":"Danh từ","word":"年"},{"emoji":"🎉","example":"前几年我去了西安，非常好玩儿。","examplePinyin":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr.","exampleVi":"Mấy năm trước tôi đã đi Tây An, rất vui.","meaning":"vui, thú vị","pinyin":"hǎowánr","pos":"Tính từ","word":"好玩儿"},{"emoji":"✈️","example":"你们的飞机到北京要几个小时？","examplePinyin":"Nǐmen de fēijī dào Běijīng yào jǐ ge xiǎoshí?","exampleVi":"Máy bay của các em đến Bắc Kinh mất mấy tiếng?","meaning":"máy bay","pinyin":"fēijī","pos":"Danh từ","word":"飞机"},{"emoji":"⏱️","example":"你们的飞机到北京要几个小时？","examplePinyin":"Nǐmen de fēijī dào Běijīng yào jǐ ge xiǎoshí?","exampleVi":"Máy bay của các em đến Bắc Kinh mất mấy tiếng?","meaning":"cần (thời gian), mất","pinyin":"yào","pos":"Động từ","word":"要"},{"emoji":"🕐","example":"九个小时。","examplePinyin":"Jiǔ ge xiǎoshí.","exampleVi":"Chín tiếng.","meaning":"giờ, tiếng đồng hồ","pinyin":"xiǎoshí","pos":"Danh từ","word":"小时"},{"emoji":"👨‍👩‍👧‍👦","example":"我家人都在北京。","examplePinyin":"Wǒ jiārén dōu zài Běijīng.","exampleVi":"Gia đình tôi đều ở Bắc Kinh.","meaning":"người nhà, gia đình","pinyin":"jiārén","pos":"Danh từ","word":"家人"},{"emoji":"⏳","example":"星期天我姐姐也有时间。","examplePinyin":"Xīngqītiān wǒ jiějie yě yǒu shíjiān.","exampleVi":"Chủ nhật chị gái tôi cũng rảnh.","meaning":"thời gian","pinyin":"shíjiān","pos":"Danh từ","word":"时间"},{"emoji":"🛫","example":"她可以去机场接你们。","examplePinyin":"Tā kěyǐ qù jīchǎng jiē nǐmen.","exampleVi":"Chị ấy có thể ra sân bay đón các em.","meaning":"sân bay","pinyin":"jīchǎng","pos":"Danh từ","word":"机场"},{"emoji":"🤝","example":"她可以去机场接你们。","examplePinyin":"Tā kěyǐ qù jīchǎng jiē nǐmen.","exampleVi":"Chị ấy có thể ra sân bay đón các em.","meaning":"đón","pinyin":"jiē","pos":"Động từ","word":"接"},{"emoji":"🏠","example":"你们也可以住我家。","examplePinyin":"Nǐmen yě kěyǐ zhù wǒ jiā.","exampleVi":"Các em cũng có thể ở nhà tôi.","meaning":"ở, sống","pinyin":"zhù","pos":"Động từ","word":"住"},{"emoji":"🌅","example":"我们星期日早上八点到大兴机场，早不早？","examplePinyin":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","exampleVi":"Chúng em sáng chủ nhật 8 giờ đến sân bay Đại Hưng, có sớm quá không?","meaning":"sớm","pinyin":"zǎo","pos":"Tính từ","word":"早"},{"emoji":"👉","example":"那我们和您姐姐在大兴机场见！","examplePinyin":"Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","exampleVi":"Vậy chúng em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!","meaning":"vậy thì, thế thì","pinyin":"nà","pos":"Liên từ","word":"那"},{"emoji":"🏯","example":"去年我和男朋友去了西安。","examplePinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān.","exampleVi":"Năm ngoái tôi và bạn trai đã đi Tây An.","meaning":"Tây An (thành phố)","pinyin":"Xī'ān","pos":"Danh từ","word":"西安"},{"emoji":"🏙️","example":"今年我想去北京。","examplePinyin":"Jīnnián wǒ xiǎng qù Běijīng.","exampleVi":"Năm nay tôi muốn đi Bắc Kinh.","meaning":"Bắc Kinh","pinyin":"Běijīng","pos":"Danh từ","word":"北京"},{"emoji":"🛫","example":"我们星期日早上八点到大兴机场。","examplePinyin":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng.","exampleVi":"Chúng em sáng chủ nhật 8 giờ đến sân bay Đại Hưng.","meaning":"sân bay Đại Hưng","pinyin":"Dàxīng Jīchǎng","pos":"Danh từ","word":"大兴机场"}],"phonetics":{"audio":"h1-phon-15.mp3","sections":[{"exercise":{"instruction":"听录音，根据听到的音节选择对应的词语，并大声朗读。","instructionVi":"Nghe ghi âm, chọn từ tương ứng với âm tiết nghe được, sau đó đọc to.","items":["nǐ hǎo","méi kànjiàn","nǎxiē rén","shuōhuà","shénme shíhou","zuò fēijī"]},"title":"听音节，匹配词语。","titleVi":"Nghe âm tiết và nối với từ ngữ phù hợp.","track":"15-1","words":[{"han":"你好","py":"","vi":"xin chào"},{"han":"说话","py":"","vi":"nói chuyện"},{"han":"坐飞机","py":"","vi":"đi máy bay"},{"han":"没看见","py":"","vi":"không nhìn thấy"},{"han":"哪些人","py":"","vi":"những người nào"},{"han":"什么时候","py":"","vi":"khi nào, lúc nào"}]},{"exercise":{"instruction":"听录音，辨别听到的句子类型。陈述句用A标出，疑问句用B标出，感叹句用C标出，祈使句用D标出，并大声朗读。","instructionVi":"Nghe ghi âm, phân biệt loại câu nghe được. Đánh dấu A cho câu trần thuật, B cho câu nghi vấn, C cho câu cảm thán, D cho câu cầu khiến và đọc to.","items":["Nǐ shì xuéshēng ma","Wǒ ài chī shuǐguǒ","Zhè jiàn yīfu zhēn piàoliang","Nǐmen qù nǎlǐ","Qǐng zuò","Yǔ dà ma"]},"title":"听辨句调","titleVi":"Nghe và phân biệt ngữ điệu của câu","track":"15-1"}]}}];
window.sceneData = window.sceneData1 = {"1":[{"context":"Ngày đầu tiên của năm học, ở văn phòng, Vương Nhất Phi chào hỏi trợ giảng AI Tiểu Ngữ.","contextZh":"开学第一天，在办公室里，王一飞和AI助教小语打招呼。","label":"1-1 · Chào hỏi ở văn phòng","lines":[["王一飞","AI小语，你好！","AI Xiǎoyǔ, nǐ hǎo!","Chào AI Tiểu Ngữ!"],["小语","王老师，你好！","Wáng lǎoshī, nǐ hǎo!","Chào cô Vương!"]],"sides":{"小语":"R","王一飞":"L"}},{"context":"Ngày đầu tiên của năm học, trên lớp, các học sinh học cách chào hỏi.","contextZh":"开学第一天，课堂上，学生们学习打招呼用语。","label":"1-2 · Chào hỏi trên lớp","lines":[["王一飞","大家好！","Dàjiā hǎo!","Chào mọi người!"],["学生们","老师，您好！","Lǎoshī, nín hǎo!","Chào cô ạ!"],["小语","你们好！","Nǐmen hǎo!","Chào các bạn!"],["学生们","你好，小语！","Nǐ hǎo, Xiǎoyǔ!","Chào Tiểu Ngữ!"]],"sides":{"学生们":"R","小语":"C","王一飞":"L"}},{"context":"Ngày đầu tiên của năm học, trên lớp, các học sinh học lời cảm ơn và lời tạm biệt.","contextZh":"开学第一天，课堂上，学生们学习致谢语、告别语。","label":"1-3 · Cảm ơn và tạm biệt","lines":[["学生们","谢谢！","Xièxie!","Cảm ơn!"],["小语","不客气！","Bú kèqi!","Không có gì!"],["王一飞","同学们，再见！","Tóngxuémen, zàijiàn!","Tạm biệt các bạn học!"],["学生们","老师，再见！","Lǎoshī, zàijiàn!","Tạm biệt cô ạ!"]],"sides":{"学生们":"L","小语":"R","王一飞":"C"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"1-4 · Bài vè (绕口令)","lines":[["小语","妈种麻，我放马。","Mā zhòng má, wǒ fàng mǎ.","Mẹ trồng gai dầu, tôi thả ngựa."],["小语","马吃麻，妈骂马。","Mǎ chī má, mā mà mǎ.","Ngựa ăn gai dầu, mẹ mắng ngựa."]],"sides":{"小语":"C"}}],"2":[{"context":"Trong lớp học, Vương Nhất Phi đang làm quen với các học sinh.","contextZh":"在教室里，王一飞在认识学生。","label":"2-1 · Hỏi tên trong lớp","lines":[["王一飞","请问，你叫什么名字？","Qǐngwèn, nǐ jiào shénme míngzi?","Xin hỏi, bạn tên là gì?"],["陈天中","我叫陈天中。","Wǒ jiào Chén Tiānzhōng.","Tôi tên là Trần Thiên Trung."]],"sides":{"王一飞":"L","陈天中":"R"}},{"context":"Trong khuôn viên trường, Trần Thiên Trung chào Bạch Gia Nguyệt nhưng nhận nhầm người.","contextZh":"在校园里，陈天中和白家月打招呼时认错了人。","label":"2-2 · Nhận nhầm người","lines":[["陈天中","你好，安妮！","Nǐ hǎo, Ānnī!","Chào An Ni!"],["白家月","你好，陈天中！我不是安妮，我是白家月。","Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","Chào Trần Thiên Trung! Tôi không phải An Ni, tôi là Bạch Gia Nguyệt."],["陈天中","对不起！","Duìbuqǐ!","Xin lỗi!"],["白家月","没关系！","Méi guānxi!","Không sao đâu!"]],"sides":{"白家月":"R","陈天中":"L"}},{"context":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu.","contextZh":"在校园里，李文和白家月第一次相遇。","label":"2-3 · Gặp nhau lần đầu","lines":[["李文","你好！我叫李文。","Nǐ hǎo! Wǒ jiào Lǐ Wén.","Chào bạn! Tôi tên là Lý Văn."],["白家月","你好！我叫白家月。","Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","Chào bạn! Tôi tên là Bạch Gia Nguyệt."],["李文","很高兴认识你。","Hěn gāoxìng rènshi nǐ.","Rất vui được gặp bạn."],["白家月","认识你我也很高兴。","Rènshi nǐ wǒ yě hěn gāoxìng.","Được gặp bạn tôi cũng rất vui."]],"sides":{"李文":"L","白家月":"R"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"2-4 · Bài vè (绕口令)","lines":[["小语","七加一，再减一，加完减完等于几？","Qī jiā yī, zài jiǎn yī, jiāwán jiǎnwán děngyú jǐ?","Bảy cộng một, rồi trừ một, cộng xong trừ xong bằng mấy?"],["小语","加完减完还是七。","Jiāwán jiǎnwán hái shì qī.","Cộng xong trừ xong vẫn là bảy."]],"sides":{"小语":"C"}}],"3":[{"context":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu và tiếp tục trò chuyện.","contextZh":"在校园里，李文和白家月第一次相遇，两人继续聊天儿。","label":"3-1 · Tôi là người Trung Quốc","lines":[["李文","我是中国人。","Wǒ shì Zhōngguó rén.","Tôi là người Trung Quốc."],["白家月","我是法国人。我的中文老师也是中国人。","Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc."]],"sides":{"李文":"L","白家月":"R"}},{"context":"Trong lớp học, sau giờ học, An Ni đang xem ảnh trong điện thoại của Trần Thiên Trung.","contextZh":"在教室里，下课后，安妮在看陈天中手机里的照片。","label":"3-2 · Đây là ai?","lines":[["安妮","这是谁？","Zhè shì shéi?","Đây là ai?"],["陈天中","这是我女朋友。","Zhè shì wǒ nǚpéngyou.","Đây là bạn gái của tôi."],["安妮","你女朋友是哪国人？","Nǐ nǚpéngyou shì nǎ guó rén?","Bạn gái của bạn là người nước nào?"],["陈天中","她也是泰国人。","Tā yě shì Tàiguó rén.","Cô ấy cũng là người Thái Lan."]],"sides":{"安妮":"L","陈天中":"R"}},{"context":"Ở nhà, Vương Nhất Tuyết gọi video cho Vương Nhất Phi.","contextZh":"在家里，王一雪给王一飞打视频电话。","label":"3-3 · Gọi video cho chị","lines":[["王一雪","喂，一飞！","Wéi, Yīfēi!","A lô, Nhất Phi!"],["王一飞","姐姐！","Jiějie!","Chị ơi!"],["王一雪","你工作还忙吗？","Nǐ gōngzuò hái máng ma?","Công việc của bạn còn bận không?"],["王一飞","对，还很忙。你也很忙吗？","Duì, hái hěn máng. Nǐ yě hěn máng ma?","Đúng, còn rất bận. Bạn cũng rất bận à?"],["王一雪","我不太忙。我们很想你。","Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","Tôi không bận lắm. Chúng tôi rất nhớ bạn."],["王一飞","我也想你们。","Wǒ yě xiǎng nǐmen.","Tôi cũng nhớ các bạn."]],"sides":{"王一雪":"L","王一飞":"R"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"3-4 · Bài vè (绕口令)","lines":[["小语","四是四，十是十。","Sì shì sì, shí shì shí.","Bốn là bốn, mười là mười."],["小语","十四是十四，四十是四十。","Shísì shì shísì, sìshí shì sìshí.","Mười bốn là mười bốn, bốn mươi là bốn mươi."]],"sides":{"小语":"C"}}],"4":[{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在家里，刘明和王一雪在聊天儿。","label":"4-1 · Cô ấy có bao nhiêu học sinh?","lines":[["刘明","一飞忙吗？","Yīfēi máng ma?","Nhất Phi có bận không?"],["王一雪","她很忙。","Tā hěn máng.","Cô ấy rất bận."],["刘明","她有多少个学生？","Tā yǒu duōshao gè xuéshēng?","Cô ấy có bao nhiêu học sinh?"],["王一雪","她有二十个学生。","Tā yǒu èrshí gè xuéshēng.","Cô ấy có hai mươi học sinh."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc nghỉ giải lao.","contextZh":"在公司里，王一雪和杨同乐休息时聊天儿。","label":"4-2 · Nhà bạn có mấy người?","lines":[["王一雪","我有两个哥哥，你呢？","Wǒ yǒu liǎng gè gēge, nǐ ne?","Tôi có hai anh trai, còn bạn?"],["杨同乐","我没有哥哥。","Wǒ méiyǒu gēge.","Tôi không có anh trai."],["王一雪","你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","Nhà bạn có mấy người?"],["杨同乐","我家有四口人，爸爸、妈妈、妹妹和我。","Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","Nhà tôi có bốn người: bố, mẹ, em gái và tôi."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Trên phố, Vương Nhất Tuyết dẫn con trai đi chơi thì tình cờ gặp Dương Đồng Lạc.","contextZh":"在街上，王一雪带着儿子偶遇杨同乐。","label":"4-3 · Tôi có hai con","lines":[["杨同乐","这是您儿子吗？","Zhè shì nín érzi ma?","Đây là con trai của cô phải không?"],["王一雪","是的。我有两个孩子，一个儿子，一个女儿。","Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","Vâng. Tôi có hai con, một con trai, một con gái."],["杨同乐","您儿子几岁？","Nín érzi jǐ suì?","Con trai của cô mấy tuổi?"],["王一雪","他今年五岁。","Tā jīnnián wǔ suì.","Cháu năm nay năm tuổi."],["杨同乐","您女儿多大？","Nín nǚ'ér duō dà?","Con gái của cô bao nhiêu tuổi?"],["王一雪","她今年十二。","Tā jīnnián shí'èr.","Cháu năm nay mười hai tuổi."]],"sides":{"杨同乐":"L","王一雪":"R"}}],"5":[{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在家里，刘明和王一雪在聊天儿。","label":"5-1 · Hôm nay là ngày mấy?","lines":[["王一雪","今天几号？","Jīntiān jǐ hào?","Hôm nay là ngày mấy?"],["刘明","今天9月8号。","Jīntiān jiǔ yuè bā hào.","Hôm nay là ngày 8 tháng 9."],["王一雪","星期几？","Xīngqī jǐ?","Hôm nay là thứ mấy?"],["刘明","星期日。今天我休息。","Xīngqīrì. Jīntiān wǒ xiūxi.","Chủ nhật. Hôm nay tôi nghỉ."]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc nghỉ giải lao.","contextZh":"在公司里，王一雪和杨同乐休息时聊天儿。","label":"5-2 · Bạn có biết nấu cơm không?","lines":[["王一雪","你会做饭吗？","Nǐ huì zuò fàn ma?","Bạn có biết nấu cơm không?"],["杨同乐","我会做。","Wǒ huì zuò.","Tôi biết làm."],["王一雪","你会做什么？","Nǐ huì zuò shénme?","Bạn biết làm món gì?"],["杨同乐","我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","Tôi biết làm mì, sủi cảo, cũng biết làm một số món. Chủ nhật tôi cũng nấu cơm."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc tan làm.","contextZh":"在公司里，王一雪和杨同乐下班时聊天儿。","label":"5-3 · Máy tính mới đẹp thật!","lines":[["王一雪","同乐，下班吗？","Tónglè, xiàbān ma?","Đồng Lạc, tan làm chưa?"],["杨同乐","下班。","Xiàbān.","Tan làm rồi."],["王一雪","这是你的新电脑吗？","Zhè shì nǐ de xīn diànnǎo ma?","Đây là máy tính mới của bạn phải không?"],["杨同乐","是的，是我的新电脑。","Shì de, shì wǒ de xīn diànnǎo.","Vâng, là máy tính mới của tôi."],["王一雪","真好看！","Zhēn hǎokàn!","Đẹp thật đấy!"],["杨同乐","我也很喜欢它。","Wǒ yě hěn xǐhuan tā.","Tôi cũng rất thích nó."]],"sides":{"杨同乐":"R","王一雪":"L"}}],"6":[{"label":"6-1 · Hỏi số điện thoại","context":"Ở trường, Lý Văn hỏi Bạch Gia Nguyệt số điện thoại di động.","contextZh":"在校园里，李文向白家月要手机号。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","家月，你的手机号是多少？","Jiāyuè, nǐ de shǒujīhào shì duōshao?","Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?"],["白家月","我的手机号是+33 601493190。","Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","Số điện thoại di động của tôi là +33 601493190."],["李文","我的手机号是+86 13552721160。","Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","Số điện thoại di động của tôi là +86 13552721160."],["白家月","好的。","Hǎo de.","Được rồi."]]},{"label":"6-2 · Đi siêu thị mua đồ","context":"Sau giờ học, ở lớp học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室里，下课后，白家月和陈天中在聊天儿。","sides":{"陈天中":"L","白家月":"R"},"lines":[["陈天中","家月，明天你去哪儿？","Jiāyuè, míngtiān nǐ qù nǎr?","Gia Nguyệt, ngày mai bạn đi đâu?"],["白家月","我想去超市买东西。","Wǒ xiǎng qù chāoshì mǎi dōngxi.","Tôi muốn đi siêu thị mua đồ."],["陈天中","你去超市买什么？","Nǐ qù chāoshì mǎi shénme?","Bạn đi siêu thị mua gì?"],["白家月","我想买些牛奶。","Wǒ xiǎng mǎi xiē niúnǎi.","Tôi muốn mua một ít sữa bò."]]},{"label":"6-3 · Ăn tối ở nhà hàng Tây An","context":"Ở nhà, cả nhà Vương Nhất Tuyết đang bàn kế hoạch ăn tối cuối tuần.","contextZh":"在家里，王一雪全家在讨论周末晚餐安排。","sides":{"王一雪":"L","刘明":"R","刘小雪":"L","刘小明":"R"},"lines":[["王一雪","星期天我们去哪儿吃晚饭？","Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","Chủ nhật chúng ta đi đâu ăn tối?"],["刘明","我还想去西安饭店。","Wǒ hái xiǎng qù Xī'ān Fàndiàn.","Tôi vẫn muốn đến nhà hàng Tây An."],["刘小雪","那边的包子非常好吃，我想吃包子。","Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","Bánh bao bên đó rất ngon, con muốn ăn bánh bao."],["刘小明","妈妈，我想吃米饭，不想吃包子。","Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."],["王一雪","好的。我们怎么去？","Hǎo de. Wǒmen zěnme qù?","Được rồi. Chúng ta đi bằng cách nào?"],["刘明","坐出租车去。","Zuò chūzūchē qù.","Đi taxi đến đó."]]}],"7":[{"label":"7-1 · Gọi điện hẹn gặp","context":"Bạch Gia Nguyệt và An Ni đang gọi điện cho nhau.","contextZh":"白家月和安妮在打电话。","sides":{"白家月":"L","安妮":"R"},"lines":[["白家月","现在几点？","Xiànzài jǐ diǎn?","Bây giờ là mấy giờ?"],["安妮","早上八点四十。","Zǎoshang bā diǎn sìshí.","Tám giờ bốn mươi buổi sáng."],["白家月","我上午十点十分有课。","Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","Sáng nay mười giờ mười phút tôi có tiết học."],["安妮","好的，我们下午两点见吧。","Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","Được rồi, chiều nay hai giờ chúng ta gặp nhau nhé."]]},{"label":"7-2 · Rủ đi xem phim","context":"Ở trường, Lý Văn gặp Bạch Gia Nguyệt.","contextZh":"在校园里，李文遇到白家月。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","下午我想去电影院看电影，你去吗？","Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","Chiều nay tôi muốn đi rạp chiếu phim xem phim, bạn đi không?"],["白家月","我不想去，下午还有事。","Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","Tôi không muốn đi, chiều nay còn có việc."],["李文","好的。明天呢？","Hǎo de. Míngtiān ne?","Được rồi. Ngày mai thì sao?"],["白家月","我明天下午两点还上课呢，四点半下课。","Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","Chiều mai hai giờ tôi vẫn còn học, bốn giờ rưỡi mới tan học."]]},{"label":"7-3 · Gọi điện cho Lưu Minh","context":"Vương Nhất Tuyết ở văn phòng gọi điện cho Lưu Minh.","contextZh":"王一雪在办公室给刘明打电话。","sides":{"王一雪":"L","刘明":"R"},"lines":[["王一雪","喂，你在哪儿呢？","Wèi, nǐ zài nǎr ne?","Alo, bạn đang ở đâu đấy?"],["刘明","我在家里呢。","Wǒ zài jiā li ne.","Tôi đang ở nhà đây."],["王一雪","我晚上六点半下班。","Wǒ wǎnshang liù diǎn bàn xiàbān.","Tôi tan làm lúc sáu giờ rưỡi tối."],["刘明","我八点去医院上班。","Wǒ bā diǎn qù yīyuàn shàngbān.","Tôi tám giờ đi bệnh viện làm việc."],["王一雪","好的，你去店里买些菜吧。","Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","Được rồi, bạn đi cửa hàng mua ít rau nhé."],["刘明","好，我十分钟后去。","Hǎo, wǒ shí fēnzhōng hòu qù.","Được, mười phút nữa tôi đi."]]}],"8":[{"label":"8-1 · Con mèo nhỏ ngoài phòng","context":"Ở nhà Vương Nhất Phi, Bạch Gia Nguyệt và Trần Thiên Trung đến chơi.","contextZh":"在王一飞家，白家月和陈天中来做客。","sides":{"白家月":"L","陈天中":"R"},"lines":[["白家月","房间外有一只小猫。","Fángjiān wài yǒu yì zhī xiǎo māo.","Ngoài phòng có một con mèo nhỏ."],["陈天中","我没看见，它在哪儿呢？","Wǒ méi kànjiàn, tā zài nǎr ne?","Tôi không nhìn thấy nó, nó ở đâu nhỉ?"],["白家月","它在桌子下呢。","Tā zài zhuōzi xià ne.","Nó đang ở dưới gầm bàn đấy."],["陈天中","这只小猫真漂亮！","Zhè zhī xiǎo māo zhēn piàoliang!","Con mèo nhỏ này xinh thật!"]]},{"label":"8-2 · Hẹn gặp trước hiệu sách","context":"Ở lớp học, sau giờ học, Bạch Gia Nguyệt gọi điện cho Lý Văn.","contextZh":"在教室里，下课后，白家月给李文打电话。","sides":{"白家月":"L","李文":"R"},"lines":[["白家月","我们在哪儿见呢？","Wǒmen zài nǎr jiàn ne?","Chúng ta gặp nhau ở đâu nhỉ?"],["李文","在学校书店前见吧。","Zài xuéxiào shūdiàn qián jiàn ba.","Gặp nhau trước hiệu sách của trường nhé."],["白家月","好的。下午两点你能到吗？","Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","Được rồi. Chiều nay hai giờ bạn đến được không?"],["李文","我能到。我在学校吃午饭。","Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","Tôi đến được. Tôi ăn trưa ở trường."]]},{"label":"8-3 · Chuyện trò ở bệnh viện","context":"Ở bệnh viện, Lưu Minh và đồng nghiệp là bác sĩ Hồ đang trò chuyện.","contextZh":"在医院里，刘明和同事胡医生在聊天儿。","sides":{"刘明":"L","胡医生":"R"},"lines":[["刘明","小胡，还没吃饭呢？","Xiǎo Hú, hái méi chī fàn ne?","Tiểu Hồ, vẫn chưa ăn cơm à?"],["胡医生","没吃呢。","Méi chī ne.","Chưa ăn."],["刘明","大医院病人多，医生非常忙。","Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","Bệnh viện lớn đông bệnh nhân, bác sĩ rất bận."],["胡医生","是的。我爸爸也在医院工作，他也非常忙。","Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận."],["刘明","你家有两个医生？","Nǐ jiā yǒu liǎng ge yīshēng?","Nhà bạn có hai bác sĩ à?"],["胡医生","对。","Duì.","Đúng vậy."]]}],"9":[{"label":"9-1 · Hẹn xem phim tối nay","context":"Ở trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在校园里，李文和白家月在聊天儿。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","学校前边有一家电影院。","Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","Trước trường có một rạp chiếu phim."],["白家月","对。我们晚上去那个电影院看电影吧。","Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","Đúng vậy. Tối nay chúng ta đến rạp chiếu phim đó xem phim nhé."],["李文","好！我们七点在电影院外边见，好吗？","Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","Hay quá! Bảy giờ chúng ta gặp nhau ngoài rạp chiếu phim, được không?"],["白家月","好的，晚上七点见！","Hǎo de, wǎnshang qī diǎn jiàn!","Được rồi, tối nay bảy giờ gặp nhau!"]]},{"label":"9-2 · Quyển sách trên ghế","context":"Ở lớp học, sau giờ học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室里，下课后，白家月和陈天中在对话。","sides":{"白家月":"L","陈天中":"R"},"lines":[["白家月","椅子上有一本中文书，那是谁的书？","Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","Trên ghế có một quyển sách tiếng Trung, đó là sách của ai?"],["陈天中","是我的书，谢谢。这是我的第二本中文书。","Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","Là sách của tôi, cảm ơn. Đây là quyển sách tiếng Trung thứ hai của tôi."],["白家月","不客气。你明天上午在哪儿？","Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","Không có gì. Sáng mai bạn ở đâu?"],["陈天中","我明天上午在学校学习。","Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","Sáng mai tôi học ở trường."]]},{"label":"9-3 · Kế hoạch cuối tuần","context":"Trong giờ nghỉ ở văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc bàn về cuộc sống cuối tuần.","contextZh":"在办公室里，休息时，王一雪和杨同乐谈论周末生活。","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","明天星期六，你做什么？","Míngtiān Xīngqīliù, nǐ zuò shénme?","Ngày mai là thứ bảy, bạn làm gì?"],["杨同乐","我白天在家里读书，晚上和朋友们去外边唱歌。","Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","Ban ngày tôi đọc sách ở nhà, buổi tối cùng các bạn ra ngoài hát."],["王一雪","你唱歌很好听。","Nǐ chàng gē hěn hǎotīng.","Bạn hát rất hay."],["杨同乐","谢谢！您星期六做什么？","Xièxie! Nín Xīngqīliù zuò shénme?","Cảm ơn! Thứ bảy chị làm gì ạ?"],["王一雪","我在家里做饭、看电视，和孩子们、小狗玩。","Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","Tôi nấu cơm, xem ti vi ở nhà, và chơi với các con cùng chú chó nhỏ."],["杨同乐","我也有一只小狗。","Wǒ yě yǒu yì zhī xiǎo gǒu.","Tôi cũng có một chú chó nhỏ."]]}],"10":[{"label":"10-1 · Mua cốc ở cửa hàng nhỏ","context":"Ở một cửa hàng nhỏ, Vương Nhất Tuyết đang mua cốc.","contextZh":"在一家小店，王一雪在买杯子。","sides":{"王一雪":"L","售货员":"R"},"lines":[["王一雪","请问，有杯子吗？","Qǐngwèn, yǒu bēizi ma?","Xin hỏi, có cốc không ạ?"],["售货员","有，杯子在这边。","Yǒu, bēizi zài zhèbiān.","Có, cốc ở bên này."],["王一雪","多少钱一个？","Duōshao qián yí ge?","Một cái bao nhiêu tiền?"],["售货员","这些五块钱一个，那些十块钱一个。","Zhèxiē wǔ kuài qián yí ge, nàxiē shí kuài qián yí ge.","Những cái này năm đồng một cái, những cái kia mười đồng một cái."],["王一雪","我买这个吧。","Wǒ mǎi zhège ba.","Tôi mua cái này nhé."]]},{"label":"10-2 · Mua táo ở chợ","context":"Ở chợ, Vương Nhất Tuyết đang mua hoa quả.","contextZh":"在菜市场，王一雪在买水果。","sides":{"王一雪":"L","售货员":"R"},"lines":[["王一雪","这儿的水果真不少！","Zhèr de shuǐguǒ zhēn bù shǎo!","Hoa quả ở đây nhiều thật!"],["售货员","您想买什么？","Nín xiǎng mǎi shénme?","Ngài muốn mua gì ạ?"],["王一雪","我想买两斤苹果。","Wǒ xiǎng mǎi liǎng jīn píngguǒ.","Tôi muốn mua hai cân táo."],["售货员","苹果三块五一斤。这些七块二，七块钱吧。","Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","Táo ba đồng rưỡi một cân. Những thứ này bảy đồng hai, tính bảy đồng nhé."],["王一雪","好的，这儿的苹果真便宜！","Hǎo de, zhèr de píngguǒ zhēn piányi!","Được rồi, táo ở đây rẻ thật!"]]},{"label":"10-3 · Mua quần áo cho con","context":"Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con.","contextZh":"在商场里，刘明和王一雪在给孩子买衣服。","sides":{"王一雪":"L","刘明":"R"},"lines":[["王一雪","这家商店衣服真多！这件一百元，怎么样？","Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","Cửa hàng này nhiều quần áo thật! Cái này một trăm đồng, thế nào?"],["刘明","好看，也不贵。","Hǎokàn, yě bù guì.","Đẹp, cũng không đắt."],["王一雪","小雪能穿，买一件吧。","Xiǎoxuě néng chuān, mǎi yí jiàn ba.","Tiểu Tuyết mặc được, mua một cái nhé."],["刘明","好的。小明能穿吗？","Hǎo de. Xiǎomíng néng chuān ma?","Được rồi. Tiểu Minh có mặc được không?"],["王一雪","不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","Không được. Đây là quần áo con gái mặc, quần áo con trai ở đằng kia."],["刘明","好的。","Hǎo de.","Được rồi."]]}],"11":[{"context":"Trên đường, Lý Văn đang tìm nhà hàng thì Vương Nhất Phi gọi điện cho anh.","contextZh":"在路上，李文在找饭店，王一飞给他打电话。","label":"11-1 · Tìm nhà hàng trên đường","lines":[["王一飞","喂，李文，你什么时候能到饭店？","Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","A lô, Lý Văn, bao giờ anh đến được nhà hàng?"],["李文","还不知道，正在找呢。它是不是在超市后边？","Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","Vẫn chưa biết, tôi đang tìm đây. Nó có phải ở phía sau siêu thị không?"],["王一飞","是的。你开车没开车？","Shì de. Nǐ kāichē méi kāichē?","Đúng rồi. Anh có lái xe không?"],["李文","我没开车，坐车呢。","Wǒ méi kāichē, zuò chē ne.","Tôi không lái xe, tôi đang ngồi xe đây."]],"sides":{"李文":"R","王一飞":"L"}},{"context":"Ở nhà hàng, Vương Nhất Phi và Lý Văn gặp nhau rồi trò chuyện.","contextZh":"在饭店里，王一飞和李文见面后聊天儿。","label":"11-2 · Gặp nhau ở nhà hàng","lines":[["王一飞","你还在读大学吗？","Nǐ hái zài dú dàxué ma?","Anh vẫn còn đang học đại học à?"],["李文","对，我读大学呢，还是大学生。","Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","Đúng, tôi đang học đại học đây, vẫn còn là sinh viên."],["王一飞","你们学习忙不忙？","Nǐmen xuéxí máng bu máng?","Các anh học có bận không?"],["李文","非常忙，我学医，我们的课很多。","Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","Rất bận, tôi học y, chúng tôi có rất nhiều tiết học."]],"sides":{"李文":"R","王一飞":"L"}},{"context":"Sáng thứ Bảy, Lưu Minh sắp đi bệnh viện làm thêm, trước khi ra khỏi nhà anh trò chuyện với con gái.","contextZh":"星期六早上，刘明要去医院加班，出门前和女儿对话。","label":"11-3 · Sáng thứ Bảy ở nhà","lines":[["刘明","弟弟起床没起床呢？","Dìdi qǐchuáng méi qǐchuáng ne?","Em trai đã dậy chưa?"],["刘小雪","没起床呢，还在睡觉。","Méi qǐchuáng ne, hái zài shuìjiào.","Chưa dậy đâu, vẫn còn đang ngủ."],["刘明","还睡呢？他今天去不去哪里？","Hái shuì ne? Tā jīntiān qù bu qù nǎlǐ?","Vẫn còn ngủ à? Hôm nay nó có đi đâu không?"],["刘小雪","去哪里？","Qù nǎlǐ?","Đi đâu ạ?"],["刘明","去超市。","Qù chāoshì.","Đi siêu thị."],["刘小雪","我昨天问他，他对我说，他不去，他今天要和小朋友玩。","Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","Hôm qua con hỏi nó, nó nói với con là nó không đi, hôm nay nó muốn chơi với các bạn nhỏ."]],"sides":{"刘小雪":"R","刘明":"L"}}],"12":[{"context":"Vương Nhất Tuyết gọi điện cho Vương Nhất Phi hỏi tình hình bên chỗ chị.","contextZh":"王一雪给王一飞打电话，问问王一飞那边的情况。","label":"12-1 · Gọi điện hỏi thời tiết","lines":[["王一雪","今天天气怎么样？","Jīntiān tiānqì zěnmeyàng?","Hôm nay thời tiết thế nào?"],["王一飞","这里的天不太好，下雨了。","Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","Thời tiết chỗ chị không tốt lắm, trời đang mưa."],["王一雪","雨大吗？","Yǔ dà ma?","Mưa to không?"],["王一飞","有点儿大，我觉得很冷。","Yǒudiǎnr dà, wǒ juéde hěn lěng.","Hơi to, chị thấy rất lạnh."]],"sides":{"王一雪":"L","王一飞":"R"}},{"context":"Trong thang máy công ty, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện.","contextZh":"在公司电梯里，王一雪和杨同乐在聊天儿。","label":"12-2 · Gặp nhau trong thang máy","lines":[["王一雪","昨天下雪了。","Zuótiān xià xuě le.","Hôm qua trời có tuyết rơi."],["杨同乐","是的，太冷了。","Shì de, tài lěng le.","Đúng thế, lạnh quá."],["王一雪","你昨天没来公司，生病了？","Nǐ zuótiān méi lái gōngsī, shēngbìng le?","Hôm qua anh không đến công ty, bị ốm à?"],["杨同乐","对，我昨天去医院看病了。","Duì, wǒ zuótiān qù yīyuàn kànbìng le.","Đúng, hôm qua tôi đi bệnh viện khám bệnh."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Hôm qua ở bệnh viện, bác sĩ khám bệnh cho Dương Đồng Lạc.","contextZh":"昨天在医院，医生给杨同乐看病。","label":"12-3 · Khám bệnh ở bệnh viện","lines":[["杨同乐","医生，我病了。","Yīshēng, wǒ bìng le.","Bác sĩ, tôi bị ốm."],["胡医生","我看看。你觉得怎么样？","Wǒ kànkan. Nǐ juéde zěnmeyàng?","Để tôi xem nào. Anh thấy trong người thế nào?"],["杨同乐","我很冷。","Wǒ hěn lěng.","Tôi thấy rất lạnh."],["胡医生","好的，吃一点儿药，今天休息半天吧。","Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","Được, uống một ít thuốc, hôm nay nghỉ nửa ngày nhé."],["杨同乐","好的。","Hǎo de.","Vâng."],["胡医生","回家后再喝些热水。","Huí jiā hòu zài hē xiē rè shuǐ.","Về nhà rồi uống thêm ít nước nóng nhé."]],"sides":{"杨同乐":"L","胡医生":"R"}}],"13":[{"context":"Trong lớp học, sau giờ học, Bạch Gia Nguyệt hỏi cô Vương một câu hỏi.","contextZh":"在教室里，下课后，白家月问王老师问题。","label":"13-1 · Hỏi thêm cô giáo một câu","lines":[["白家月","王老师，我可以再问您一个问题吗？","Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí ge wèntí ma?","Cô Vương, em có thể hỏi thêm cô một câu nữa không ạ?"],["王一飞","可以。你有什么问题？","Kěyǐ. Nǐ yǒu shénme wèntí?","Được. Em có câu hỏi gì?"],["白家月","那个小店卖不卖手机？","Nàge xiǎo diàn mài bu mài shǒujī?","Cửa hàng nhỏ kia có bán điện thoại không ạ?"],["王一飞","我不知道。你可以打电话问一下。","Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","Cô không biết. Em có thể gọi điện hỏi thử xem."]],"sides":{"王一飞":"R","白家月":"L"}},{"context":"Ở quán cà phê, Vương Nhất Tuyết muốn ăn sáng.","contextZh":"在咖啡馆里，王一雪想吃早餐。","label":"13-2 · Gọi món ở quán cà phê","lines":[["服务员","女士，请坐！您喝什么？","Nǚshì, qǐng zuò! Nín hē shénme?","Thưa cô, mời cô ngồi! Cô uống gì ạ?"],["王一雪","我看一下。请给我一杯牛奶。","Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","Để tôi xem một chút. Cho tôi một ly sữa."],["服务员","好的。您还要什么？","Hǎo de. Nín hái yào shénme?","Vâng. Cô còn muốn gì nữa ạ?"],["王一雪","我还没吃早饭，再要这个面包和鸡蛋吧。","Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","Tôi vẫn chưa ăn sáng, cho thêm bánh mì và trứng này nhé."]],"sides":{"服务员":"L","王一雪":"R"}},{"context":"Ở nhà hàng, Lưu Minh đang gọi món.","contextZh":"在餐馆里，刘明在点餐。","label":"13-3 · Gọi món ở nhà hàng","lines":[["服务员","先生，请坐！您要什么？","Xiānsheng, qǐng zuò! Nín yào shénme?","Thưa ông, mời ông ngồi! Ông muốn gì ạ?"],["刘明","我要一斤饺子。","Wǒ yào yì jīn jiǎozi.","Tôi muốn một cân sủi cảo."],["服务员","好的。一斤饺子40个。","Hǎo de. Yì jīn jiǎozi sìshí gè.","Vâng. Một cân sủi cảo là 40 cái."],["刘明","40个太多了，我要一半吧。","Sìshí gè tài duō le, wǒ yào yíbàn ba.","40 cái nhiều quá, tôi lấy một nửa thôi."],["服务员","半斤20个。您想喝什么？","Bàn jīn èrshí gè. Nín xiǎng hē shénme?","Nửa cân là 20 cái. Ông muốn uống gì ạ?"],["刘明","请给我一杯茶吧。","Qǐng gěi wǒ yì bēi chá ba.","Cho tôi một ly trà nhé."]],"sides":{"刘明":"R","服务员":"L"}}],"14":[{"context":"Trong lớp học, sau giờ học, Bạch Gia Nguyệt và Trần Thiên Trung bàn về chuyến đi ngoại khóa lần trước.","contextZh":"在教室里，下课后，白家月和陈天中在谈论上一次课外旅行。","label":"14-1 · Kể chuyện đi tàu hỏa","lines":[["白家月","你们上火车后看见王老师了吗？","Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","Sau khi lên tàu các cậu có nhìn thấy cô Vương không?"],["陈天中","没看见。中午车开后，有些人在看书，有些人睡觉了。","Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","Không thấy. Sau khi tàu chạy buổi trưa, có người đọc sách, có người đã ngủ."],["白家月","你呢？","Nǐ ne?","Còn cậu thì sao?"],["陈天中","我看了一个电影。","Wǒ kànle yí ge diànyǐng.","Tôi đã xem một bộ phim."]],"sides":{"白家月":"L","陈天中":"R"}},{"context":"Trên lớp, Vương Nhất Phi hỏi học sinh về tình hình học tập.","contextZh":"在课堂上，王一飞询问学生们的学习情况。","label":"14-2 · Cô giáo hỏi tình hình học tập","lines":[["王一飞","你们会说汉语了，也会写汉字了吗？","Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán chưa?"],["白家月","我们都会写了。","Wǒmen dōu huì xiě le.","Chúng em đều biết viết rồi ạ."],["陈天中","老师，我听不见。","Lǎoshī, wǒ tīng bú jiàn.","Cô ơi, em không nghe thấy."],["王一飞","请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","Mọi người đừng nói chuyện nữa! Hãy nghe câu hỏi của cô: các em đều biết viết những chữ Hán nào rồi?"],["陈天中","我会写这些字了，您看！","Wǒ huì xiě zhèxiē zì le, nín kàn!","Em biết viết những chữ này rồi, cô xem này!"]],"sides":{"王一飞":"L","白家月":"R","陈天中":"C"}},{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang bàn về việc học lên của các con.","contextZh":"在家里，刘明和王一雪在谈论孩子的升学情况。","label":"14-3 · Bàn chuyện con đi học","lines":[["刘明","明年女儿上中学。","Míngnián nǚ'ér shàng zhōngxué.","Sang năm con gái sẽ lên trung học."],["王一雪","对。儿子也上小学了。","Duì. Érzi yě shàng xiǎoxué le.","Đúng thế. Con trai cũng sẽ vào tiểu học."],["刘明","我们家有了一个中学生。","Wǒmen jiā yǒule yí ge zhōngxuéshēng.","Nhà mình sẽ có một học sinh trung học."],["王一雪","还有了一个小学生。","Hái yǒule yí ge xiǎoxuéshēng.","Còn có thêm một học sinh tiểu học nữa."],["刘明","上学后，他们都忙了。","Shàngxué hòu, tāmen dōu máng le.","Sau khi đi học, chúng nó đều sẽ bận."],["王一雪","是的。太晚了，睡觉吧。","Shì de. Tài wǎn le, shuìjiào ba.","Đúng thế. Muộn quá rồi, đi ngủ thôi."]],"sides":{"刘明":"L","王一雪":"R"}}],"15":[{"context":"Ở nhà Lý Văn, Lý Văn mời Trần Thiên Trung, Bạch Gia Nguyệt và các bạn nếm thử món ăn Trung Quốc.","contextZh":"在李文家，李文邀请陈天中、白家月等朋友品尝中餐。","label":"15-1 · Mời bạn ăn cơm Tàu","lines":[["李文","你们爱吃哪个菜？","Nǐmen ài chī nǎge cài?","Các bạn thích ăn món nào?"],["白家月","我喜欢这个，也喜欢那个。","Wǒ xǐhuan zhège, yě xǐhuan nàge.","Tôi thích món này, cũng thích món kia."],["陈天中","这些菜都好吃，还很好看。","Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","Những món này đều ngon, lại còn rất đẹp mắt."],["李文","我爱吃中国菜，也喜欢做。大家多吃点儿。","Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","Tôi thích ăn món Trung Quốc, cũng thích nấu. Mọi người ăn nhiều vào nhé."]],"sides":{"李文":"L","白家月":"R","陈天中":"C"}},{"context":"Ở nhà Lý Văn, mọi người vừa ăn cơm vừa bàn kế hoạch nghỉ lễ.","contextZh":"在李文家，大家边吃饭边谈论假期计划。","label":"15-2 · Bàn kế hoạch nghỉ lễ","lines":[["李文","你们都想去哪儿？","Nǐmen dōu xiǎng qù nǎr?","Các bạn đều muốn đi đâu?"],["安妮","去年我和男朋友去了西安，今年我想去北京。","Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","Năm ngoái tôi và bạn trai đã đi Tây An, năm nay tôi muốn đi Bắc Kinh."],["白家月","前几年我去了西安，非常好玩儿。今年我也想去北京。","Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","Mấy năm trước tôi đã đi Tây An, rất vui. Năm nay tôi cũng muốn đi Bắc Kinh."],["李文","我和王老师都是北京人，北京非常漂亮。","Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","Tôi và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp."]],"sides":{"安妮":"R","李文":"L","白家月":"C"}},{"context":"Ngoài lớp học, Bạch Gia Nguyệt, An Ni và cô Vương đang bàn chuyện đi du lịch Bắc Kinh.","contextZh":"在教室外，白家月、安妮和王老师在谈论去北京旅游的事。","label":"15-3 · Hẹn gặp ở sân bay Đại Hưng","lines":[["王一飞","你们的飞机到北京要几个小时？","Nǐmen de fēijī dào Běijīng yào jǐ ge xiǎoshí?","Máy bay của các em đến Bắc Kinh mất mấy tiếng?"],["白家月","九个小时。","Jiǔ ge xiǎoshí.","Chín tiếng ạ."],["王一飞","我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","Gia đình cô đều ở Bắc Kinh, chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô."],["安妮","我们星期日早上八点到大兴机场，早不早？","Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","Chúng em sáng chủ nhật 8 giờ đến sân bay Đại Hưng, có sớm quá không ạ?"],["王一飞","不早。","Bù zǎo.","Không sớm đâu."],["白家月","谢谢老师！那我们和您姐姐在大兴机场见！","Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","Cảm ơn cô ạ! Vậy chúng em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!"]],"sides":{"安妮":"C","王一飞":"L","白家月":"R"}}]};
